// Bootstrap, run-status, format utils, and plotly utils are in separate files.
// See: bootstrap.js, run-status.js, format-utils.js, plotly-utils.js, reload.js

function main() {
    initRunStatusBanner();
    initHelpToggles();

    let plots = [];
    let currentPlot = null;
    // Frequency convergence is the primary milestone; 'full'/'all_converged' are
    // verification only. Default to freq_converged (falls back to 'full' when a
    // loaded run has no frequency milestone — see updateStoppingCriteriaVisibility).
    let currentStoppingCriteria = 'freq_converged'; // 'full' | 'freq_converged' | 'all_converged'
    try {
        plots = window.MANIFEST;
        if (!Array.isArray(plots)) {
            throw new Error('Invalid manifest format');
        }
    } catch (error) {
        console.error('Error reading plots manifest from window.MANIFEST:', error);
        // Show an error message to the user
        const errorDiv = document.createElement('div');
        errorDiv.setAttribute('role', 'alert');
        errorDiv.style.padding = '20px';
        errorDiv.style.margin = '20px';
        errorDiv.style.border = '1px solid #f5c6cb';
        errorDiv.style.backgroundColor = '#f8d7da';
        errorDiv.style.color = '#721c24';
        errorDiv.style.borderRadius = '4px';
        errorDiv.innerHTML = '<h3>Error: Invalid data format</h3><p>Could not parse the plot data. The data might be corrupted or in an unexpected format.</p>';
        document.body.appendChild(errorDiv);
        return;
    }

    const settings = window.SETTINGS || {};
    const outDirDisplay = document.getElementById('out-dir-display');
    if (outDirDisplay && settings.out_dir) {
        outDirDisplay.textContent = `(${settings.out_dir})`;
    }

    const locatorResultsLink = document.querySelector('a[download][href="locator_results.csv"]');
    if (locatorResultsLink) {
        locatorResultsLink.href = resolveAssetPath('locator_results.csv');
    }

    plots.forEach((p) => {
        if (p && typeof p.path === 'string' && p.path.length > 0) {
            p.path = resolveAssetPath(p.path);
        }
    });

    const scanPlots = plots.filter((p) => p.type === 'scan');
    const bayesSection = document.getElementById('bayes-section-container');
    const bayesImage = document.getElementById('bayes-image');
    const bayesPlots = plots.filter((p) => p.type === 'bayesian');
    // New JSON-data types (generated by plots_data.py writers)
    const bayesPosteriorDataPlots = plots.filter((p) => p.type === 'bayesian_posterior_data');
    const bayesParamConvDataPlots = plots.filter((p) => p.type === 'bayesian_parameter_convergence_data');
    const bayesConvMetricsDataPlots = plots.filter((p) => p.type === 'bayesian_convergence_metrics_data');
    const bayesFisherDataPlots = plots.filter((p) => p.type === 'bayesian_fisher_data');
    // Legacy iframe types (kept for backward compatibility with cached runs)
    const bayesInteractivePlots = plots.filter((p) => p.type === 'bayesian_interactive');
    const bayesFisherPlots = plots.filter((p) => p.type === 'bayesian_fisher_information');
    const bayesFisherPairsPlots = plots.filter((p) => p.type === 'bayesian_fisher_crlb_pairs');
    const bayesEllipsePlots = plots.filter((p) => p.type === 'bayesian_covariance_ellipses_data');
    const bayesConvergencePlots = plots.filter((p) => p.type === 'bayesian_parameter_convergence');
    const bayesConvMetricsPlots = plots.filter((p) => p.type === 'bayesian_convergence_metrics');
    const bayesJitterPlots = plots.filter((p) => p.type === 'bayesian_jitter');

    const bayesInteractiveSection = document.getElementById('bayes-interactive-section');
    const bayesInteractiveIframe = document.getElementById('bayes-interactive-iframe');
    const bayesConvergenceSection = document.getElementById('bayes-convergence-section');
    const bayesConvergenceIframe = document.getElementById('bayes-convergence-iframe');
    const bayesConvMetricsIframe = document.getElementById('bayes-conv-metrics-iframe');
    const bayesFisherSection = document.getElementById('bayes-fisher-section');
    const bayesFisherIframe = document.getElementById('bayes-fisher-iframe');
    const bayesFisherPairsSection = document.getElementById('bayes-fisher-pairs-section');
    const bayesFisherPairsIframe = document.getElementById('bayes-fisher-pairs-iframe');
    const bayesCovarianceSection = document.getElementById('bayes-covariance-section');
    const bayesEllipseContainer = document.getElementById('bayes-ellipse-container');
    const bayesJitterContent = document.getElementById('bayes-jitter-content');
    const bayesStatsPlots = plots.filter((p) => p.type === 'bayesian_stats');
    const bayesStatsSection = document.getElementById('bayes-stats-section');
    const posteriorHistoryImage = document.getElementById('posterior-history-image');
    const convergenceStatsImage = document.getElementById('convergence-stats-image');
    const hasBayesArtifacts =
        bayesPlots.length > 0 ||
        bayesPosteriorDataPlots.length > 0 ||
        bayesInteractivePlots.length > 0 ||
        bayesParamConvDataPlots.length > 0 ||
        bayesConvMetricsDataPlots.length > 0 ||
        bayesFisherDataPlots.length > 0 ||
        bayesStatsPlots.length > 0 ||
        plots.some((p) => p.type === 'bayesian_parameter_convergence') ||
        plots.some((p) => p.type === 'bayesian_convergence_metrics') ||
        plots.some((p) => p.type === 'bayesian_fisher_bounds') ||
        plots.some((p) => p.type === 'bayesian_fisher_crlb_pairs') ||
        plots.some((p) => p.type === 'bayesian_jitter') ||
        plots.some((p) => p.type === 'bayesian_covariance_ellipses_data');
    // Global Timeline Controls Sync Controller
    const globalControls = document.getElementById('global-timeline-controls');
    const globalPlayBtn = document.getElementById('global-play-btn');
    const globalSlider = document.getElementById('global-range-slider');
    const noiseMetricsView = document.getElementById('noise-metrics-view');
    const globalLabel = document.getElementById('global-step-label');
    const globalSpeedSelect = document.getElementById('global-speed-select');

    let globalIsPlaying = false;
    let globalPlayInterval = null;
    let globalTotalFrames = 0;
    let globalStepValues = [];

    // Track registered iframes
    const activeIframes = new Set();

    function registerIframeForTimeline(iframe) {
        if (!iframe) return;

        function onIframeLoaded() {
            try {
                const win = iframe.contentWindow;
                if (win && win.showFrame && win.totalFrames !== undefined) {
                    activeIframes.add(iframe);
                    updateGlobalTimelineMetadata();
                } else {
                    let attempts = 0;
                    const poll = setInterval(() => {
                        attempts++;
                        if (win && win.showFrame && win.totalFrames !== undefined) {
                            activeIframes.add(iframe);
                            updateGlobalTimelineMetadata();
                            clearInterval(poll);
                        }
                        if (attempts > 30) clearInterval(poll);
                    }, 100);
                }
            } catch (e) {
                console.error("Timeline registration cross-origin error:", e);
            }
        }

        iframe.addEventListener('load', onIframeLoaded);
        onIframeLoaded();
    }

    function getStoppingFrameLimit() {
        if (!currentPlot || currentStoppingCriteria === 'full') return null;
        const m = currentPlot.metrics || {};
        if (currentStoppingCriteria === 'freq_converged' && m.freq_converged_step != null)
            return Math.max(0, m.freq_converged_step);
        if (currentStoppingCriteria === 'all_converged' && m.all_converged_step != null)
            return Math.max(0, m.all_converged_step);
        return null;
    }

    function applyStoppingFrameLimit() {
        if (globalTotalFrames === 0) return;
        const limit = getStoppingFrameLimit();
        const cap = limit != null ? Math.min(limit, globalTotalFrames - 1) : globalTotalFrames - 1;
        globalSlider.max = cap;
        const cur = parseInt(globalSlider.value, 10);
        if (cur > cap) {
            globalSlider.value = cap;
            syncFrames(cap);
        }
        updateGlobalLabel(parseInt(globalSlider.value, 10));
    }

    function updateGlobalTimelineMetadata() {
        let maxFrames = 0;
        let steps = [];
        for (const iframe of activeIframes) {
            try {
                const win = iframe.contentWindow;
                if (win && win.totalFrames > maxFrames) {
                    maxFrames = win.totalFrames;
                    if (win.stepValues && win.stepValues.length > 0) {
                        steps = win.stepValues;
                    }
                }
            } catch (e) { }
        }

        if (maxFrames > 0) {
            globalTotalFrames = maxFrames;
            globalStepValues = steps;
            globalSlider.max = maxFrames - 1;
            globalControls.style.display = 'flex';
            applyStoppingFrameLimit();
            syncFrames(parseInt(globalSlider.value, 10));
        } else {
            globalTotalFrames = 0;
            globalStepValues = [];
            globalControls.style.display = 'none';
            if (globalIsPlaying) {
                globalPause();
            }
        }
    }

    function updateGlobalLabel(idx) {
        const val = (globalStepValues && globalStepValues[idx] !== undefined) ? globalStepValues[idx] : idx;
        globalLabel.innerHTML = `Step: ${val} (${idx + 1} / ${globalTotalFrames})`;
    }

    function syncFrames(idx) {
        updateGlobalLabel(idx);
        for (const iframe of activeIframes) {
            try {
                const win = iframe.contentWindow;
                if (win && typeof win.showFrame === 'function') {
                    const localIdx = Math.min(idx, win.totalFrames - 1);
                    win.showFrame(localIdx);
                }
            } catch (e) { }
        }
    }

    globalSlider.addEventListener('input', (e) => {
        const idx = parseInt(e.target.value, 10);
        syncFrames(idx);
    });

    globalPlayBtn.addEventListener('click', () => {
        if (globalIsPlaying) {
            globalPause();
        } else {
            globalPlay();
        }
    });

    globalSpeedSelect.addEventListener('change', () => {
        if (globalIsPlaying) {
            globalPause();
            globalPlay();
        }
    });

    function globalPlay() {
        globalIsPlaying = true;
        globalPlayBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" style="display:inline-block; vertical-align:middle; margin-right:4px;"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg><span>Pause</span>';
        globalPlayBtn.style.background = '#ffebe6';
        globalPlayBtn.style.borderColor = '#ff4d4d';
        globalPlayBtn.style.color = '#960000';

        const intervalMs = parseInt(globalSpeedSelect.value, 10);
        globalPlayInterval = setInterval(() => {
            let nextIdx = parseInt(globalSlider.value, 10) + 1;
            if (nextIdx > parseInt(globalSlider.max, 10)) {
                nextIdx = 0;
            }
            globalSlider.value = nextIdx;
            syncFrames(nextIdx);
        }, intervalMs);
    }

    function globalPause() {
        globalIsPlaying = false;
        globalPlayBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" style="display:inline-block; vertical-align:middle; margin-right:4px;"><path d="M8 5v14l11-7z"/></svg><span>Play</span>';
        globalPlayBtn.style.background = '#e6f2ff';
        globalPlayBtn.style.borderColor = '#1e90ff';
        globalPlayBtn.style.color = '#005b96';

        clearInterval(globalPlayInterval);
    }

    function updateBayesView(selectedPlot) {
        if (!bayesSection || !bayesImage) {
            return;
        }

        if (!selectedPlot) {
            bayesImage.hidden = true;
            bayesImage.removeAttribute('src');
            return;
        }

        const bayesPlot = bayesPlots.find(
            (p) =>
                p.generator === selectedPlot.generator &&
                p.noise === selectedPlot.noise &&
                p.strategy === selectedPlot.strategy &&
                p.repeat === selectedPlot.repeat
        );

        if (!bayesPlot) {
            bayesImage.hidden = true;
            bayesImage.removeAttribute('src');
            return;
        }

        bayesImage.src = bayesPlot.path;
        bayesImage.hidden = false;
    }

    // Helper: get-or-create a div container for JSON-rendered plots inside a section.
    // The iframe is hidden when the div is used, and cleared when neither is available.
    function _jsonContainer(section, iframeEl, divId) {
        let div = document.getElementById(divId);
        if (!div) {
            div = document.createElement('div');
            div.id = divId;
            section.appendChild(div);
        }
        div.style.display = 'block';
        if (iframeEl) { iframeEl.style.display = 'none'; iframeEl.src = ''; }
        return div;
    }

    function _iframeContainer(section, iframeEl, divId, src) {
        const div = document.getElementById(divId);
        if (div) { div.style.display = 'none'; div.innerHTML = ''; }
        if (iframeEl) { iframeEl.style.display = ''; iframeEl.src = src; }
    }

    function _matchesSelected(p, sel) {
        return p.generator === sel.generator &&
               p.noise === sel.noise &&
               p.strategy === sel.strategy &&
               p.repeat === sel.repeat;
    }

    function updateBayesInteractiveView(selectedPlot) {
        if (!bayesInteractiveSection || !bayesInteractiveIframe) {
            return;
        }

        // Clear registered iframes/adapters and reset the slider
        activeIframes.clear();
        const ticksContainer = document.getElementById('timeline-ticks-container');
        if (ticksContainer) ticksContainer.innerHTML = '';
        globalTotalFrames = 0;
        globalStepValues = [];
        globalSlider.value = 0;
        globalSlider.max = 0;
        updateGlobalLabel(0);

        if (!selectedPlot) {
            bayesInteractiveSection.dataset.available = 'false';
            bayesInteractiveIframe.src = '';
            bayesConvergenceSection.dataset.available = 'false';
            bayesConvergenceIframe.src = '';
            bayesConvMetricsIframe.src = '';
            bayesFisherSection.dataset.available = 'false';
            bayesFisherIframe.src = '';
            bayesFisherPairsSection.dataset.available = 'false';
            bayesFisherPairsIframe.src = '';
            bayesCovarianceSection.dataset.available = 'false';
            bayesEllipseContainer.innerHTML = '';
            bayesJitterContent.innerHTML = '';
            ['bayes-posterior-container', 'bayes-conv-json-container',
             'bayes-conv-metrics-json-container', 'bayes-fisher-json-container'].forEach((id) => {
                const el = document.getElementById(id);
                if (el) { el.style.display = 'none'; el.innerHTML = ''; }
            });
            return;
        }

        // --- Posterior animation ---
        const posteriorDataPlot = bayesPosteriorDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const interactivePlot = bayesInteractivePlots.find((p) => _matchesSelected(p, selectedPlot));

        if (posteriorDataPlot) {
            const div = _jsonContainer(bayesInteractiveSection, bayesInteractiveIframe, 'bayes-posterior-container');
            bayesInteractiveSection.dataset.available = 'true';
            renderPosterior(div, posteriorDataPlot.path, (adapter) => {
                registerTimelineAdapter(adapter);
            });
        } else if (interactivePlot) {
            _iframeContainer(bayesInteractiveSection, bayesInteractiveIframe, 'bayes-posterior-container', interactivePlot.path);
            bayesInteractiveIframe.style.height = '85vh';
            bayesInteractiveSection.dataset.available = 'true';
            registerIframeForTimeline(bayesInteractiveIframe);
        } else {
            bayesInteractiveSection.dataset.available = 'false';
            bayesInteractiveIframe.src = '';
            bayesInteractiveIframe.style.height = '';
        }

        // --- Parameter convergence ---
        const paramConvDataPlot = bayesParamConvDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const convergencePlot = plots.find((p) => p.type === 'bayesian_parameter_convergence' && _matchesSelected(p, selectedPlot));
        const convMetricsDataPlot = bayesConvMetricsDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const convMetricsPlot = plots.find((p) => p.type === 'bayesian_convergence_metrics' && _matchesSelected(p, selectedPlot));

        if (paramConvDataPlot || convMetricsDataPlot) {
            bayesConvergenceSection.dataset.available = 'true';
            if (convMetricsDataPlot) {
                const topDiv = document.getElementById('bayes-conv-json-container');
                if (topDiv) topDiv.style.display = 'none';
                if (bayesConvergenceIframe) {
                    bayesConvergenceIframe.style.display = 'none';
                    bayesConvergenceIframe.src = '';
                }
                const div = _jsonContainer(bayesConvergenceSection, bayesConvMetricsIframe, 'bayes-conv-metrics-json-container');
                renderConvergenceMetrics(div, convMetricsDataPlot.path, (adapter) => {
                    registerTimelineAdapter(adapter);
                });
            } else {
                if (paramConvDataPlot) {
                    const div = _jsonContainer(bayesConvergenceSection, bayesConvergenceIframe, 'bayes-conv-json-container');
                    renderParameterConvergence(div, paramConvDataPlot.path, (adapter) => {
                        registerTimelineAdapter(adapter);
                    });
                } else {
                    _iframeContainer(bayesConvergenceSection, bayesConvergenceIframe, 'bayes-conv-json-container', convergencePlot ? convergencePlot.path : '');
                }
                _iframeContainer(bayesConvergenceSection, bayesConvMetricsIframe, 'bayes-conv-metrics-json-container', convMetricsPlot ? convMetricsPlot.path : '');
            }
        } else if (convergencePlot || convMetricsPlot) {
            bayesConvergenceSection.dataset.available = 'true';
            _iframeContainer(bayesConvergenceSection, bayesConvergenceIframe, 'bayes-conv-json-container', convergencePlot ? convergencePlot.path : '');
            _iframeContainer(bayesConvergenceSection, bayesConvMetricsIframe, 'bayes-conv-metrics-json-container', convMetricsPlot ? convMetricsPlot.path : '');
        } else {
            bayesConvergenceSection.dataset.available = 'false';
            bayesConvergenceIframe.src = '';
            bayesConvMetricsIframe.src = '';
        }

        // --- Fisher information ---
        const fisherDataPlot = bayesFisherDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const fisherPlot = plots.find((p) => p.type === 'bayesian_fisher_bounds' && _matchesSelected(p, selectedPlot));
        const fisherPairsPlot = plots.find((p) => p.type === 'bayesian_fisher_crlb_pairs' && _matchesSelected(p, selectedPlot));

        if (fisherDataPlot) {
            const div = _jsonContainer(bayesFisherSection, bayesFisherIframe, 'bayes-fisher-json-container');
            bayesFisherSection.dataset.available = 'true';
            bayesFisherPairsSection.dataset.available = 'false';
            bayesFisherPairsIframe.src = '';
            renderFisher(div, fisherDataPlot.path);
        } else if (fisherPlot) {
            _iframeContainer(bayesFisherSection, bayesFisherIframe, 'bayes-fisher-json-container', fisherPlot.path);
            bayesFisherSection.dataset.available = 'true';
            if (fisherPairsPlot) {
                bayesFisherPairsIframe.src = fisherPairsPlot.path;
                bayesFisherPairsSection.dataset.available = 'true';
            } else {
                bayesFisherPairsSection.dataset.available = 'false';
                bayesFisherPairsIframe.src = '';
            }
        } else {
            bayesFisherSection.dataset.available = 'false';
            bayesFisherIframe.src = '';
            bayesFisherPairsSection.dataset.available = 'false';
            bayesFisherPairsIframe.src = '';
        }

        // --- Covariance ellipses (already JSON-based) ---
        const ellipsePlot = plots.find((p) => p.type === 'bayesian_covariance_ellipses_data' && _matchesSelected(p, selectedPlot));
        if (ellipsePlot) {
            renderCovarianceEllipses(bayesEllipseContainer, ellipsePlot.path, (adapter) => {
                registerTimelineAdapter(adapter);
            });
        } else {
            bayesEllipseContainer.innerHTML = '';
        }

        // --- Jitter ---
        const jitterPlot = plots.find((p) => p.type === 'bayesian_jitter' && _matchesSelected(p, selectedPlot));
        if (jitterPlot && bayesJitterContent) {
            renderJitterView(bayesJitterContent, jitterPlot);
        } else if (bayesJitterContent) {
            bayesJitterContent.innerHTML = '';
        }

        if (ellipsePlot || jitterPlot) {
            bayesCovarianceSection.dataset.available = 'true';
        } else {
            bayesCovarianceSection.dataset.available = 'false';
        }
    }

    function updateBayesStatsView(selectedPlot) {
        if (!bayesStatsSection || !posteriorHistoryImage || !convergenceStatsImage) {
            return;
        }

        if (!selectedPlot) {
            bayesStatsSection.dataset.available = 'false';
            return;
        }

        const posteriorPlot = bayesStatsPlots.find(
            (p) =>
                p.kind === 'posterior_history' &&
                p.generator === selectedPlot.generator &&
                p.noise === selectedPlot.noise &&
                p.strategy === selectedPlot.strategy &&
                p.repeat === selectedPlot.repeat
        );

        const convergencePlot = bayesStatsPlots.find(
            (p) =>
                p.kind === 'convergence_stats' &&
                p.generator === selectedPlot.generator &&
                p.noise === selectedPlot.noise &&
                p.strategy === selectedPlot.strategy &&
                p.repeat === selectedPlot.repeat
        );

        if (posteriorPlot) {
            posteriorHistoryImage.src = posteriorPlot.path;
            posteriorHistoryImage.hidden = false;
        } else {
            posteriorHistoryImage.hidden = true;
        }

        if (convergencePlot) {
            convergenceStatsImage.src = convergencePlot.path;
            convergenceStatsImage.hidden = false;
        } else {
            convergenceStatsImage.hidden = true;
        }

        if (posteriorPlot || convergencePlot) {
            bayesStatsSection.dataset.available = 'true';
        } else {
            bayesStatsSection.dataset.available = 'false';
        }
    }



    function updateBayesTabs() {
        const tabBar = document.getElementById('bayes-tab-bar');
        if (!tabBar) return;

        const sections = [
            { id: 'bayes-interactive-section', label: 'Posterior Evolution' },
            { id: 'bayes-convergence-section', label: 'Convergence' },
            { id: 'bayes-fisher-section', label: 'Fisher Bounds' },
            { id: 'bayes-fisher-pairs-section', label: 'CRLB Pairs' },
            { id: 'bayes-covariance-section', label: 'Covariance' },
            { id: 'bayes-stats-section', label: 'Statistics' },
        ];

        const available = sections.filter((s) => {
            const el = document.getElementById(s.id);
            return el && el.dataset.available === 'true';
        });

        const bayesSectionContainer = document.getElementById('bayes-section-container');
        const noDataMsg = document.getElementById('bayes-no-data-message');

        if (bayesPlots.length === 0 && bayesInteractivePlots.length === 0 &&
                bayesPosteriorDataPlots.length === 0 && bayesParamConvDataPlots.length === 0 &&
                bayesConvMetricsDataPlots.length === 0 && bayesFisherDataPlots.length === 0 &&
                bayesEllipsePlots.length === 0 && bayesJitterPlots.length === 0) {
            if (bayesSectionContainer) bayesSectionContainer.style.display = 'none';
            return;
        } else if (bayesSectionContainer) {
            bayesSectionContainer.style.display = 'block';
        }

        if (available.length === 0) {
            tabBar.style.display = 'none';
            if (noDataMsg) noDataMsg.style.display = 'block';
        } else {
            tabBar.style.display = 'flex';
            if (noDataMsg) noDataMsg.style.display = 'none';
        }

        const currentActive = tabBar.querySelector('.bayes-tab-button.is-active');
        let activeId = currentActive ? currentActive.dataset.tab : null;
        if (!available.some((s) => s.id === activeId)) {
            activeId = available[0] ? available[0].id : null;
        }

        tabBar.innerHTML = '';
        for (const s of available) {
            const btn = document.createElement('button');
            btn.className = 'bayes-tab-button' + (s.id === activeId ? ' is-active' : '');
            btn.type = 'button';
            btn.textContent = s.label;
            btn.setAttribute("role", "tab");
            btn.setAttribute("aria-selected", s.id === activeId ? "true" : "false");
            btn.tabIndex = s.id === activeId ? 0 : -1;
            btn.setAttribute("aria-controls", s.id);
            btn.setAttribute("id", "tab-" + s.id);
            const panel = document.getElementById(s.id);
            if (panel) {
                panel.setAttribute("aria-labelledby", "tab-" + s.id);
            }
            btn.dataset.tab = s.id;
            btn.addEventListener('click', () => {
                tabBar.querySelectorAll('.bayes-tab-button').forEach((b) => {
                    b.classList.remove('is-active');
                    b.setAttribute("aria-selected", "false");
                    b.tabIndex = -1;
                });
                btn.setAttribute("aria-selected", "true");
                btn.tabIndex = 0;
                btn.classList.add('is-active');
                sections.forEach((sec) => {
                    const el = document.getElementById(sec.id);
                    if (el) el.classList.toggle('is-active', sec.id === s.id);
                });
                // Trigger a window resize event so responsive Plotly charts adjust to their visible containers
                setTimeout(() => {
                    window.dispatchEvent(new Event('resize'));
                }, 0);
                // Sync frames to refresh plots and active step line
                const currentIdx = parseInt(globalSlider.value, 10);
                if (!isNaN(currentIdx)) {
                    syncFrames(currentIdx);
                }
            });
            btn.addEventListener('keydown', (e) => {
                const buttons = Array.from(tabBar.querySelectorAll('.bayes-tab-button'));
                const index = buttons.indexOf(btn);
                let nextIndex = null;
                if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                    nextIndex = (index + 1) % buttons.length;
                } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                    nextIndex = (index - 1 + buttons.length) % buttons.length;
                }
                if (nextIndex !== null) {
                    e.preventDefault();
                    buttons[nextIndex].focus();
                    buttons[nextIndex].click();
                }
            });
            tabBar.appendChild(btn);
        }

        sections.forEach((s) => {
            const el = document.getElementById(s.id);
            if (el) el.classList.toggle('is-active', s.id === activeId);
        });
    }

    const scanDefault = scanPlots.length > 0 ? scanPlots[0] : null;

    const scanGenerator = document.getElementById('scan-generator');
    const scanGeneratorFlatRow = document.getElementById('scan-generator-flat-row');
    const scanGeneratorFamilyRow = document.getElementById('scan-generator-family-row');
    const scanGeneratorFamily = document.getElementById('scan-generator-family');
    const scanGeneratorFacetsRow = document.getElementById('scan-generator-facets-row');
    const scanGeneratorFacets = document.getElementById('scan-generator-facets');
    const scanNoise = document.getElementById('scan-noise');
    const scanStrategy = document.getElementById('scan-strategy');
    const scanRepeat = document.getElementById('scan-repeat');
    const scanRepeatPrev = document.getElementById('scan-repeat-prev');
    const scanRepeatNext = document.getElementById('scan-repeat-next');
    const scanIframe = document.getElementById('scan-iframe');
    const scanMetrics = document.getElementById('scan-metrics');
    const scanSweepMetrics = document.getElementById('scan-sweep-metrics');
    const gridStatsScanAxisSelect = document.getElementById('grid-stats-scan-axis');
    const gridStatsFixedSelects = document.getElementById('grid-stats-fixed-selects');
    const gridStatsPlotDiv = document.getElementById('grid-stats-plot-div');
    const gridStatsTableContainer = document.getElementById('grid-stats-table-container');
    const gridStatsEmptyMessage = document.getElementById('grid-stats-empty-message');
    let gridStatsScanAxisKey = null;
    let gridStatsFixedValues = {};
    let currentRepeatItems = [];
    let measurementDistributionVisible = null;
    let scanFlipViewEnabled = false;

    function isMeasurementDistributionTrace(trace) {
        const name = (trace && trace.name) ? String(trace.name).trim().toLowerCase() : '';
        return name === 'measurement distribution';
    }

    function resolveTraceVisibleState(value) {
        if (Array.isArray(value)) {
            if (value.length === 0) {
                return null;
            }
            return resolveTraceVisibleState(value[0]);
        }
        if (value === true) {
            return true;
        }
        if (value === false || value === 'legendonly') {
            return false;
        }
        return null;
    }

    function _getScanGraphDiv() {
        const scanPlotDiv = document.getElementById('scan-plot-div');
        if (scanPlotDiv && scanPlotDiv.style.display !== 'none' && scanPlotDiv.data) {
            return { graphDiv: scanPlotDiv, plotly: window.Plotly };
        }
        if (scanIframe && scanIframe.contentWindow && scanIframe.contentWindow.Plotly) {
            const fd = scanIframe.contentDocument;
            if (fd) {
                const gd = fd.querySelector('.plotly-graph-div');
                if (gd) return { graphDiv: gd, plotly: scanIframe.contentWindow.Plotly };
            }
        }
        return null;
    }

    function applyMeasurementDistributionPreferenceInScanIframe() {
        if (measurementDistributionVisible === null) return;
        const s = _getScanGraphDiv();
        if (!s || !Array.isArray(s.graphDiv.data)) return;
        const targetIndices = [];
        s.graphDiv.data.forEach((trace, idx) => {
            if (isMeasurementDistributionTrace(trace)) targetIndices.push(idx);
        });
        if (targetIndices.length === 0) return;
        const visibleValue = measurementDistributionVisible ? true : 'legendonly';
        s.plotly.restyle(s.graphDiv, { visible: visibleValue }, targetIndices);
    }

    function bindScanIframeLegendPreferenceSync() {
        const s = _getScanGraphDiv();
        if (!s) return;
        const graphDiv = s.graphDiv;
        if (graphDiv.dataset.measureDistListenerAttached === '1') return;
        graphDiv.dataset.measureDistListenerAttached = '1';
        graphDiv.on('plotly_restyle', (restyleData) => {
            if (!Array.isArray(restyleData) || restyleData.length < 2) return;
            const updates = restyleData[0] || {};
            const traceIndices = Array.isArray(restyleData[1]) ? restyleData[1] : [];
            if (!('visible' in updates) || traceIndices.length === 0 || !Array.isArray(graphDiv.data)) return;
            const visibleUpdate = updates.visible;
            for (const traceIdx of traceIndices) {
                const trace = graphDiv.data[traceIdx];
                if (!isMeasurementDistributionTrace(trace)) continue;
                const nextState = resolveTraceVisibleState(visibleUpdate);
                if (nextState !== null) measurementDistributionVisible = nextState;
                break;
            }
        });
    }


    function formatDuration(value) {
        if (typeof value === 'number' && Number.isFinite(value)) {
            const totalMs = value;
            const ms = Math.floor(totalMs % 1000);
            const totalSecs = Math.floor(totalMs / 1000);
            const secs = totalSecs % 60;
            const totalMins = Math.floor(totalSecs / 60);
            const mins = totalMins % 60;
            const hours = Math.floor(totalMins / 60);

            const msStr = ms.toString().padStart(3, '0');
            const secsStr = secs.toString().padStart(2, '0');
            const minsStr = mins.toString().padStart(2, '0');
            const hoursStr = hours.toString().padStart(2, '0');

            if (hours > 0) {
                return hoursStr + ':' + minsStr + ':' + secsStr + '.' + msStr;
            } else {
                return minsStr + ':' + secsStr + '.' + msStr;
            }
        }
        return 'N/A';
    }

    function formatTimestamp(isoString) {
        if (!isoString || typeof isoString !== 'string') {
            return 'N/A';
        }
        try {
            const d = new Date(isoString);
            if (Number.isNaN(d.getTime())) {
                return isoString;
            }
            return d.toLocaleString();
        } catch (e) {
            return isoString;
        }
    }

    function renderSweepMetricsPanel(container, metrics) {
        if (!container) return;
        container.innerHTML = '';
        if (metrics.sobol_baseline_steps != null && metrics.sobol_freq_steps != null && metrics.sobol_conv_diff == null) {
            metrics.sobol_conv_diff = metrics.sobol_baseline_steps - metrics.sobol_freq_steps;
        }
        // Build a displayable focus_window string from acquisition bounds,
        // but only for sweep locators that support focus (indicated by
        // the presence of expected_focused_points).
        if (metrics.expected_focused_points != null &&
            metrics.acquisition_lo != null && metrics.acquisition_hi != null) {
            const lo = Number(metrics.acquisition_lo);
            const hi = Number(metrics.acquisition_hi);
            if (Number.isFinite(lo) && Number.isFinite(hi)) {
                metrics.focus_window = '[' + lo.toExponential(3) + ', ' + hi.toExponential(3) + ']';
            }
        }
        const items = [
            { key: 'measurements_done', label: 'Measurements done', tip: 'Actual measurements taken before stopping or hitting the step limit.', fmt: formatCount },
            { key: 'dips_detected', label: 'Dips detected', tip: 'Dips found in the initial sweep after noise filtering. When the sweep is too sparse to detect dips, falls back to the true ground-truth dip count.', fmt: formatCount },
            { key: 'dips_merged', label: 'Dips merged', tip: 'Whether detected dips are close enough to be treated as one combined range.', fmt: function (v) { return v ? 'Yes' : 'No'; } },
            { key: 'min_dip_width', label: 'Dip width', tip: 'Width of the actual signal dip in physical frequency units.', fmt: formatFrequency },
            { key: 'total_signal_span', label: 'Signal span', tip: 'Total span from first dip start to last dip end in physical frequency units.', fmt: formatFrequency },
            { key: 'sweep_efficiency', label: 'Efficiency', tip: 'Expected uniform points / actual measurements. >1 means the locator was efficient.', fmt: formatMetricValue },
            { key: 'focus_window', label: 'Focus window', tip: 'Inferred frequency window the locator narrowed onto after detecting dips.', fmt: function (v) { return v; } },
        ];
        let any = false;
        for (const it of items) {
            const val = metrics[it.key];
            if (val == null || (typeof val === 'number' && !Number.isFinite(val))) continue;
            any = true;
            const el = document.createElement('div');
            el.className = 'metric-item';
            if (it.key === 'sweep_efficiency' && val != null) {
                if (val >= 1) {
                    el.classList.add('efficiency-good');
                } else if (val >= 0.5) {
                    el.classList.add('efficiency-medium');
                } else {
                    el.classList.add('efficiency-bad');
                }
            }
            let formula = '';
            if (it.key === 'sweep_efficiency' && metrics.expected_uniform_points != null && metrics.measurements_done != null) {
                formula = '<div class="metric-formula">' + formatCount(metrics.expected_uniform_points) + ' expected / ' + formatCount(metrics.measurements_done) + ' actual = ' + it.fmt(val) + '×</div>';
            }
            el.innerHTML =
                '<div class="metric-header">' +
                '<span class="metric-label">' + it.label + '</span>' +
                '<span class="help-icon" tabindex="0" title="' + it.tip.replace(/"/g, '&quot;') + '">?</span>' +
                '</div>' +
                '<div class="metric-value">' + it.fmt(val) + '</div>' + formula;
            container.appendChild(el);
        }
        container.hidden = !any;
    }


    // Parse plot data from scan file on-demand (handles lean data, .json.gz, and legacy .html)
    async function loadPlotDataFromScanHtml(plot) {
        if (!plot || !plot.path) return null;
        try {
            if (plot.path.endsWith('.json') || plot.path.endsWith('.json.gz')) {
                const raw = await _fetchJson(plot.path);
                if (raw && raw._graph_type === 'scan') {
                    // Lean scan data — return the plot_data subset as plain arrays
                    const pd = _decodePlotlyFigure(raw);  // already decoded; re-run is idempotent
                    const toPlainArr = (v) => ArrayBuffer.isView(v) ? Array.from(v) : v;
                    const plainMeas = (m) => {
                        if (!m || typeof m !== 'object') return { mode: 'empty' };
                        const r = { mode: m.mode };
                        for (const k of Object.keys(m)) {
                            if (k === 'mode') continue;
                            r[k] = ArrayBuffer.isView(m[k]) ? Array.from(m[k]) : m[k];
                        }
                        return r;
                    };
                    const out = {
                        x_dense: toPlainArr(raw.x_dense),
                        y_dense: toPlainArr(raw.y_dense),
                        has_metrics: !!raw.has_metrics,
                        measurements: plainMeas(raw.measurements),
                    };
                    if (raw.y_dense_noisy) out.y_dense_noisy = toPlainArr(raw.y_dense_noisy);
                    if (raw.y_dense_noisy_lo) out.y_dense_noisy_lo = toPlainArr(raw.y_dense_noisy_lo);
                    if (raw.y_dense_noisy_hi) out.y_dense_noisy_hi = toPlainArr(raw.y_dense_noisy_hi);
                    if (raw.y_dense_noisy_lo2) out.y_dense_noisy_lo2 = toPlainArr(raw.y_dense_noisy_lo2);
                    if (raw.y_dense_noisy_hi2) out.y_dense_noisy_hi2 = toPlainArr(raw.y_dense_noisy_hi2);
                    if (raw.y_dense_mode) out.y_dense_mode = toPlainArr(raw.y_dense_mode);
                    if (raw.focus_window) out.focus_window = Array.isArray(raw.focus_window) ? raw.focus_window : Array.from(raw.focus_window);
                    if (raw.narrowed_param_bounds) out.narrowed_param_bounds = raw.narrowed_param_bounds;
                    return out;
                }
                // Full Plotly figure (legacy) — extract from traces
                if (!raw || !Array.isArray(raw.data)) return null;
                const out = extractPlotDataFromTraces(raw.data);
                if (!out) return null;
                const meta = raw.layout && raw.layout.meta;
                if (meta && meta.narrowed_param_bounds && typeof meta.narrowed_param_bounds === 'object') {
                    out.narrowed_param_bounds = meta.narrowed_param_bounds;
                }
                return out;
            }
            const response = await fetch(resolveAssetPath(plot.path), { cache: 'no-store' });
            if (!response.ok) return null;
            const html = await response.text();
            return parsePlotDataFromHtml(html);
        } catch (e) {
            console.warn('Failed to load plot data from', plot.path, e);
            return null;
        }
    }

    function parsePlotDataFromHtml(html) {
        // Extract Plotly.newPlot data arrays + layout from HTML
        const m = html.match(/Plotly\.newPlot\(\s*"[^"]+",\s*/);
        if (!m) return null;
        const pos = m.index + m[0].length;
        try {
            const dataStr = html.slice(pos);
            // Find the end of the data array (first top-level array close)
            let depth = 0;
            let end = 0;
            for (let i = 0; i < dataStr.length; i++) {
                if (dataStr[i] === '[') depth++;
                else if (dataStr[i] === ']') {
                    depth--;
                    if (depth === 0) { end = i + 1; break; }
                } else if (dataStr[i] === '{' && depth === 0) {
                    // Started object before array - malformed
                    break;
                }
            }
            const data = JSON.parse(dataStr.slice(0, end));
            if (!Array.isArray(data)) return null;
            const out = extractPlotDataFromTraces(data);
            if (!out) return null;

            // Try to parse layout for narrowed_param_bounds in meta
            try {
                let layoutStart = pos + end;
                while (layoutStart < html.length && /[\s,]/.test(html[layoutStart])) layoutStart++;
                if (html[layoutStart] === '{') {
                    // find matching closing brace
                    let ldepth = 0, lend = 0;
                    for (let i = layoutStart; i < html.length; i++) {
                        if (html[i] === '{') ldepth++;
                        else if (html[i] === '}') {
                            ldepth--;
                            if (ldepth === 0) { lend = i + 1; break; }
                        }
                    }
                    if (lend > layoutStart) {
                        const layout = JSON.parse(html.slice(layoutStart, lend));
                        const meta = layout && layout.meta;
                        if (meta && meta.narrowed_param_bounds && typeof meta.narrowed_param_bounds === 'object') {
                            out.narrowed_param_bounds = meta.narrowed_param_bounds;
                        }
                    }
                }
            } catch (layoutErr) {
                // Non-critical: layout parse failures are silently ignored
            }
            return out;
        } catch (e) {
            console.warn('Failed to parse plot data from HTML:', e);
            return null;
        }
    }


    function extractPlotDataFromTraces(traces) {
        let x_dense = null, y_dense = null, y_dense_noisy = null, y_dense_mode = null;
        let coarse_x = [], coarse_y = [], secondary_x = [], secondary_y = [], tertiary_x = [], tertiary_y = [], fine_x = [], fine_y = [], fine_step = [];
        let step_x = [], step_y = [], step_idx = [];
        let has_metrics = false, focus_window = null;

        for (const tr of traces) {
            const name = tr.name || '';
            const mode = tr.mode || '';
            if ((name === 'locator most likely signal' || name === 'locator mode belief signal') && mode.includes('lines')) {
                y_dense_mode = tr.y;
            } else if (name === 'true signal' && mode.includes('lines')) {
                x_dense = tr.x;
                y_dense = tr.y;
            } else if (name === 'simulated noisy signal (over-frequency)' && mode.includes('lines')) {
                y_dense_noisy = tr.y?.map((v, i) => v != null ? v : (y_dense?.[i] || 0));
            } else if (name === 'measurements (coarse)') {
                coarse_x = tr.x || [];
                coarse_y = tr.y || [];
            } else if (name === 'measurements (secondary)') {
                secondary_x = tr.x || [];
                secondary_y = tr.y || [];
            } else if (name === 'measurements (tertiary)') {
                tertiary_x = tr.x || [];
                tertiary_y = tr.y || [];
            } else if (name === 'measurements (inference)') {
                fine_x = tr.x || [];
                fine_y = tr.y || [];
                fine_step = tr.marker?.color || fine_x.map((_, i) => i);
            } else if (name === 'measurements (noisy)') {
                step_x = tr.x || [];
                step_y = tr.y || [];
                step_idx = tr.marker?.color || step_x.map((_, i) => i);
            } else if (name === 'Entropy' || name === 'Uncertainty') {
                has_metrics = true;
            }
        }

        if (!x_dense || !y_dense) return null;

        const out = { x_dense, y_dense, has_metrics };
        if (y_dense_mode && y_dense_mode.length === x_dense.length) out.y_dense_mode = y_dense_mode;
        if (y_dense_noisy && y_dense_noisy.length === x_dense.length) out.y_dense_noisy = y_dense_noisy;

        if (coarse_x.length || secondary_x.length || tertiary_x.length || fine_x.length) {
            out.measurements = {
                mode: 'phases',
                coarse_x, coarse_y: coarse_y.map(y => y == null ? null : Number(y)),
                secondary_x, secondary_y: secondary_y.map(y => y == null ? null : Number(y)),
                tertiary_x, tertiary_y: tertiary_y.map(y => y == null ? null : Number(y)),
                fine_x, fine_y: fine_y.map(y => y == null ? null : Number(y)),
                fine_step: fine_step.map(s => Number(s))
            };
        } else if (step_x.length) {
            out.measurements = {
                mode: 'steps',
                x: step_x,
                y: step_y.map(y => y == null ? null : Number(y)),
                step: step_idx.map(s => Number(s))
            };
        } else {
            out.measurements = { mode: 'empty' };
        }

        return out;
    }


    // Fold a scan figure at the true center frequency: every trace is clipped to its
    // right half (x >= center), and the true-signal curve's left half is reflected
    // (x -> 2*center - x) and re-plotted as a dotted overlay on that same right-half
    // range, so Zeeman/hyperfine symmetry can be checked visually with the halves
    // superimposed instead of side by side. Fallback used when the signal has no
    // Zeeman splitting to split into two per-group subplots.
    function _foldScanFigureAtCenter(figData, figLayout, center) {
        if (!Array.isArray(figData) || !figData.length) return { data: figData, layout: figLayout };

        let lo = Infinity, hi = -Infinity;
        for (const t of figData) {
            if (!t.x || !t.x.length) continue;
            for (const v of t.x) {
                if (v == null || !Number.isFinite(v)) continue;
                if (v < lo) lo = v;
                if (v > hi) hi = v;
            }
        }
        if (!Number.isFinite(lo) || !Number.isFinite(hi)) return { data: figData, layout: figLayout };
        if (center === null || center === undefined) center = (lo + hi) / 2;

        const filterRight = (t) => {
            if (!t.x || !t.x.length) return t;
            const idx = [];
            for (let i = 0; i < t.x.length; i++) {
                const v = t.x[i];
                if (v != null && Number.isFinite(v) && v >= center) idx.push(i);
            }
            const pick = (arr) => (Array.isArray(arr) && arr.length === t.x.length) ? idx.map((i) => arr[i]) : arr;
            return Object.assign({}, t, { x: idx.map((i) => t.x[i]), y: pick(t.y), customdata: pick(t.customdata) });
        };

        const newData = figData.map(filterRight);

        // Mirror the true-signal curve's left half onto the right-half range.
        const trueTrace = figData.find((t) => t.name === 'true signal');
        if (trueTrace && trueTrace.x && trueTrace.x.length) {
            const pts = [];
            for (let i = 0; i < trueTrace.x.length; i++) {
                const v = trueTrace.x[i];
                if (v != null && Number.isFinite(v) && v < center) {
                    pts.push([2 * center - v, trueTrace.y[i]]);
                }
            }
            pts.sort((a, b) => a[0] - b[0]);
            if (pts.length) {
                newData.push({
                    type: 'scatter', mode: 'lines',
                    name: 'true signal (mirrored left half)',
                    x: pts.map((p) => p[0]), y: pts.map((p) => p[1]),
                    line: { color: 'blue', dash: 'dot', width: 1.5 },
                });
            }
        }

        const newLayout = Object.assign({}, figLayout, {
            xaxis: Object.assign({}, figLayout && figLayout.xaxis, { range: [center, hi] }),
        });
        return { data: newData, layout: newLayout };
    }

    // Window one trace's points to [lo, hi] and, if mirrorAbout is given, reflect
    // x -> 2*mirrorAbout - x (re-sorted by x) so a mirrored trace reads in the same
    // left-to-right orientation as its un-mirrored counterpart.
    function _windowAndMirrorTrace(t, lo, hi, mirrorAbout) {
        if (!t.x || !t.x.length) return null;
        const idx = [];
        for (let i = 0; i < t.x.length; i++) {
            const v = t.x[i];
            if (v != null && Number.isFinite(v) && v >= lo && v <= hi) idx.push(i);
        }
        if (!idx.length) return null;
        const pick = (arr) => (Array.isArray(arr) && arr.length === t.x.length) ? idx.map((i) => arr[i]) : arr;
        let xs = idx.map((i) => t.x[i]);
        let ys = pick(t.y);
        let cd = pick(t.customdata);
        if (mirrorAbout != null) {
            const hasCd = Array.isArray(cd) && cd.length === xs.length;
            const pts = xs.map((x, i) => [2 * mirrorAbout - x, ys[i], hasCd ? cd[i] : null]);
            pts.sort((a, b) => a[0] - b[0]);
            xs = pts.map((p) => p[0]);
            ys = pts.map((p) => p[1]);
            if (hasCd) cd = pts.map((p) => p[2]);
        }
        return Object.assign({}, t, { x: xs, y: ys, customdata: cd });
    }

    // Split a scan figure into two stacked subplots, one per Zeeman group (centered
    // at frequency +/- zeeman_split). The lower-frequency group has every trace
    // mirrored about its own center so both panels read in the same orientation and
    // can be visually compared for symmetry -- each panel keeps its own measurement
    // markers, so (unlike a single combined-overlay fold) you can see which specific
    // measurements landed in each group.
    function _splitScanFigureByZeemanGroup(figData, figLayout, center, zeemanSplit) {
        const hw = Math.abs(zeemanSplit) * 0.9;
        const c2 = center + zeemanSplit; // higher-frequency group, as-is
        const c1 = center - zeemanSplit; // lower-frequency group, mirrored about c1

        const topData = [];
        const bottomData = [];
        for (const t of figData) {
            // Skip metrics-row traces (entropy/uncertainty vs. step) -- not meaningful
            // windowed against a frequency range, and would collide with the x2/y2
            // axes reused below for the second Zeeman-group panel.
            if (t.xaxis === 'x2' || t.yaxis === 'y2') continue;

            const top = _windowAndMirrorTrace(t, c2 - hw, c2 + hw, null);
            if (top) topData.push(Object.assign({}, top, { xaxis: 'x', yaxis: 'y' }));

            const bottom = _windowAndMirrorTrace(t, c1 - hw, c1 + hw, c1);
            if (bottom) {
                bottomData.push(Object.assign({}, bottom, {
                    xaxis: 'x2', yaxis: 'y2',
                    name: bottom.name ? bottom.name + ' (mirrored)' : bottom.name,
                }));
            }
        }

        const newLayout = Object.assign({}, figLayout, {
            shapes: [],
            annotations: [],
            grid: { rows: 2, columns: 1, pattern: 'independent' },
            xaxis: Object.assign({}, figLayout && figLayout.xaxis, {
                domain: [0, 1], anchor: 'y', range: [c2 - hw, c2 + hw],
                title: { text: 'frequency — Zeeman group @ f0+' + formatFrequency(Math.abs(zeemanSplit)) },
            }),
            yaxis: Object.assign({}, figLayout && figLayout.yaxis, { domain: [0.55, 1], anchor: 'x' }),
            xaxis2: {
                domain: [0, 1], anchor: 'y2', range: [c1 - hw, c1 + hw],
                title: { text: 'frequency — Zeeman group @ f0-' + formatFrequency(Math.abs(zeemanSplit)) + ' (mirrored)' },
                tickformat: figLayout && figLayout.xaxis && figLayout.xaxis.tickformat,
            },
            yaxis2: Object.assign({}, figLayout && figLayout.yaxis, { domain: [0, 0.45], anchor: 'x2' }),
            height: 800,
        });

        return { data: topData.concat(bottomData), layout: newLayout };
    }

    // Dispatcher for the "Flip view" toggle: splits by Zeeman group when the true
    // signal has Zeeman splitting, otherwise falls back to the single center-fold.
    function _foldScanFigureForFlipView(figData, figLayout) {
        if (!Array.isArray(figData) || !figData.length) return { data: figData, layout: figLayout };
        const tp = figLayout && figLayout.meta && figLayout.meta.true_params && figLayout.meta.true_params.params;
        const center = tp && Number.isFinite(tp.frequency) ? tp.frequency : null;
        const zeemanSplit = tp && Number.isFinite(tp.zeeman_split) ? tp.zeeman_split : null;
        if (center !== null && zeemanSplit !== null && Math.abs(zeemanSplit) > 1e-9) {
            return _splitScanFigureByZeemanGroup(figData, figLayout, center, zeemanSplit);
        }
        return _foldScanFigureAtCenter(figData, figLayout, center);
    }

    async function renderPlotFromJson(container, jsonPath) {
        if (!jsonPath) { container.innerHTML = ''; return; }
        container._lastJsonPath = jsonPath;
        // Purge any pending Plotly operations on this container before replacing it.
        // Without this, an in-flight Plotly.restyle blocks the queue and subsequent
        // Plotly.react calls never execute.
        try { if (window.Plotly) Plotly.purge(container); } catch (_) {}
        // Tag this render so a stale fetch doesn't overwrite a newer one
        const renderToken = {};
        container._renderToken = renderToken;
        container.innerHTML = '<div style="padding:1.5em;color:#64748b;text-align:center;">Loading…</div>';
        try {
            await ensurePlotly();
            const raw = await _fetchJson(jsonPath);
            // Abort if a newer renderPlotFromJson started while we were fetching
            if (container._renderToken !== renderToken) return;

            // Convert TypedArrays (Float32Array etc.) to plain JS arrays for Plotly compatibility.
            // Required for fill="tonexty", customdata, marker.color, and other Plotly features
            // that don't accept typed arrays in all versions.
            const toPlain = (o) => {
                if (o === null || o === undefined) return o;
                if (ArrayBuffer.isView(o)) return Array.from(o);
                if (Array.isArray(o)) return o.map(toPlain);
                if (typeof o === 'object') {
                    const r = {};
                    for (const k of Object.keys(o)) r[k] = toPlain(o[k]);
                    return r;
                }
                return o;
            };

            let figData, figLayout;
            if (raw && raw._graph_type) {
                // Lean data file — build figure from static definition.
                // toPlain applied so builders receive plain arrays throughout.
                const built = await buildFigureFromData(toPlain(raw));
                figData = built.data;
                figLayout = Object.assign({}, built.layout, { autosize: true });
            } else {
                // Full Plotly figure (legacy or Bayesian) — render as-is
                const fig = toPlain(raw);
                figData = fig.data || [];
                figLayout = Object.assign({}, fig.layout || {}, { autosize: true });
            }

            if (container.id === 'scan-plot-div' && scanFlipViewEnabled && raw && raw._graph_type === 'scan') {
                const folded = _foldScanFigureForFlipView(figData, figLayout);
                figData = folded.data;
                figLayout = folded.layout;
            }

            // If this is a noise sweep summary plot, draw vertical reference line(s) for selected noise(s)
            const isSweepPlot = ['comp-iframe-summary-err-json-div', 'comp-iframe-summary-meas-json-div', 'comp-iframe-summary-savings-json-div'].includes(container.id);
            if (isSweepPlot) {
                const selectedNoises = getSelectedScanNoises();
                if (selectedNoises && selectedNoises.length) {
                    figLayout.shapes = figLayout.shapes || [];
                    selectedNoises.forEach(noiseVal => {
                        const exists = figLayout.shapes.some(s => s.type === 'line' && s.x0 === noiseVal);
                        if (!exists) {
                            figLayout.shapes.push({
                                type: 'line',
                                xref: 'x',
                                yref: 'paper',
                                x0: noiseVal,
                                x1: noiseVal,
                                y0: 0,
                                y1: 1,
                                line: {
                                    color: '#f43f5e',
                                    width: 2,
                                    dash: 'dash'
                                }
                            });
                        }
                    });
                }
            }

            // Plotly.react modifies DOM synchronously; don't await so a concurrent render
            // on the same container doesn't stall this one.
            Plotly.react(container, figData, figLayout, { responsive: true }).catch((e) => {
                console.error('Plotly.react failed for', jsonPath, e);
                if (container._renderToken === renderToken) {
                    container.innerHTML = `<div style="padding:1em;color:#ef4444;">Chart render error: ${e && e.message ? e.message : String(e)}</div>`;
                }
            });
            const isScanPlot = container.id === 'scan-plot-div';
            if (isScanPlot) {
                applyMeasurementDistributionPreferenceInScanIframe();
                bindScanIframeLegendPreferenceSync();
                renderNarrowedBoundsFromIframe();
            }
        } catch (e) {
            if (container._renderToken !== renderToken) return;
            console.warn('renderPlotFromJson failed for', jsonPath, e);
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load plot: ${e && e.message ? e.message : String(e)}</div>`;
        }
    }

    function _getOrCreateSiblingDiv(iframeEl) {
        if (!iframeEl) return null;
        const id = iframeEl.id + '-json-div';
        let div = document.getElementById(id);
        if (!div) {
            div = document.createElement('div');
            div.id = id;
            div.style.width = '100%';
            const h = iframeEl.style.height;
            if (h) div.style.height = h;
            iframeEl.parentNode.insertBefore(div, iframeEl);
        }
        return div;
    }

    function setPlotSrc(iframeEl, divElOrNull, path) {
        const divEl = divElOrNull !== undefined ? divElOrNull : _getOrCreateSiblingDiv(iframeEl);
        if (!path) {
            if (divEl) { divEl.style.display = 'none'; divEl.innerHTML = ''; }
            if (iframeEl) { iframeEl.style.display = 'none'; iframeEl.src = ''; }
            return;
        }
        if (path.endsWith('.json') || path.endsWith('.json.gz')) {
            if (iframeEl) { iframeEl.style.display = 'none'; iframeEl.src = ''; }
            if (divEl) { divEl.style.display = ''; renderPlotFromJson(divEl, path); }
        } else {
            if (divEl) { divEl.style.display = 'none'; divEl.innerHTML = ''; }
            if (iframeEl) { iframeEl.style.display = ''; iframeEl.src = path; }
        }
    }

    function addHeadToHeadMeasurementTraces(traces, m, label, side) {
        const cs = side === 'left' ? 'Oranges' : 'Purples';
        const symbol = side === 'left' ? 'circle' : 'diamond';
        if (!m || m.mode === 'empty') {
            return;
        }
        if (m.mode === 'phases') {
            const coarseColor = 'rgba(176,176,176,0.9)';
            const secondaryColor = 'rgba(255,127,14,0.9)';
            const tertiaryColor = 'rgba(148,0,211,0.9)';
            if (m.coarse_x && m.coarse_x.length) {
                traces.push({
                    type: 'scatter',
                    x: m.coarse_x,
                    y: m.coarse_y,
                    mode: 'markers',
                    name: `${label} (coarse)`,
                    marker: {
                        size: 7,
                        color: coarseColor,
                        symbol: symbol,
                        line: { width: 0.6, color: '#4a4a4a' },
                    },
                    hovertemplate: 'x=%{x}<br>y=%{y:.4f}<br>phase=initial sweep<extra></extra>',
                });
            }
            if (m.secondary_x && m.secondary_x.length) {
                traces.push({
                    type: 'scatter',
                    x: m.secondary_x,
                    y: m.secondary_y,
                    mode: 'markers',
                    name: `${label} (secondary)`,
                    marker: {
                        size: 7,
                        color: secondaryColor,
                        symbol: symbol,
                        line: { width: 0.6, color: '#8B4513' },
                    },
                    hovertemplate: 'x=%{x}<br>y=%{y:.4f}<br>phase=secondary sweep<extra></extra>',
                });
            }
            if (m.tertiary_x && m.tertiary_x.length) {
                traces.push({
                    type: 'scatter',
                    x: m.tertiary_x,
                    y: m.tertiary_y,
                    mode: 'markers',
                    name: `${label} (tertiary)`,
                    marker: {
                        size: 7,
                        color: tertiaryColor,
                        symbol: symbol,
                        line: { width: 0.6, color: '#4B0082' },
                    },
                    hovertemplate: 'x=%{x}<br>y=%{y:.4f}<br>phase=tertiary sweep<extra></extra>',
                });
            }
            if (m.fine_x && m.fine_x.length) {
                const fineSteps =
                    Array.isArray(m.fine_step) && m.fine_step.length === m.fine_x.length
                        ? m.fine_step
                        : m.fine_x.map((_, i) => i);
                const maxStep = Math.max(1, fineSteps.length - 1);
                const finePct = fineSteps.map((s) => (s / maxStep) * 100.0);
                traces.push({
                    type: 'scatter',
                    x: m.fine_x,
                    y: m.fine_y,
                    mode: 'markers',
                    name: `${label} (fine)`,
                    marker: {
                        size: 8,
                        color: fineSteps,
                        colorscale: cs,
                        showscale: false,
                        symbol: symbol,
                        line: { width: 0.5, color: '#222' },
                    },
                    customdata: finePct,
                    hovertemplate:
                        'x=%{x}<br>y=%{y:.4f}<br>inference step=%{marker.color}<br>inference progress=%{customdata:.1f}%<extra></extra>',
                });
            }
            return;
        }
        if (m.mode === 'steps') {
            traces.push({
                type: 'scatter',
                x: m.x,
                y: m.y,
                mode: 'markers',
                name: `${label} (measurements)`,
                marker: {
                    size: 8,
                    color: m.step,
                    colorscale: cs,
                    symbol: symbol,
                    line: { width: 0.5, color: '#222' },
                    showscale: false,
                },
            });
        }
    }

    function buildHeadToHeadFocusShapes(pdL, pdR) {
        const shapes = [];
        if (pdL.focus_window && pdL.focus_window.length === 2) {
            const x0 = pdL.focus_window[0];
            const x1 = pdL.focus_window[1];
            if (Number.isFinite(x0) && Number.isFinite(x1) && x1 > x0) {
                shapes.push({
                    type: 'rect',
                    xref: 'x',
                    yref: 'paper',
                    x0,
                    x1,
                    y0: 0,
                    y1: 1,
                    fillcolor: 'rgba(46, 204, 113, 0.12)',
                    line: { color: 'rgba(46, 204, 113, 0.45)', width: 1 },
                    layer: 'below',
                });
            }
        }
        if (pdR.focus_window && pdR.focus_window.length === 2) {
            const x0 = pdR.focus_window[0];
            const x1 = pdR.focus_window[1];
            if (Number.isFinite(x0) && Number.isFinite(x1) && x1 > x0) {
                shapes.push({
                    type: 'rect',
                    xref: 'x',
                    yref: 'paper',
                    x0,
                    x1,
                    y0: 0,
                    y1: 1,
                    fillcolor: 'rgba(59, 130, 246, 0.1)',
                    line: { color: 'rgba(59, 130, 246, 0.45)', width: 1, dash: 'dot' },
                    layer: 'below',
                });
            }
        }
        return shapes;
    }

    function buildHeadToHeadTraces(pdL, pdR, nameL, nameR) {
        const traces = [];
        traces.push({
            type: 'scatter',
            x: pdL.x_dense,
            y: pdL.y_dense,
            mode: 'lines',
            name: 'true signal',
            line: { color: '#2563eb', width: 2 },
        });
        if (
            pdL.y_dense_noisy_lo &&
            pdL.y_dense_noisy_lo.length &&
            pdL.y_dense_noisy_lo.length === pdL.x_dense.length
        ) {
            if (
                pdL.y_dense_noisy_lo2 &&
                pdL.y_dense_noisy_lo2.length === pdL.x_dense.length
            ) {
                traces.push({
                    type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_lo2, mode: 'lines',
                    line: { width: 0, color: 'rgba(100,100,100,0)' },
                    showlegend: false, hoverinfo: 'skip',
                });
                traces.push({
                    type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_hi2, mode: 'lines',
                    name: 'possible measurement range (±2σ)',
                    line: { width: 0, color: 'rgba(100,100,100,0)' },
                    fill: 'tonexty', fillcolor: 'rgba(100,100,100,0.15)',
                });
            }
            traces.push({
                type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_lo, mode: 'lines',
                line: { width: 0, color: 'rgba(100,100,100,0)' },
                showlegend: false, hoverinfo: 'skip',
            });
            traces.push({
                type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_hi, mode: 'lines',
                name: 'possible measurement range (±1σ)',
                line: { width: 0, color: 'rgba(100,100,100,0)' },
                fill: 'tonexty', fillcolor: 'rgba(100,100,100,0.30)',
            });
        } else if (
            pdL.y_dense_noisy &&
            pdL.y_dense_noisy.length &&
            pdL.y_dense_noisy.length === pdL.x_dense.length
        ) {
            traces.push({
                type: 'scatter',
                x: pdL.x_dense,
                y: pdL.y_dense_noisy,
                mode: 'lines',
                name: 'simulated noisy signal (over-frequency)',
                line: { color: '#fb923c', dash: 'dot', width: 1.5 },
            });
        }
        if (
            pdL.y_dense_mode &&
            pdL.y_dense_mode.length &&
            pdL.y_dense_mode.length === pdL.x_dense.length
        ) {
            traces.push({
                type: 'scatter',
                x: pdL.x_dense,
                y: pdL.y_dense_mode,
                mode: 'lines',
                name: nameL + ' (most likely)',
                line: { color: '#dc2626', dash: 'dash', width: 2 },
            });
        }
        if (
            pdR.y_dense_mode &&
            pdR.y_dense_mode.length &&
            pdR.y_dense_mode.length === pdR.x_dense.length
        ) {
            traces.push({
                type: 'scatter',
                x: pdR.x_dense,
                y: pdR.y_dense_mode,
                mode: 'lines',
                name: nameR + ' (most likely)',
                line: { color: '#9333ea', dash: 'dash', width: 2 },
            });
        }
        addHeadToHeadMeasurementTraces(traces, pdL.measurements, nameL, 'left');
        addHeadToHeadMeasurementTraces(traces, pdR.measurements, nameR, 'right');
        return traces;
    }

    function controlValue(control) {
        if (control instanceof HTMLSelectElement) {
            return control.value || control.dataset.value || '';
        }
        return control.dataset.value ?? '';
    }

    function setControlValue(control, value, { silent = false } = {}) {
        const normalized = value ?? '';
        control.dataset.value = normalized;
        const buttons = control.querySelectorAll('button');
        for (const button of buttons) {
            const isActive = button.dataset.value === normalized;
            button.classList.toggle('is-active', isActive);
            button.setAttribute('aria-checked', String(isActive));
            button.tabIndex = isActive ? 0 : -1;
        }
        if (!silent) {
            control.dispatchEvent(
                new CustomEvent('controlchange', {
                    bubbles: false,
                    detail: { value: normalized },
                }),
            );
        }
    }

    function renderSegmentedControl(control, items, previousValue, options = {}) {
        const disabledItems = options.disabledItems instanceof Set
            ? options.disabledItems
            : new Set(options.disabledItems || []);
        const uniqueItems = [
            ...new Set(
                items.filter((item) => item !== undefined && item !== null)
            ),
        ]
            .map((item) => String(item))
            .sort((a, b) => a.localeCompare(b));

        control.innerHTML = '';

        for (const item of uniqueItems) {
            const button = document.createElement('button');
            button.type = 'button';
            button.dataset.value = item;
            button.setAttribute('role', 'radio');
            button.setAttribute('aria-checked', 'false');
            button.tabIndex = -1;
            button.textContent = item;
            if (disabledItems.has(item)) {
                button.disabled = true;
                button.title = 'No scan data yet. Run this strategy with nvision run, then render.';
            }
            button.addEventListener('click', () => {
                if (button.disabled) {
                    return;
                }
                setControlValue(control, item);
            });
            button.addEventListener('keydown', (e) => {
                const buttons = Array.from(control.querySelectorAll('button'));
                const index = buttons.indexOf(button);
                let nextIndex = null;
                if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                    nextIndex = (index + 1) % buttons.length;
                } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                    nextIndex = (index - 1 + buttons.length) % buttons.length;
                }
                if (nextIndex !== null) {
                    e.preventDefault();
                    buttons[nextIndex].focus();
                    buttons[nextIndex].click();
                }
            });
            control.appendChild(button);
        }

        let nextValue = '';
        const enabledItems = uniqueItems.filter((item) => !disabledItems.has(item));
        if (enabledItems.length > 0) {
            if (previousValue && enabledItems.includes(previousValue)) {
                nextValue = previousValue;
            } else if (previousValue && uniqueItems.includes(previousValue)) {
                nextValue = enabledItems[0];
            } else {
                nextValue = enabledItems[0];
            }
        }

        setControlValue(control, nextValue, { silent: true });
        return nextValue;
    }

    function renderSelectControl(select, items, previousValue) {
        const uniqueItems = [
            ...new Set(items.filter((item) => item !== undefined && item !== null)),
        ]
            .map((item) => String(item))
            .sort((a, b) => Number(a) - Number(b));

        let nextValue = '';
        if (uniqueItems.length > 0) {
            if (previousValue && uniqueItems.includes(previousValue)) {
                nextValue = previousValue;
            } else {
                nextValue = uniqueItems[0];
            }
        }

        select.innerHTML = '';
        for (const item of uniqueItems) {
            const option = document.createElement('option');
            option.value = item;
            option.textContent = item;
            select.appendChild(option);
        }

        if (nextValue) {
            select.value = nextValue;
        } else {
            select.value = '';
        }
        select.dataset.value = nextValue;
        select.dataset.options = JSON.stringify(uniqueItems);
        return { value: nextValue, items: uniqueItems };
    }

    // Parse a generator name produced by a parameter-grid study (see
    // sim/presets.py's _fmt_sigma_inhom/_fmt_width/_fmt_contrast)
    // into its swept axes, so the UI can offer one dropdown per axis instead of a
    // flat list of opaque concatenated names. Returns null for non-grid generators
    // (e.g. bare "NVCenter-lorentzian").
    function parseGeneratorFacets(name) {
        let m = /^NVCenter-saturation_voigt-c([\d.]+)-si([\d.]+)MHz$/.exec(name);
        if (m) {
            return {
                family: 'saturation_voigt',
                familyLabel: 'Saturation-Voigt (contrast × sigma_inhom)',
                axes: [
                    { key: 'contrast', label: 'Contrast', value: Number(m[1]) },
                    { key: 'sigma_inhom', label: 'sigma_inhom (MHz)', value: Number(m[2]) },
                ],
            };
        }
        m = /^NVCenter-([a-zA-Z_]+)-w([\d.]+)MHz-c([\d.]+)-lf([\d.]+)$/.exec(name);
        if (m) {
            const variant = m[1];
            return {
                family: `${variant}_width_contrast_lorentzfrac`,
                familyLabel: `${variant} (width × contrast × inhom)`,
                axes: [
                    { key: 'width', label: 'Width (MHz)', value: Number(m[2]) },
                    { key: 'contrast', label: 'Contrast', value: Number(m[3]) },
                    { key: 'lorentz_frac', label: 'Inhom (lorentz_frac)', value: Number(m[4]) },
                ],
            };
        }
        m = /^NVCenter-([a-zA-Z_]+)-w([\d.]+)MHz-c([\d.]+)$/.exec(name);
        if (m) {
            const variant = m[1];
            return {
                family: `${variant}_width_contrast`,
                familyLabel: `${variant} (width × contrast)`,
                axes: [
                    { key: 'width', label: 'Width (MHz)', value: Number(m[2]) },
                    { key: 'contrast', label: 'Contrast', value: Number(m[3]) },
                ],
            };
        }
        return null;
    }

    // Group generator names into parameter-study "families" (same variant + same
    // swept axes) plus an "__ungrouped__" bucket for anything that doesn't parse
    // (e.g. bare default generators from a plain, non-grid run).
    function groupGeneratorsByFamily(items) {
        const families = new Map();
        const ungrouped = [];
        for (const name of items) {
            const parsed = parseGeneratorFacets(name);
            if (!parsed) {
                ungrouped.push(name);
                continue;
            }
            if (!families.has(parsed.family)) {
                families.set(parsed.family, { label: parsed.familyLabel, axes: parsed.axes.map((a) => a.key), members: [] });
            }
            families.get(parsed.family).members.push({ name, axisValues: parsed.axes });
        }
        return { families, ungrouped };
    }

    function axisDisplayValue(v) {
        return Number.isInteger(v) ? String(v) : String(Number(v.toFixed(4)));
    }

    // Per-family, per-axis selected values (as axisDisplayValue strings), keyed by
    // family key so a multi-selection survives the full facet re-render that
    // every axis change triggers (via scanGenerator's 'controlchange' -->
    // updateAllScanControls --> updateScanSignalControls --> this function again).
    // Without this store, that re-render would reseed each axis from the single
    // primary generator and silently collapse any multi-selection back to one.
    const facetSelectionStore = new Map();

    // Render one multi-select button group per axis for the given family (same
    // click/range UX as the noise selector), wired so that any axis's selection
    // recomputes the set of matching generator names. The primary (first) match
    // is pushed into the existing #scan-generator control (dataset.value +
    // 'controlchange') so single-generator consumers of controlValue(scanGenerator)
    // keep working unchanged; the full match set is exposed via
    // getSelectedScanGenerators() for consumers that compare across values.
    function renderGeneratorFacetSelects(familyGroup, previousGeneratorName, familyKey) {
        const axisMeta = familyGroup.members[0].axisValues.map((a) => ({ key: a.key, label: a.label }));
        if (!facetSelectionStore.has(familyKey)) facetSelectionStore.set(familyKey, {});
        const store = facetSelectionStore.get(familyKey);
        const prevMember = familyGroup.members.find((m) => m.name === previousGeneratorName);

        function computeMatches() {
            return familyGroup.members.filter((m) =>
                axisMeta.every((meta) => {
                    const sel = store[meta.key];
                    if (!sel || sel.size === 0) return false;
                    return sel.has(axisDisplayValue(m.axisValues.find((a) => a.key === meta.key).value));
                }),
            );
        }

        function applySelection(options = {}) {
            const matches = computeMatches();
            const effective = matches.length ? matches : [familyGroup.members[0]];
            scanGeneratorFacets.dataset.selectedGenerators = JSON.stringify(effective.map((m) => m.name));
            setControlValue(scanGenerator, effective[0].name, options);
        }

        scanGeneratorFacets.innerHTML = '';
        for (const meta of axisMeta) {
            const wrapper = document.createElement('span');
            wrapper.className = 'facet-select-wrapper';
            const label = document.createElement('label');
            label.textContent = `${meta.label}: `;
            label.className = 'facet-select-label';

            const values = [...new Set(familyGroup.members.map((m) => m.axisValues.find((a) => a.key === meta.key).value))]
                .sort((a, b) => a - b)
                .map(axisDisplayValue);

            let seed = store[meta.key] ? [...store[meta.key]].filter((v) => values.includes(v)) : [];
            if (!seed.length) {
                const prevAxis = prevMember && axisDisplayValue(prevMember.axisValues.find((a) => a.key === meta.key).value);
                seed = prevAxis && values.includes(prevAxis) ? [prevAxis] : [values[0]];
            }

            const btnGroup = document.createElement('span');
            btnGroup.setAttribute('aria-label', meta.label);
            renderMultiSelectButtonControl(btnGroup, values, seed, (a, b) => Number(a) - Number(b));
            store[meta.key] = new Set(JSON.parse(btnGroup.dataset.selectedValues || '[]'));

            btnGroup.addEventListener('controlchange', () => {
                store[meta.key] = new Set(JSON.parse(btnGroup.dataset.selectedValues || '[]'));
                // Apply silently -- setting scanGenerator's value with a dispatched
                // 'controlchange' would trigger updateAllScanControls(), which calls
                // this function again and rebuilds every axis's buttons (a fresh
                // control has no _rangeAnchor), wiping the anchor before a second
                // click can complete a range gesture. Instead, run only the narrower
                // refresh (noise items + downstream controls) that a facet change
                // actually needs; the full facet rebuild is reserved for family
                // switches and other paths that go through scanGenerator directly.
                applySelection({ silent: true });
                lastComparePairIds = { a: null, b: null };
                lastSummaryKey = null;
                refreshScanNoiseControlForSelectedGenerators();
                updateNoiseViewMode();
                updateScanStrategyControl();
                updateScanRepeatControl();
                findAndDisplayPlot();
            });

            label.appendChild(btnGroup);
            wrapper.appendChild(label);
            scanGeneratorFacets.appendChild(wrapper);
        }

        // Initial render: set state without dispatching 'controlchange' (mirrors
        // renderSegmentedControl's own silent initial setControlValue) -- avoids a
        // reentrant updateScanSignalControls() call on every render, not just on
        // user-driven changes.
        applySelection({ silent: true });
    }

    // ── Grid Stats: pick a scan axis, hold the rest fixed, view censored stats ──
    // Pure client-side exploration of already-run repeats (no new simulation runs).
    // Mirrors the censored aggregation in nvision/viz/grid_study.py's _cell_stats /
    // _plot_grid_vs_noise: group by the chosen scan axis, compute median/IQR of
    // freq_converged_step over converged repeats only, plus convergence_rate.

    function updateGridStatsButton(generator) {
        const btn = document.getElementById('scan-view-grid-stats-btn');
        if (!btn) return;
        btn.style.display = parseGeneratorFacets(generator) ? '' : 'none';
    }

    // Returns { familyGroup, axes: [{key, label, values:[sorted numbers]}] } for the
    // generator's family, with a synthetic 'noise' axis appended when numeric
    // (Gaussian) noise data exists for the family. Returns null for non-grid generators.
    function _gridStatsAxisInfo(generator) {
        const parsed = parseGeneratorFacets(generator);
        if (!parsed) return null;
        const allGeneratorNames = [...new Set(scanPlots.map((p) => p.generator))];
        const { families } = groupGeneratorsByFamily(allGeneratorNames);
        const familyGroup = families.get(parsed.family);
        if (!familyGroup) return null;

        const axisMeta = familyGroup.members[0].axisValues.map((a) => ({ key: a.key, label: a.label }));
        const memberNames = new Set(familyGroup.members.map((m) => m.name));
        const axes = axisMeta.map((meta) => ({
            key: meta.key,
            label: meta.label,
            values: [...new Set(familyGroup.members.map((m) => m.axisValues.find((a) => a.key === meta.key).value))]
                .sort((a, b) => a - b),
        }));

        const noiseValues = [...new Set(
            scanPlots
                .filter((p) => memberNames.has(p.generator))
                .map((p) => noiseSigma(p.noise))
                .filter((v) => v !== null),
        )].sort((a, b) => a - b);
        if (noiseValues.length > 0) {
            axes.push({ key: 'noise', label: 'Noise σ', values: noiseValues });
        }

        return { familyGroup, axes };
    }

    // Censored aggregation over already-run repeats: filters scanPlots to the given
    // strategy and every fixed axis value, groups the rest by the scan axis, and
    // computes n_total/n_converged/median/q25/q75(freq_converged_step among converged)
    // plus convergence_rate — exactly mirroring grid_study.py's _cell_stats.
    function computeGridStatsSeries(info, strategy, scanAxisKey, fixedValues) {
        const memberByName = new Map(info.familyGroup.members.map((m) => [m.name, m]));

        function axisValueOf(axisKey, plot) {
            if (axisKey === 'noise') return noiseSigma(plot.noise);
            const member = memberByName.get(plot.generator);
            const found = member && member.axisValues.find((a) => a.key === axisKey);
            return found ? found.value : null;
        }

        const filtered = scanPlots.filter((p) => {
            if (p.type !== 'scan' || p.strategy !== strategy) return false;
            if (!memberByName.has(p.generator)) return false;
            for (const axis of info.axes) {
                if (axis.key === scanAxisKey) continue;
                if (axisValueOf(axis.key, p) !== fixedValues[axis.key]) return false;
            }
            return true;
        });

        const groups = new Map();
        for (const p of filtered) {
            const scanValue = axisValueOf(scanAxisKey, p);
            if (scanValue === null || scanValue === undefined) continue;
            if (!groups.has(scanValue)) groups.set(scanValue, []);
            groups.get(scanValue).push(p.freq_converged_step);
        }

        const sortedKeys = [...groups.keys()].sort((a, b) => a - b);
        const x = [], median = [], q25 = [], q75 = [], convergenceRate = [], nTotal = [], nConverged = [];
        for (const key of sortedKeys) {
            const steps = groups.get(key);
            const converged = hlSorted(steps.filter((s) => s !== null && s !== undefined));
            x.push(key);
            median.push(converged.length ? hlQuantileSorted(converged, 0.5) : null);
            q25.push(converged.length ? hlQuantileSorted(converged, 0.25) : null);
            q75.push(converged.length ? hlQuantileSorted(converged, 0.75) : null);
            nTotal.push(steps.length);
            nConverged.push(converged.length);
            convergenceRate.push(steps.length ? converged.length / steps.length : null);
        }
        return { x, median, q25, q75, convergenceRate, nTotal, nConverged };
    }

    // Renders an in-memory {_graph_type, ...} payload (no fetch) using the same
    // figure builders as the pre-computed plot files, mirroring the generic render
    // path used for fetched plots but skipping the fetch/typed-array-decode steps.
    async function renderChartPayload(container, raw) {
        try {
            await ensurePlotly();
            try { if (window.Plotly) Plotly.purge(container); } catch (_) {}
            const built = await buildFigureFromData(raw);
            const figLayout = Object.assign({}, built.layout, { autosize: true });
            await Plotly.react(container, built.data, figLayout, { responsive: true });
        } catch (e) {
            console.error('Grid stats chart render failed', e);
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Chart render error: ${e && e.message ? e.message : String(e)}</div>`;
        }
    }

    function renderGridStatsTable(container, axisLabel, series) {
        const table = document.createElement('table');
        table.style.cssText = 'border-collapse:collapse;font-size:0.85em;';
        const thead = table.createTHead();
        const hrow = thead.insertRow();
        for (const h of [axisLabel, 'N total', 'N converged', 'Convergence rate', 'Median steps', 'Q25', 'Q75']) {
            const th = document.createElement('th');
            th.textContent = h;
            th.style.cssText = 'text-align:right;padding:5px 10px;border-bottom:2px solid #e2e8f0;white-space:nowrap;color:#475569;font-weight:600;';
            if (h === axisLabel) th.style.textAlign = 'left';
            hrow.appendChild(th);
        }
        const tbody = table.createTBody();
        for (let i = 0; i < series.x.length; i++) {
            const row = tbody.insertRow();
            const cells = [
                axisDisplayValue(series.x[i]),
                String(series.nTotal[i]),
                String(series.nConverged[i]),
                series.convergenceRate[i] != null ? `${Math.round(series.convergenceRate[i] * 100)}%` : '—',
                series.median[i] != null ? String(Math.round(series.median[i])) : '—',
                series.q25[i] != null ? String(Math.round(series.q25[i])) : '—',
                series.q75[i] != null ? String(Math.round(series.q75[i])) : '—',
            ];
            cells.forEach((c, idx) => {
                const td = row.insertCell();
                td.textContent = String(c);
                td.style.cssText = 'text-align:right;padding:4px 10px;border-bottom:1px solid #f1f5f9;';
                if (idx === 0) td.style.textAlign = 'left';
            });
        }
        container.innerHTML = '';
        container.appendChild(table);
    }

    function renderGridStatsTab(generator, strategy) {
        if (!gridStatsScanAxisSelect || !gridStatsFixedSelects || !gridStatsPlotDiv) return;
        const info = _gridStatsAxisInfo(generator);
        if (!info) return;
        const { axes } = info;

        // Reset scan-axis choice if it's no longer valid (e.g. switched family).
        if (!gridStatsScanAxisKey || !axes.some((a) => a.key === gridStatsScanAxisKey)) {
            gridStatsScanAxisKey = axes[0].key;
        }

        // Seed fixed-value defaults from the current main-view selection so switching
        // into Grid Stats keeps context; keep prior choices when still valid.
        const parsedCurrent = parseGeneratorFacets(generator);
        const currentNoiseSigma = noiseSigma(getEffectiveScanNoise());
        for (const axis of axes) {
            if (gridStatsFixedValues[axis.key] !== undefined && axis.values.includes(gridStatsFixedValues[axis.key])) {
                continue;
            }
            let seed = axis.values[0];
            if (axis.key === 'noise' && currentNoiseSigma !== null && axis.values.includes(currentNoiseSigma)) {
                seed = currentNoiseSigma;
            } else if (parsedCurrent) {
                const match = parsedCurrent.axes.find((a) => a.key === axis.key);
                if (match && axis.values.includes(match.value)) seed = match.value;
            }
            gridStatsFixedValues[axis.key] = seed;
        }

        gridStatsScanAxisSelect.innerHTML = '';
        for (const axis of axes) {
            const opt = document.createElement('option');
            opt.value = axis.key;
            opt.textContent = axis.label;
            gridStatsScanAxisSelect.appendChild(opt);
        }
        gridStatsScanAxisSelect.value = gridStatsScanAxisKey;
        gridStatsScanAxisSelect.onchange = () => {
            gridStatsScanAxisKey = gridStatsScanAxisSelect.value;
            renderGridStatsTab(controlValue(scanGenerator), controlValue(scanStrategy));
        };

        gridStatsFixedSelects.innerHTML = '';
        for (const axis of axes) {
            if (axis.key === gridStatsScanAxisKey) continue;
            const wrapper = document.createElement('span');
            wrapper.className = 'facet-select-wrapper';
            const label = document.createElement('label');
            label.className = 'facet-select-label';
            label.textContent = `${axis.label}: `;
            const select = document.createElement('select');
            select.className = 'control-select';
            select.setAttribute('aria-label', axis.label);
            for (const v of axis.values) {
                const opt = document.createElement('option');
                opt.value = String(v);
                opt.textContent = axisDisplayValue(v);
                select.appendChild(opt);
            }
            select.value = String(gridStatsFixedValues[axis.key]);
            select.addEventListener('change', () => {
                gridStatsFixedValues[axis.key] = Number(select.value);
                renderGridStatsTab(controlValue(scanGenerator), controlValue(scanStrategy));
            });
            label.appendChild(select);
            wrapper.appendChild(label);
            gridStatsFixedSelects.appendChild(wrapper);
        }

        const series = computeGridStatsSeries(info, strategy, gridStatsScanAxisKey, gridStatsFixedValues);
        if (!series.x.length) {
            if (gridStatsEmptyMessage) gridStatsEmptyMessage.style.display = '';
            gridStatsPlotDiv.style.display = 'none';
            if (gridStatsTableContainer) gridStatsTableContainer.innerHTML = '';
            return;
        }
        if (gridStatsEmptyMessage) gridStatsEmptyMessage.style.display = 'none';
        gridStatsPlotDiv.style.display = '';

        const scanAxisMeta = axes.find((a) => a.key === gridStatsScanAxisKey);
        const payload = {
            _graph_type: 'chart',
            title: `Steps to freq. convergence vs ${scanAxisMeta.label} (${strategy})`,
            xaxis_title: scanAxisMeta.label,
            yaxis_title: 'Median steps to freq. convergence (converged repeats)',
            mode: 'lines+markers',
            series: [{
                name: 'median (IQR band)',
                x: series.x,
                y: series.median,
                q25: series.q25,
                q75: series.q75,
                convergence_rate: series.convergenceRate,
                n_total: series.nTotal,
                n_converged: series.nConverged,
            }],
        };
        renderChartPayload(gridStatsPlotDiv, payload);
        if (gridStatsTableContainer) {
            renderGridStatsTable(gridStatsTableContainer, scanAxisMeta.label, series);
        }
    }

    function updateRepeatNavButtons() {
        if (!scanRepeatPrev || !scanRepeatNext) {
            return;
        }
        if (currentRepeatItems.length === 0) {
            scanRepeatPrev.disabled = true;
            scanRepeatNext.disabled = true;
            return;
        }
        const currentValue = scanRepeat.value || currentRepeatItems[0] || '';
        const currentIndex = currentRepeatItems.indexOf(currentValue);
        const hasValidSelection = currentIndex !== -1;
        scanRepeatPrev.disabled = !hasValidSelection || currentIndex <= 0;
        scanRepeatNext.disabled = !hasValidSelection || currentIndex >= currentRepeatItems.length - 1;
    }

    function selectRepeatByIndex(index) {
        if (currentRepeatItems.length === 0) {
            return;
        }
        const clampedIndex = Math.max(0, Math.min(index, currentRepeatItems.length - 1));
        const nextValue = currentRepeatItems[clampedIndex];
        if (nextValue === undefined) {
            return;
        }
        scanRepeat.value = nextValue;
        scanRepeat.dataset.value = nextValue;
        updateRepeatNavButtons();
        findAndDisplayPlot();
    }

    function selectRepeatByOffset(offset) {
        if (currentRepeatItems.length === 0) {
            return;
        }
        const currentValue = scanRepeat.value || currentRepeatItems[0];
        let currentIndex = currentRepeatItems.indexOf(currentValue);
        if (currentIndex === -1) {
            currentIndex = 0;
        }
        const targetIndex = currentIndex + offset;
        if (targetIndex < 0 || targetIndex >= currentRepeatItems.length) {
            return;
        }
        selectRepeatByIndex(targetIndex);
    }

    // ── Noise range-select control ────────────────────────────────────────────
    // Click 1: sets the anchor (single selection, darker highlight).
    // Click 2 on a different button: selects the full range from anchor to here.
    // Hovering while an anchor is set previews the range.

    function _getNoiseSelectedSet(control) {
        try { return new Set(JSON.parse(control.dataset.selectedValues || '[]')); }
        catch { return new Set(); }
    }

    function _setNoiseSelected(control, values, { silent = false } = {}) {
        const valSet = new Set(values);
        control.dataset.selectedValues = JSON.stringify([...valSet]);
        for (const btn of control.querySelectorAll('button')) {
            const sel = valSet.has(btn.dataset.value);
            btn.classList.toggle('is-active', sel);
            btn.setAttribute('aria-checked', String(sel));
        }
        if (!silent) {
            control.dispatchEvent(new CustomEvent('controlchange', {
                bubbles: false, detail: { values: [...valSet] },
            }));
        }
    }

    function renderMultiSelectNoiseControl(control, items, previousValues) {
        return renderMultiSelectButtonControl(control, items, previousValues, (a, b) => {
            const ga = a.match(/Gauss\(([\d.]+)\)/);
            const gb = b.match(/Gauss\(([\d.]+)\)/);
            if (ga && gb) return parseFloat(ga[1]) - parseFloat(gb[1]);
            if (ga) return -1; if (gb) return 1;
            return a.localeCompare(b);
        });
    }

    // Generic multi-select button group with click = select-one, click-another =
    // commit contiguous range (same anchor/preview UX as the noise selector).
    // `sortFn` orders the buttons left-to-right; pass a numeric comparator when
    // items are numeric strings so range-select is contiguous in value order.
    function renderMultiSelectButtonControl(control, items, previousValues, sortFn) {
        const prev = Array.isArray(previousValues) ? previousValues : (previousValues ? [previousValues] : []);
        const uniqueItems = [...new Set(items.filter(Boolean).map(String))].sort(sortFn);

        control.innerHTML = '';
        control.setAttribute('role', 'group');
        control._rangeAnchor = null;

        for (const item of uniqueItems) {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.dataset.value = item;
            btn.setAttribute('role', 'checkbox');
            btn.setAttribute('aria-checked', 'false');
            btn.tabIndex = 0;
            btn.textContent = item;
            btn.className = 'noise-btn';

            btn.addEventListener('click', () => {
                const allBtns = [...control.querySelectorAll('button')];
                allBtns.forEach(b => b.classList.remove('is-range-preview'));

                if (!control._rangeAnchor) {
                    // First click: set anchor, select only this item
                    control._rangeAnchor = item;
                    allBtns.forEach(b => b.classList.toggle('is-range-anchor', b.dataset.value === item));
                    _setNoiseSelected(control, [item]);
                } else {
                    const ai = allBtns.findIndex(b => b.dataset.value === control._rangeAnchor);
                    const bi = allBtns.findIndex(b => b.dataset.value === item);
                    if (ai === bi) {
                        // Re-clicked the anchor — keep it as a fresh single-item anchor
                        return;
                    }
                    // Second click: commit range from anchor to here
                    const lo = Math.min(ai, bi), hi = Math.max(ai, bi);
                    const range = allBtns.slice(lo, hi + 1).map(b => b.dataset.value);
                    control._rangeAnchor = null;
                    allBtns.forEach(b => b.classList.remove('is-range-anchor'));
                    _setNoiseSelected(control, range);
                }
            });

            btn.addEventListener('mouseenter', () => {
                if (!control._rangeAnchor || item === control._rangeAnchor) return;
                const allBtns = [...control.querySelectorAll('button')];
                const ai = allBtns.findIndex(b => b.dataset.value === control._rangeAnchor);
                const bi = allBtns.findIndex(b => b.dataset.value === item);
                const lo = Math.min(ai, bi), hi = Math.max(ai, bi);
                allBtns.forEach((b, i) =>
                    b.classList.toggle('is-range-preview', i >= lo && i <= hi && !b.classList.contains('is-range-anchor'))
                );
            });

            btn.addEventListener('mouseleave', () => {
                if (!control._rangeAnchor) return;
                control.querySelectorAll('.is-range-preview').forEach(b => b.classList.remove('is-range-preview'));
            });

            control.appendChild(btn);
        }

        // Restore previous selection; keep valid items; fallback to first
        let nextValues = prev.filter(v => uniqueItems.includes(v));
        if (nextValues.length === 0 && uniqueItems.length > 0) nextValues = [uniqueItems[0]];
        _setNoiseSelected(control, nextValues, { silent: true });
        return nextValues;
    }

    function getSelectedScanNoises() {
        try { return JSON.parse(scanNoise.dataset.selectedValues || '[]').filter(Boolean); }
        catch { return []; }
    }

    function getEffectiveScanNoise() {
        const noises = getSelectedScanNoises();
        return noises[0] || '';
    }

    function isNoiseRangeMode() {
        return getSelectedScanNoises().length > 1;
    }

    // getSelectedScanGenerators: the full set of generators matched by the
    // Width/Contrast (or other parameter-grid axis) multi-select buttons.
    // Falls back to the single #scan-generator value for plain/ungrouped
    // generators, where there is no facet control.
    function getSelectedScanGenerators() {
        try {
            const stored = JSON.parse(scanGeneratorFacets.dataset.selectedGenerators || '[]');
            if (stored.length) return stored;
        } catch { /* fall through to single-value fallback */ }
        const v = controlValue(scanGenerator);
        return v ? [v] : [];
    }

    function isGeneratorRangeMode() {
        return getSelectedScanGenerators().length > 1;
    }

    // Generator argument the aggregate renderers (Speed/Accuracy/Failed Runs)
    // expect: an array in generator-range mode, otherwise the single value.
    function compareGeneratorsArg() {
        const gens = getSelectedScanGenerators();
        return gens.length > 1 ? gens : (gens[0] || '');
    }

    function updateNoiseViewMode() {
        const range = isNoiseRangeMode() || isGeneratorRangeMode();
        const singleBtn = document.getElementById('scan-view-single-btn');
        if (singleBtn) singleBtn.style.display = range ? 'none' : '';

        if (range) {
            const activeBtn = document.querySelector('#scan-view-mode button.is-active');
            if (activeBtn && activeBtn.dataset.value === 'single') {
                const speedBtn = document.querySelector('#scan-view-mode button[data-value="speed"]');
                if (speedBtn) speedBtn.click();
            }
        }
    }

    /** Left column: generator, noise (signal / experiment path).
     *
     * Parameter-grid studies (see sim/presets.py's saturation_voigt_param_grid_generators
     * / param_grid_generators) produce many generator names that only differ by their
     * swept-parameter values (e.g. "NVCenter-saturation_voigt-s5.00-si0.30MHz"). Scrolling
     * a flat list of ~25 such names is hard to navigate, so when the manifest contains a
     * parseable grid we offer one dropdown per swept axis instead. Falls back to the
     * original flat segmented-control for plain (non-grid) generators, and adds a "Study"
     * dropdown when both grid and non-grid generators are present in the same manifest
     * (e.g. an artifacts directory accumulated across multiple run types).
     */
    // forcedFamilyKey: when the user just changed the family <select> itself, its new
    // value must win over the family re-derived from the (not-yet-updated) previously
    // selected generator -- otherwise this same function's own re-render, triggered by
    // its onchange handler, would immediately revert the dropdown to the old family.
    function updateScanSignalControls(forcedFamilyKey = null) {
        const scanGeneratorItems = [...new Set(scanPlots.map((p) => p.generator))].sort();
        const { families, ungrouped } = groupGeneratorsByFamily(scanGeneratorItems);
        const familyKeys = [...families.keys()];
        const previousGenerator = controlValue(scanGenerator);

        let selectedScanGenerator;

        if (familyKeys.length === 0) {
            // No parseable grid families: original flat list.
            scanGeneratorFlatRow.style.display = '';
            scanGeneratorFamilyRow.style.display = 'none';
            scanGeneratorFacetsRow.style.display = 'none';
            scanGeneratorFacets.dataset.selectedGenerators = '[]';
            selectedScanGenerator = renderSegmentedControl(scanGenerator, scanGeneratorItems, previousGenerator);
        } else {
            const familyOptions = [
                ...familyKeys.map((key) => ({ key, label: families.get(key).label })),
                ...(ungrouped.length > 0 ? [{ key: '__ungrouped__', label: 'Default (ungrouped)' }] : []),
            ];
            const needsFamilyPicker = familyOptions.length > 1;

            scanGeneratorFlatRow.style.display = 'none';
            scanGeneratorFamilyRow.style.display = needsFamilyPicker ? '' : 'none';

            let selectedFamilyKey;
            if (needsFamilyPicker) {
                const prevParsed = parseGeneratorFacets(previousGenerator);
                const prevFamilyKey = prevParsed ? prevParsed.family : (ungrouped.includes(previousGenerator) ? '__ungrouped__' : null);
                scanGeneratorFamily.innerHTML = '';
                for (const opt of familyOptions) {
                    const option = document.createElement('option');
                    option.value = opt.key;
                    option.textContent = opt.label;
                    scanGeneratorFamily.appendChild(option);
                }
                const candidateKey = forcedFamilyKey ?? prevFamilyKey;
                selectedFamilyKey = candidateKey && familyOptions.some((o) => o.key === candidateKey)
                    ? candidateKey
                    : familyOptions[0].key;
                scanGeneratorFamily.value = selectedFamilyKey;
                scanGeneratorFamily.onchange = () => {
                    updateScanSignalControls(scanGeneratorFamily.value);
                    updateScanStrategyControl();
                    updateScanRepeatControl();
                    findAndDisplayPlot();
                };
            } else {
                selectedFamilyKey = familyOptions[0].key;
            }

            if (selectedFamilyKey === '__ungrouped__') {
                scanGeneratorFacetsRow.style.display = 'none';
                scanGeneratorFlatRow.style.display = '';
                scanGeneratorFacets.dataset.selectedGenerators = '[]';
                selectedScanGenerator = renderSegmentedControl(scanGenerator, ungrouped, previousGenerator);
            } else {
                scanGeneratorFacetsRow.style.display = '';
                // Only carry the previous generator's facet selections into the new
                // render when we're staying within the SAME family; switching families
                // should default to that family's first combination instead.
                const carryPrevious = !forcedFamilyKey || forcedFamilyKey === (parseGeneratorFacets(previousGenerator) || {}).family;
                renderGeneratorFacetSelects(families.get(selectedFamilyKey), carryPrevious ? previousGenerator : null, selectedFamilyKey);
                selectedScanGenerator = controlValue(scanGenerator);
            }
        }

        refreshScanNoiseControlForSelectedGenerators();
    }

    // Rebuilds the noise multi-select from whichever generators are currently
    // selected (single generator, or the full Width/Contrast facet match set).
    // Pulled out of updateScanSignalControls so a facet-only change can refresh
    // just the noise list without rebuilding the facet buttons themselves (see
    // the facet 'controlchange' handler in renderGeneratorFacetSelects).
    function refreshScanNoiseControlForSelectedGenerators() {
        const selectedGenSet = new Set(getSelectedScanGenerators());
        const noiseItems = [...new Set(
            scanPlots
                .filter((p) => selectedGenSet.has(p.generator))
                .map((p) => p.noise)
        )];

        const prev = getSelectedScanNoises();
        renderMultiSelectNoiseControl(scanNoise, noiseItems, prev.length ? prev : null);
    }

    function updateScanStrategyControl() {
        const selectedScanGenerator = controlValue(scanGenerator);
        const selectedScanNoise = getEffectiveScanNoise();
        const availableFromPlots = new Set(
            scanPlots
                .filter((p) => p.generator === selectedScanGenerator && p.noise === selectedScanNoise)
                .map((p) => p.strategy),
        );
        const gridStrategies =
            (window.STRATEGY_GRID && window.STRATEGY_GRID[selectedScanGenerator]) || [];
        const scanStrategyItems = [
            ...new Set([...gridStrategies, ...availableFromPlots]),
        ];
        const disabledItems = new Set(
            scanStrategyItems.filter((strategy) => !availableFromPlots.has(strategy)),
        );
        renderSegmentedControl(scanStrategy, scanStrategyItems, controlValue(scanStrategy), {
            disabledItems,
        });
    }

    function updateScanRepeatControl() {
        const selectedScanGenerator = controlValue(scanGenerator);
        const selectedScanNoise = getEffectiveScanNoise();
        const selectedScanStrategy = controlValue(scanStrategy);

        updateFailedRunsButton(compareGeneratorsArg(), compareNoisesArg());
        updateGridStatsButton(selectedScanGenerator);

        const scanRepeatItems = scanPlots
            .filter(
                (p) =>
                    p.generator === selectedScanGenerator &&
                    p.noise === selectedScanNoise &&
                    p.strategy === selectedScanStrategy &&
                    isSuccessRun(p)
            )
            .map((p) => String(p.repeat ?? p.attempt ?? 1));
        const { value: selectedRepeat, items: repeatItems } = renderSelectControl(
            scanRepeat,
            scanRepeatItems,
            controlValue(scanRepeat) || scanRepeat.dataset.value || '',
        );
        currentRepeatItems = repeatItems;
        if (selectedRepeat) {
            scanRepeat.dataset.value = selectedRepeat;
        }
        updateRepeatNavButtons();

        const viewToggleContainer = document.getElementById('scan-view-toggle-container');
        if (viewToggleContainer) {
            if (repeatItems.length > 0) {
                viewToggleContainer.style.display = 'flex';
            } else {
                viewToggleContainer.style.display = 'none';
                const singleBtn = document.querySelector('#scan-view-mode button[data-value="single"]');
                if (singleBtn) singleBtn.click();
            }
        }
    }

    function updateAllScanControls() {
        updateScanSignalControls();
        updateNoiseViewMode();
        updateScanStrategyControl();
        updateScanRepeatControl();
    }

    function findAndDisplayPlot() {
        const scanGeneratorValue = controlValue(scanGenerator);
        const scanNoiseValue = getEffectiveScanNoise();
        const scanStrategyValue = controlValue(scanStrategy);
        const scanRepeatValue = controlValue(scanRepeat);

        // In range mode the single-scan display is suppressed; view mode handles everything
        if (isNoiseRangeMode() || isGeneratorRangeMode()) {
            currentPlot = null;
            setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), null);
            if (scanMetrics) scanMetrics.innerHTML = '';
            if (scanSweepMetrics) scanSweepMetrics.hidden = true;
            const activeBtn = document.querySelector('#scan-view-mode button.is-active');
            if (activeBtn) showScanViewPanels(activeBtn.dataset.value);
            updateBayesTabs();
            return;
        }

        if (
            scanGeneratorValue &&
            scanNoiseValue &&
            scanStrategyValue &&
            scanRepeatValue
        ) {
            const repeatNumber = parseInt(scanRepeatValue, 10);
            const plot = scanPlots.find(
                (p) =>
                    p.generator === scanGeneratorValue &&
                    p.noise === scanNoiseValue &&
                    p.strategy === scanStrategyValue &&
                    p.repeat === repeatNumber
            );
            currentPlot = plot;
            setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), plot ? plot.path : null);
            if (plot) {
                function buildScanItems(phaseData, isOverall, totalMeasurements) {
                    const repeatTotal = plot.repeat_total ?? null;
                    const attemptLabel = repeatTotal
                        ? 'Attempt ' + plot.repeat + ' of ' + repeatTotal
                        : 'Attempt ' + plot.repeat;
                    // For sweep-only runs, phaseData.measurements is the authoritative total.
                    const fullMeasurements = phaseData.measurements != null ? phaseData.measurements : totalMeasurements;
                    const freqConvergedStep = phaseData.freq_converged_step != null ? phaseData.freq_converged_step : (phaseData.metrics && phaseData.metrics.freq_converged_step != null ? phaseData.metrics.freq_converged_step : null);
                    const allConvergedStep = phaseData.all_converged_step != null ? phaseData.all_converged_step : (phaseData.metrics && phaseData.metrics.all_converged_step != null ? phaseData.metrics.all_converged_step : null);

                    let phaseMeasurements = fullMeasurements;
                    let measurementsLabel = 'Measurements';
                    let measurementsTip = 'Total number of measurements (sweep + acquisition) taken in this repeat.';
                    if (currentStoppingCriteria === 'freq_converged' && freqConvergedStep != null) {
                        phaseMeasurements = freqConvergedStep;
                        measurementsLabel = 'Freq. converged @';
                        measurementsTip = 'Step at which frequency uncertainty first dropped below the convergence threshold.';
                    } else if (currentStoppingCriteria === 'all_converged' && allConvergedStep != null) {
                        phaseMeasurements = allConvergedStep;
                        measurementsLabel = 'Converged @';
                        measurementsTip = 'Step at which all tracked parameters first met the convergence threshold.';
                    }

                    const items = [
                        { label: 'Attempt', val: attemptLabel, tip: 'Which repeat attempt this scan corresponds to.' },
                        { label: measurementsLabel, val: formatCount(phaseMeasurements), tip: measurementsTip },
                    ];
                    if (freqConvergedStep != null && currentStoppingCriteria === 'full') {
                        items.push({ label: 'Freq. converged', val: formatCount(freqConvergedStep), tip: 'Step at which frequency uncertainty first dropped below the convergence threshold.' });
                    }
                    if (phaseData.steps_to_fb != null && freqConvergedStep == null) {
                        items.push({ label: 'Freq. converged', val: formatCount(phaseData.steps_to_fb), tip: 'Measurements taken until center frequency (fb) converged below threshold.' });
                    }
                    // Show total sweep steps (if any)
                    const sweepSteps = phaseData.sweep_steps;
                    if (sweepSteps != null && sweepSteps > 0) {
                        const sweepStr = phaseMeasurements != null && phaseMeasurements > 0
                            ? sweepSteps + '/' + phaseMeasurements
                            : String(sweepSteps);
                        items.push({ label: 'Sweep steps', val: sweepStr, tip: 'Measurements spent in the initial coarse/focused sweep phase.' });
                    }
                    if (phaseData.duration_ms != null) {
                        items.push({ label: 'Duration', val: formatDuration(phaseData.duration_ms), tip: 'Wall-clock time for this repeat.' });
                    }
                    if (phaseData.last_run != null) {
                        items.push({ label: 'Last run', val: formatTimestamp(phaseData.last_run), tip: 'Timestamp when this repeat was executed.' });
                    }
                    if (phaseData.abs_err_x != null) {
                        let cardClass = '';
                        if (phaseData.uncert != null) {
                            if (phaseData.abs_err_x > 2 * phaseData.uncert) {
                                cardClass = 'err-high-card';
                            } else if (phaseData.abs_err_x > phaseData.uncert) {
                                cardClass = 'err-medium-card';
                            }
                        }
                        items.push({
                            label: 'Abs error',
                            val: formatFrequency(phaseData.abs_err_x),
                            tip: 'Absolute frequency error vs ground truth. Lower is better.',
                            cardClass: cardClass
                        });
                    }
                    if (phaseData.uncert != null) {
                        items.push({ label: 'Uncertainty', val: formatFrequency(phaseData.uncert), tip: 'Final estimated standard deviation of the frequency estimate. Lower is better.' });
                    }

                    // Milestone metrics
                    if (phaseData.err_fb_at_milestone != null) {
                        items.push({ label: 'fb Err @ Milestone', val: formatFrequency(phaseData.err_fb_at_milestone), tip: 'Absolute error of center frequency at the moment of convergence.' });
                    }
                    if (phaseData.err_fc_at_milestone != null) {
                        items.push({ label: 'fc Err @ Milestone', val: formatFrequency(phaseData.err_fc_at_milestone), tip: 'Absolute error of splitting at the moment fb converged.' });
                    }
                    if (phaseData.err_fc_diff != null) {
                        items.push({ label: 'fc Err Gain', val: formatFrequency(phaseData.err_fc_diff), tip: 'Reduction in splitting error achieved by continuing after fb convergence.' });
                    }
                    return items;
                }



                function buildFreqConvergenceRows(phaseData) {
                    if (!phaseData) return [];
                    const metrics = phaseData.metrics || {};
                    const sobolFreqSteps = phaseData.sobol_freq_steps != null ? phaseData.sobol_freq_steps : metrics.sobol_freq_steps;
                    const stepsToFb = phaseData.steps_to_fb != null ? phaseData.steps_to_fb : metrics.steps_to_fb;
                    const uncertFb = phaseData.uncert_fb_at_milestone != null ? phaseData.uncert_fb_at_milestone : metrics.uncert_fb_at_milestone;
                    const errFb = phaseData.err_fb_at_milestone != null ? phaseData.err_fb_at_milestone : metrics.err_fb_at_milestone;
                    const sobolFreqUncert = phaseData.sobol_freq_uncert_at_conv != null ? phaseData.sobol_freq_uncert_at_conv : metrics.sobol_freq_uncert_at_conv;
                    const sobolFreqErr = phaseData.sobol_freq_err_at_conv != null ? phaseData.sobol_freq_err_at_conv : metrics.sobol_freq_err_at_conv;
                    const uncert = phaseData.uncert != null ? phaseData.uncert : metrics.uncert;
                    const absErr = phaseData.abs_err_x != null ? phaseData.abs_err_x : metrics.abs_err_x;

                    const freqStepsExpected = (sobolFreqSteps != null && stepsToFb != null && stepsToFb < sobolFreqSteps);
                    const sbedFreqErrExpected = (errFb != null && uncertFb != null && errFb < uncertFb);
                    const sobolFreqErrExpected = (sobolFreqErr != null && sobolFreqUncert != null && sobolFreqErr < sobolFreqUncert);
                    const uncertFbDiffExpected = (uncertFb != null && uncert != null && uncertFb - uncert > 0);
                    const errFbDiffExpected = (errFb != null && absErr != null && errFb - absErr > 0);

                    return [
                        // Row 1: Steps — sobol - sbed
                        [
                            { label: 'Sobol freq convergence', val: sobolFreqSteps != null ? formatCount(sobolFreqSteps) : 'N/A', tip: 'Steps needed for simple Sobol frequency uncertainty to drop below threshold.', cardClass: freqStepsExpected ? 'expected-card' : '' },
                            { label: 'Sbed freq convergence', val: stepsToFb != null ? formatCount(stepsToFb) : 'N/A', tip: 'Steps needed for Sbed frequency uncertainty to drop below threshold.', cardClass: freqStepsExpected ? 'expected-card' : '' },
                            { label: 'Freq convergence savings', val: (sobolFreqSteps != null && stepsToFb != null) ? formatCount(sobolFreqSteps - stepsToFb) : 'N/A', tip: 'Difference in steps needed for frequency convergence (positive = Sbed was faster).', cardClass: freqStepsExpected ? 'expected-card' : '' }
                        ],
                        // Row 2: Uncertainty — frequency - overall
                        [
                            { label: 'Sobol freq uncertainty', val: sobolFreqUncert != null ? formatFrequency(sobolFreqUncert) : 'N/A', tip: 'Uncertainty (standard deviation) of Sobol frequency estimate at the moment of convergence.', cardClass: sobolFreqErrExpected ? 'expected-card' : '' },
                            { label: 'Sbed freq uncertainty', val: uncertFb != null ? formatFrequency(uncertFb) : 'N/A', tip: 'Uncertainty (standard deviation) of Sbed frequency estimate at the moment of convergence.', cardClass: sbedFreqErrExpected ? 'expected-card' : '' },
                            { label: 'Freq uncert difference', val: (uncertFb != null && uncert != null) ? formatFrequency(uncertFb - uncert) : 'N/A', tip: 'Reduction in Sbed frequency uncertainty from freq-convergence milestone to final (positive = uncertainty decreased).', cardClass: uncertFbDiffExpected ? 'expected-card' : '' }
                        ],
                        // Row 3: Absolute Error — frequency - overall
                        [
                            { label: 'Sobol freq error', val: sobolFreqErr != null ? formatFrequency(sobolFreqErr) : 'N/A', tip: 'Absolute error of Sobol frequency estimate vs ground truth at the moment of convergence.', cardClass: sobolFreqErrExpected ? 'expected-card' : '' },
                            { label: 'Sbed freq error', val: errFb != null ? formatFrequency(errFb) : 'N/A', tip: 'Absolute error of Sbed frequency estimate vs ground truth at the moment of convergence.', cardClass: sbedFreqErrExpected ? 'expected-card' : '' },
                            { label: 'Freq error difference', val: (errFb != null && absErr != null) ? formatFrequency(errFb - absErr) : 'N/A', tip: 'Change in Sbed absolute frequency error from freq-convergence milestone to final (positive = error decreased, negative = error increased).', cardClass: errFbDiffExpected ? 'expected-card' : '' }
                        ]
                    ];
                }

                function buildComparisonRows(phaseData, plotContext) {
                    if (!phaseData) return [];
                    const metrics = phaseData.metrics || {};
                    const sobolBaseline = phaseData.sobol_baseline_steps != null ? phaseData.sobol_baseline_steps : metrics.sobol_baseline_steps;
                    const measurements = phaseData.measurements != null ? phaseData.measurements : metrics.measurements;

                    const uncert = phaseData.uncert != null ? phaseData.uncert : metrics.uncert;
                    const absErr = phaseData.abs_err_x != null ? phaseData.abs_err_x : metrics.abs_err_x;

                    // Sobol baseline final uncertainty and error
                    const sobolPlot = findSobolBaselineForPlot(plotContext);
                    const sobolOverallUncert = sobolPlot ? sobolPlot.uncert : (phaseData.sobol_freq_uncert_at_conv || metrics.sobol_freq_uncert_at_conv);
                    const sobolOverallErr = sobolPlot ? sobolPlot.abs_err_x : (phaseData.sobol_freq_err_at_conv || metrics.sobol_freq_err_at_conv);

                    const overallStepsExpected = (sobolBaseline != null && measurements != null && measurements < sobolBaseline);
                    const sbedOverallErrExpected = (absErr != null && uncert != null && absErr < uncert);
                    const sobolOverallErrExpected = (sobolOverallErr != null && sobolOverallUncert != null && sobolOverallErr < sobolOverallUncert);
                    const overallUncertDiffExpected = (sobolOverallUncert != null && uncert != null && sobolOverallUncert - uncert > 0);
                    const overallErrDiffExpected = (sobolOverallErr != null && absErr != null && sobolOverallErr - absErr > 0);

                    return [
                        // Row 1: Steps
                        [
                            { label: 'Sobol baseline', val: sobolBaseline != null ? formatCount(sobolBaseline) : 'N/A', tip: 'Measurements required by a simple Sobol sweep with Bayesian convergence to resolve this distribution.', cardClass: overallStepsExpected ? 'expected-card' : '' },
                            { label: 'Sbed overall steps', val: measurements != null ? formatCount(measurements) : 'N/A', tip: 'Total measurements taken during Sbed active locator run.', cardClass: overallStepsExpected ? 'expected-card' : '' },
                            { label: 'Overall savings', val: (sobolBaseline != null && measurements != null) ? formatCount(sobolBaseline - measurements) : 'N/A', tip: 'Difference in total measurements required for overall convergence between simple Sobol baseline and Sbed.', cardClass: overallStepsExpected ? 'expected-card' : '' }
                        ],
                        // Row 2: Uncertainty
                        [
                            { label: 'Sobol overall uncertainty', val: sobolOverallUncert != null ? formatFrequency(sobolOverallUncert) : 'N/A', tip: 'Final estimated standard deviation of Sobol baseline frequency estimate.', cardClass: sobolOverallErrExpected ? 'expected-card' : '' },
                            { label: 'Sbed overall uncertainty', val: uncert != null ? formatFrequency(uncert) : 'N/A', tip: 'Final estimated standard deviation of Sbed frequency estimate.', cardClass: sbedOverallErrExpected ? 'expected-card' : '' },
                            { label: 'Overall uncert difference', val: (sobolOverallUncert != null && uncert != null) ? formatFrequency(sobolOverallUncert - uncert) : 'N/A', tip: 'Difference in final frequency estimate uncertainty (positive = SBED was more confident).', cardClass: overallUncertDiffExpected ? 'expected-card' : '' }
                        ],
                        // Row 3: Absolute Error
                        [
                            { label: 'Sobol overall error', val: sobolOverallErr != null ? formatFrequency(sobolOverallErr) : 'N/A', tip: 'Final absolute frequency error of Sobol baseline.', cardClass: sobolOverallErrExpected ? 'expected-card' : '' },
                            { label: 'Sbed overall error', val: absErr != null ? formatFrequency(absErr) : 'N/A', tip: 'Final absolute frequency error of Sbed.', cardClass: sbedOverallErrExpected ? 'expected-card' : '' },
                            { label: 'Overall error difference', val: (sobolOverallErr != null && absErr != null) ? formatFrequency(sobolOverallErr - absErr) : 'N/A', tip: 'Difference in final absolute frequency error (positive = SBED was more accurate).', cardClass: overallErrDiffExpected ? 'expected-card' : '' }
                        ]
                    ];
                }

                function buildEarlyStopComparisonRows(phaseData) {
                    if (!phaseData) return [];
                    const metrics = phaseData.metrics || {};
                    
                    const measurements = phaseData.measurements != null ? phaseData.measurements : metrics.measurements;
                    const stepsToFb = phaseData.steps_to_fb != null ? phaseData.steps_to_fb : metrics.steps_to_fb;
                    
                    const uncert = phaseData.uncert != null ? phaseData.uncert : metrics.uncert;
                    const uncertFb = phaseData.uncert_fb_at_milestone != null ? phaseData.uncert_fb_at_milestone : metrics.uncert_fb_at_milestone;
                    
                    const absErr = phaseData.abs_err_x != null ? phaseData.abs_err_x : metrics.abs_err_x;
                    const errFb = phaseData.err_fb_at_milestone != null ? phaseData.err_fb_at_milestone : metrics.err_fb_at_milestone;

                    const earlyStopStepsExpected = (measurements != null && stepsToFb != null && stepsToFb < measurements);
                    const earlyStopUncertExpected = (uncert != null && uncertFb != null && uncert < uncertFb);
                    const earlyStopErrExpected = (absErr != null && errFb != null && absErr < errFb);

                    return [
                        // Row 1: Steps
                        [
                            { label: 'Sbed overall steps', val: measurements != null ? formatCount(measurements) : 'N/A', tip: 'Total measurements taken during Sbed active locator run.', cardClass: earlyStopStepsExpected ? 'expected-card' : '' },
                            { label: 'Sbed freq convergence', val: stepsToFb != null ? formatCount(stepsToFb) : 'N/A', tip: 'Steps needed for Sbed frequency uncertainty to drop below threshold.', cardClass: earlyStopStepsExpected ? 'expected-card' : '' },
                            { label: 'Early stopping savings', val: (measurements != null && stepsToFb != null) ? formatCount(measurements - stepsToFb) : 'N/A', tip: 'Measurements saved by stopping active locator immediately after frequency converges.', cardClass: earlyStopStepsExpected ? 'expected-card' : '' }
                        ],
                        // Row 2: Uncertainty
                        [
                            { label: 'Sbed final uncertainty', val: uncert != null ? formatFrequency(uncert) : 'N/A', tip: 'Final frequency estimate uncertainty (standard deviation) at locator termination.', cardClass: earlyStopUncertExpected ? 'expected-card' : '' },
                            { label: 'Sbed freq uncertainty', val: uncertFb != null ? formatFrequency(uncertFb) : 'N/A', tip: 'Frequency estimate uncertainty (standard deviation) at the moment fb converged.', cardClass: earlyStopUncertExpected ? 'expected-card' : '' },
                            { label: 'Freq to final uncert diff', val: (uncert != null && uncertFb != null) ? formatFrequency(uncertFb - uncert) : 'N/A', tip: 'Uncertainty reduction achieved by continuing to run from fb convergence until locator termination.', cardClass: earlyStopUncertExpected ? 'expected-card' : '' }
                        ],
                        // Row 3: Absolute Error
                        [
                            { label: 'Sbed final error', val: absErr != null ? formatFrequency(absErr) : 'N/A', tip: 'Final absolute frequency error vs ground truth at locator termination.', cardClass: earlyStopErrExpected ? 'expected-card' : '' },
                            { label: 'Sbed freq error', val: errFb != null ? formatFrequency(errFb) : 'N/A', tip: 'Absolute frequency error vs ground truth at the moment fb converged.', cardClass: earlyStopErrExpected ? 'expected-card' : '' },
                            { label: 'Freq to final error diff', val: (absErr != null && errFb != null) ? formatFrequency(errFb - absErr) : 'N/A', tip: 'Absolute error reduction achieved by continuing to run from fb convergence until locator termination.', cardClass: earlyStopErrExpected ? 'expected-card' : '' }
                        ]
                    ];
                }

                function renderRowsToHtml(rows) {
                    if (!rows || rows.length === 0) return '';
                    let html = '';
                    for (const row of rows) {
                        if (row && row.length > 0) {
                            html += '<div class="scan-metrics-panel" style="margin-bottom:0.5em;">' + renderItemsToHtml(row) + '</div>';
                        }
                    }
                    return html;
                }

                if (plot.coarse && plot.fine) {
                    const totalMeasurements = plot.measurements || (plot.coarse.measurements + plot.fine.measurements);
                    scanMetrics.className = 'scan-metrics-wrapper';
                    let html =
                        '<div style="margin-bottom:0.4em;font-weight:600;color:#334155;font-size:0.85em;">' + escapeHtml(plot.coarse.label) + '</div>' +
                        '<div class="scan-metrics-panel">' + renderItemsToHtml(buildScanItems(plot.coarse, false, totalMeasurements)) + '</div>' +
                        '<div style="margin-top:0.75em;margin-bottom:0.4em;font-weight:600;color:#334155;font-size:0.85em;">' + escapeHtml(plot.fine.label) + '</div>' +
                        '<div class="scan-metrics-panel">' + renderItemsToHtml(buildScanItems(plot.fine, true, totalMeasurements)) + '</div>';

                    if (plot.true_params) {
                        html += '<div style="margin-top:0.75em;margin-bottom:0.4em;font-weight:600;color:#334155;font-size:0.85em;">' + escapeHtml(plot.true_params.label) + '</div>' +
                            '<div class="scan-metrics-panel">' + renderItemsToHtml(buildTrueParamItems(plot.true_params, plot), true) + '</div>';
                    }
                    scanMetrics.innerHTML = html;
                    updateStoppingCriteriaVisibility(plot);
                    setupRepeatComparisonUI(plot);
                } else {
                    scanMetrics.className = 'scan-metrics-wrapper';
                    let html = '<div class="scan-metrics-panel">' + renderItemsToHtml(buildScanItems(plot, true)) + '</div>';
                    // Slim manifest: show phase breakdown from flat fields when available
                    if (plot.coarse_measurements != null && plot.fine_measurements != null) {
                        html += '<div class="scan-metrics-panel" style="margin-top:0.5em;font-size:0.85em;color:#64748b;">' +
                            '<span style="margin-right:1em;">Sweep: ' + formatCount(plot.coarse_measurements) + ' meas.</span>' +
                            '<span>Inference: ' + formatCount(plot.fine_measurements) + ' meas.</span></div>';
                    }

                    if (plot.true_params) {
                        html += '<div style="margin-top:0.75em;margin-bottom:0.4em;font-weight:600;color:#334155;font-size:0.85em;">' + escapeHtml(plot.true_params.label) + '</div>' +
                            '<div class="scan-metrics-panel">' + renderItemsToHtml(buildTrueParamItems(plot.true_params, plot), true) + '</div>';
                    }
                    scanMetrics.innerHTML = html;
                    updateStoppingCriteriaVisibility(plot);
                    setupRepeatComparisonUI(plot);
                }
                renderSweepMetricsPanel(scanSweepMetrics, plot.metrics || {});
                updateBayesView(plot);
                updateBayesStatsView(plot);
                updateBayesInteractiveView(plot);
                updateBayesTabs();
            } else {
                setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), null);
                scanMetrics.className = '';
                scanMetrics.innerHTML = '';
                const scanCmpSel = document.getElementById('scan-comparison-selector');
                if (scanCmpSel) scanCmpSel.innerHTML = '';
                const scanCmpCards = document.getElementById('scan-comparison-cards');
                if (scanCmpCards) scanCmpCards.innerHTML = '';
                if (scanSweepMetrics) { scanSweepMetrics.hidden = true; scanSweepMetrics.innerHTML = ''; }
                updateBayesView(null);
                updateBayesStatsView(null);
                updateBayesInteractiveView(null);
                updateBayesTabs();
            }
        } else {
            setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), null);
            scanMetrics.textContent = '';
            const scanCmpSel2 = document.getElementById('scan-comparison-selector');
            if (scanCmpSel2) scanCmpSel2.innerHTML = '';
            const scanCmpCards2 = document.getElementById('scan-comparison-cards');
            if (scanCmpCards2) scanCmpCards2.innerHTML = '';
            if (scanSweepMetrics) { scanSweepMetrics.hidden = true; scanSweepMetrics.innerHTML = ''; }
            updateBayesView(null);
            updateBayesStatsView(null);
            updateBayesInteractiveView(null);
            updateBayesTabs();
        }

        // Re-render the active Compare axis (if any) for the new selection.
        const activeViewModeBtn = document.querySelector('#scan-view-mode button.is-active');
        if (activeViewModeBtn && activeViewModeBtn.dataset.value !== 'single') {
            showScanViewPanels(activeViewModeBtn.dataset.value);
        }
        // Apply stopping-criteria cap to posterior animation after plot change
        applyStoppingFrameLimit();
    }

    function buildTrueParamItems(trueData, plot) {
        const items = [];
        const params = trueData.params || {};
        const bounds = trueData.bounds || {};
        // Preferred order for common parameters
        const preferred = ['frequency', 'linewidth', 'fwhm_total', 'split', 'dip_depth', 'k_np', 'lorentz_frac'];
        const keys = Object.keys(params).sort((a, b) => {
            const ia = preferred.indexOf(a);
            const ib = preferred.indexOf(b);
            if (ia !== -1 && ib !== -1) return ia - ib;
            if (ia !== -1) return -1;
            if (ib !== -1) return 1;
            return a.localeCompare(b);
        });

        for (const name of keys) {
            const val = params[name];
            const b = bounds[name];
            let label = name.replace(/_/g, ' ');
            // Capitalize first letter
            label = label.charAt(0).toUpperCase() + label.slice(1);

            let formatted = val;
            let fmtLo = b ? b[0] : null;
            let fmtHi = b ? b[1] : null;

            const lowName = name.toLowerCase();
            const isFreqLike = lowName.includes('freq') || lowName.includes('linewidth') || lowName.includes('split') || lowName === 'fwhm_total';

            if (typeof val === 'number') {
                if (isFreqLike) {
                    formatted = formatFrequency(val);
                    if (b) {
                        fmtLo = formatFrequency(b[0]);
                        fmtHi = formatFrequency(b[1]);
                    }
                } else if (lowName === 'dip_depth' || lowName === 'k_np' || lowName === 'lorentz_frac') {
                    formatted = val.toFixed(3);
                    if (b) {
                        fmtLo = b[0].toFixed(3);
                        fmtHi = b[1].toFixed(3);
                    }
                } else {
                    formatted = formatMetricValue(val);
                    if (b) {
                        fmtLo = formatMetricValue(b[0]);
                        fmtHi = formatMetricValue(b[1]);
                    }
                }
            }

            // Extract final estimate and milestone fb if available
            let finalEst = null;
            if (plot && plot.metrics) {
                finalEst = plot.metrics["final_est_" + name];
            }

            let fbAtMilestone = null;
            if (plot && plot.metrics && name === 'frequency') {
                fbAtMilestone = plot.metrics["fb_at_milestone"];
            }

            items.push({
                label: label,
                val: formatted,
                bounds: b,
                rawVal: val,
                fmtLo: fmtLo,
                fmtHi: fmtHi,
                name: name,
                finalEst: finalEst,
                fbAtMilestone: fbAtMilestone
            });

            // Derived magnetic field, shown right after zeeman_split (zeeman_split is
            // the Zeeman-group half-separation, i.e. gamma * B for the NV electron spin).
            if (name === 'zeeman_split' && typeof val === 'number' && Number.isFinite(val)) {
                const bTesla = zeemanSplitToMagneticFieldTesla(val);
                items.push({
                    label: 'Magnetic field',
                    val: formatMagneticField(bTesla),
                    bounds: null,
                    rawVal: bTesla,
                    fmtLo: null,
                    fmtHi: null,
                    name: 'magnetic_field',
                    finalEst: null,
                    fbAtMilestone: null
                });
            }
        }
        return items;
    }

    // ---- Covariance ellipse renderer (JS-native, from JSON data) ----

    function registerTimelineAdapter(adapter) {
        if (!adapter || !adapter.contentWindow) return;
        activeIframes.add(adapter);
        updateGlobalTimelineMetadata();
    }

    /**
     * Compute 2σ covariance ellipse points for a 2×2 sub-covariance,
     * centered at (cx, cy). Replicates the Python eigensystem approach exactly.
     */
    function computeEllipse(cov2d, cx, cy) {
        const std_i = Math.sqrt(Math.max(cov2d[0][0], 1e-30));
        const std_j = Math.sqrt(Math.max(cov2d[1][1], 1e-30));
        let rho = cov2d[0][1] / (std_i * std_j);
        if (!isFinite(rho)) rho = 0;
        rho = Math.max(-0.9999, Math.min(0.9999, rho));
        // Eigensystem of [[1, ρ], [ρ, 1]] — eigh returns ascending eigenvalues.
        // For ρ≥0:  λ_a=1-ρ (v_a=[1,-1]/√2),  λ_b=1+ρ (v_b=[1,1]/√2)
        // For ρ<0:  λ_a=1+ρ (v_a=[1, 1]/√2),   λ_b=1-ρ (v_b=[1,-1]/√2)
        const va = rho >= 0 ? [1 / Math.SQRT2, -1 / Math.SQRT2] : [1 / Math.SQRT2, 1 / Math.SQRT2];
        const vb = rho >= 0 ? [1 / Math.SQRT2,  1 / Math.SQRT2] : [1 / Math.SQRT2, -1 / Math.SQRT2];
        const a_half = 2 * Math.sqrt(Math.max(1 - Math.abs(rho), 0));
        const b_half = 2 * Math.sqrt(Math.max(1 + Math.abs(rho), 0));
        const N = 100;
        const xs = new Array(N + 1), ys = new Array(N + 1);
        for (let k = 0; k <= N; k++) {
            const theta = (2 * Math.PI * k) / N;
            const ex = a_half * Math.cos(theta);
            const ey = b_half * Math.sin(theta);
            // Rotate by eigenvector matrix (rot.T in Python notation)
            xs[k] = cx + (ex * va[0] + ey * vb[0]) * std_i;
            ys[k] = cy + (ex * va[1] + ey * vb[1]) * std_j;
        }
        return { x: xs, y: ys };
    }

    /**
     * Render covariance ellipses from a JSON data file.
     * Creates one independent Plotly chart per parameter pair, side by side.
     * Calls onReady(adapter) once rendering is done so the caller can register
     * the adapter with the global timeline.
     */
    async function renderCovarianceEllipses(container, jsonPath, onReady) {
        container.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;">Loading covariance data…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:2em;color:#ef4444;">Failed to load covariance data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'covariance_ellipses_v1' || !data.steps || !data.pairs) {
            container.innerHTML = '<div style="padding:2em;color:#64748b;">No covariance data available.</div>';
            return;
        }

        if (!container.isConnected) return;

        const { param_names, param_units, pairs, steps, true_params } = data;
        const nSteps = steps.length;

        await ensurePlotly();
        if (!container.isConnected) return;

        container.innerHTML = '';
        container.style.cssText = 'display:flex; gap:8px; flex-wrap:wrap; margin-top:8px;';

        const plotDivs = [];
        for (const [i, j] of pairs) {
            const pi = param_names[i];
            const pj = param_names[j];
            const piLabel = pi + (param_units[pi] || '');
            const pjLabel = pj + (param_units[pj] || '');

            const wrapper = document.createElement('div');
            wrapper.style.cssText = 'flex:1; min-width:220px; max-width:480px;';

            const titleEl = document.createElement('div');
            titleEl.style.cssText = 'text-align:center; font-size:0.78em; color:#64748b; font-weight:600; margin-bottom:2px;';
            titleEl.textContent = `${piLabel} vs ${pjLabel}`;
            wrapper.appendChild(titleEl);

            const plotDiv = document.createElement('div');
            wrapper.appendChild(plotDiv);
            container.appendChild(wrapper);
            plotDivs.push({ div: plotDiv, i, j, piLabel, pjLabel, pi, pj });
        }

        function updateJitterAndCorrelations(stepIdx) {
            const jitterContent = document.getElementById('bayes-jitter-content');
            if (!jitterContent) return;

            const idx = Math.max(0, Math.min(stepIdx, nSteps - 1));
            const step = steps[idx];
            const cov = step.covariance;

            const jitter = {};
            param_names.forEach(p => {
                const vals = [];
                for (let k = Math.max(0, idx - 19); k <= idx; k++) {
                    const m = steps[k].means[p];
                    if (m != null) vals.push(m);
                }
                if (vals.length > 0) {
                    const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
                    const sqDiffSum = vals.reduce((sum, v) => sum + (v - mean) * (v - mean), 0);
                    jitter[p] = Math.sqrt(sqDiffSum / vals.length);
                } else {
                    jitter[p] = 0;
                }
            });

            const variances = {};
            param_names.forEach((p, pIdx) => {
                variances[p] = cov[pIdx][pIdx];
            });

            const correlations = {};
            param_names.forEach((p1, idx1) => {
                correlations[p1] = {};
                param_names.forEach((p2, idx2) => {
                    const std1 = Math.sqrt(cov[idx1][idx1]);
                    const std2 = Math.sqrt(cov[idx2][idx2]);
                    const corr = (std1 * std2 > 0) ? cov[idx1][idx2] / (std1 * std2) : 0;
                    correlations[p1][p2] = Math.max(-1.0, Math.min(1.0, corr));
                });
            });

            const jitterItems = param_names.map(name => ({
                label: name,
                val: formatMetricValue(jitter[name]),
                tip: 'Standard deviation of estimates over last 20 steps (physical units).',
                rawVal: jitter[name]
            }));

            const varItems = param_names.map(name => ({
                label: name,
                val: formatMetricValue(variances[name]),
                rawVal: variances[name]
            }));

            let html = '<h4>Jitter (last 20 steps)</h4>';
            html += '<div class="jitter-cards" style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:1.5em;">' + renderItemsToHtml(jitterItems) + '</div>';

            html += '<h4>Variances (diag Σ)</h4>';
            html += '<div class="jitter-cards" style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:1.5em;">' + renderItemsToHtml(varItems) + '</div>';

            html += '<h4>Correlation Matrix <span class="help-icon" tabindex="0" title="Measures how tightly parameters are coupled. +1/-1 = perfect correlation; 0 = independent.">?</span></h4>';
            html += '<div class="correlation-table-wrapper"><table class="correlation-table">';
            html += '<thead><tr><th></th>' + param_names.map(n => `<th>${escapeHtml(n)}</th>`).join('') + '</tr></thead>';
            html += '<tbody>';
            for (const ni of param_names) {
                html += `<tr><th>${escapeHtml(ni)}</th>`;
                for (const nj of param_names) {
                    const val = (correlations[ni] && correlations[ni][nj] !== undefined) ? correlations[ni][nj] : 0;
                    let color, textColor;
                    if (ni === nj) {
                        color = 'rgba(71, 85, 105, 0.15)';
                        textColor = '#1e293b';
                    } else if (val > 0) {
                        color = `rgba(30, 144, 255, ${0.1 + 0.9 * val})`;
                        textColor = val > 0.4 ? '#ffffff' : '#1e3a8a';
                    } else {
                        color = `rgba(239, 68, 68, ${0.1 + 0.9 * Math.abs(val)})`;
                        textColor = Math.abs(val) > 0.4 ? '#ffffff' : '#7f1d1d';
                    }
                    html += `<td class="corr-cell" style="background-color:${color}; color:${textColor};">${val.toFixed(2)}</td>`;
                }
                html += '</tr>';
            }
            html += '</tbody></table></div>';

            jitterContent.innerHTML = html;
        }

        function updateEllipseStep(stepIdx) {
            const step = steps[Math.max(0, Math.min(stepIdx, nSteps - 1))];
            const cov = step.covariance;
            const means = step.means || {};
            const progress = stepIdx / Math.max(1, nSteps - 1);
            const alpha = 0.25 + 0.55 * progress;
            const fillColor = `rgba(0, 100, 200, ${(alpha * 0.6).toFixed(2)})`;
            const lineColor = `rgba(0, 100, 200, ${alpha.toFixed(2)})`;

            for (const { div, i, j, piLabel, pjLabel, pi, pj } of plotDivs) {
                const cov2d = [[cov[i][i], cov[i][j]], [cov[j][i], cov[j][j]]];
                const cx = (means[pi] != null) ? means[pi] : 0;
                const cy = (means[pj] != null) ? means[pj] : 0;
                const { x, y } = computeEllipse(cov2d, cx, cy);

                const traces = [{
                    type: 'scatter', x, y,
                    mode: 'lines',
                    line: { color: lineColor, width: 2 },
                    fill: 'toself',
                    fillcolor: fillColor,
                    hoverinfo: 'skip',
                    showlegend: false,
                }];

                if (true_params) {
                    const ti = true_params[pi], tj = true_params[pj];
                    if (ti != null && tj != null) {
                        traces.push({
                            type: 'scatter', x: [ti], y: [tj],
                            mode: 'markers',
                            marker: { symbol: 'x', color: 'red', size: 10, line: { color: 'red', width: 2 } },
                            name: 'True', showlegend: false,
                        });
                    }
                }

                const layout = {
                    template: 'plotly_white',
                    margin: { l: 55, r: 10, t: 10, b: 50 },
                    xaxis: { title: { text: piLabel, font: { size: 11 } }, autorange: true },
                    yaxis: { title: { text: pjLabel, font: { size: 11 } }, autorange: true },
                    height: 260,
                    hovermode: false,
                };

                Plotly.react(div, traces, layout, { displayModeBar: false });
            }

            // Dynamically update the tables cell states
            updateJitterAndCorrelations(stepIdx);
        }

        updateEllipseStep(0);

        const adapter = {
            contentWindow: {
                showFrame: updateEllipseStep,
                totalFrames: nSteps,
                stepValues: steps.map((_, k) => k),
            },
            addEventListener: () => {},
        };

        if (onReady) onReady(adapter);
    }

    // ---- End covariance ellipse renderer ----

    // ---- JSON-based render functions (posterior, convergence, Fisher) ----

    /** Weighted Gaussian KDE at nGrid evenly-spaced points over [lo, hi]. */
    function _weightedKDE(values, weights, lo, hi, nGrid) {
        const n = values.length;
        let wSum = 0;
        for (let i = 0; i < n; i++) wSum += weights[i];
        if (wSum <= 0 || n === 0) return { grid: [], kde: [] };

        let mean = 0;
        for (let i = 0; i < n; i++) mean += (weights[i] / wSum) * values[i];
        let variance = 0;
        for (let i = 0; i < n; i++) {
            const d = values[i] - mean;
            variance += (weights[i] / wSum) * d * d;
        }
        const sigma = Math.sqrt(Math.max(variance, 1e-30));
        const bw = Math.max(0.12 * sigma * Math.pow(n, -0.2), (hi - lo) * 1e-5);

        const grid = [], kde = [];
        const step = (hi - lo) / (nGrid - 1);
        const inv_bw_sqrt2pi = 1.0 / (bw * Math.sqrt(2 * Math.PI));
        const inv_bw = 1.0 / bw;
        for (let g = 0; g < nGrid; g++) {
            const x = lo + g * step;
            grid.push(x);
            let density = 0;
            for (let i = 0; i < n; i++) {
                const z = (x - values[i]) * inv_bw;
                density += (weights[i] / wSum) * Math.exp(-0.5 * z * z);
            }
            kde.push(density * inv_bw_sqrt2pi);
        }
        return { grid, kde };
    }

    async function renderPosterior(container, jsonPath, onReady) {
        container.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;">Loading posterior data…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:2em;color:#ef4444;">Failed to load posterior data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'posterior_v1' || !data.steps || !data.param_names) {
            container.innerHTML = '<div style="padding:2em;color:#64748b;">No posterior data available.</div>';
            return;
        }
        if (!container.isConnected) return;

        const { param_names, param_units, physical_bounds, true_params, resampled_steps, steps } = data;
        const nSteps = steps.length;
        const nParams = param_names.length;

        await ensurePlotly();
        if (!container.isConnected) return;

        container.innerHTML = '';
        
        // Setup Grid Wrapper Container (max 4 columns)
        const gridWrapper = document.createElement('div');
        gridWrapper.className = 'posterior-card-grid';
        container.appendChild(gridWrapper);

        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];
        const plotDivs = [];
        param_names.forEach((param, ci) => {
            const unit = param_units[param] ? ` (${param_units[param]})` : '';
            const wrapper = document.createElement('div');
            wrapper.className = 'posterior-card';
            
            const title = document.createElement('div');
            title.style.cssText = 'text-align:center; font-size:0.78em; color:#64748b; font-weight:600; margin-bottom:4px;';
            title.textContent = param + unit;
            wrapper.appendChild(title);
            
            const rowWrapper = document.createElement('div');
            rowWrapper.style.cssText = 'display: flex; gap: 8px; align-items: center; width: 100%;';
            
            const plotDiv = document.createElement('div');
            plotDiv.style.cssText = 'flex: 6.5; min-width: 0;';
            
            const uncDiv = document.createElement('div');
            uncDiv.style.cssText = 'flex: 3.5; min-width: 0;';
            
            rowWrapper.appendChild(plotDiv);
            rowWrapper.appendChild(uncDiv);
            wrapper.appendChild(rowWrapper);
            
            gridWrapper.appendChild(wrapper);
            
            // Calculate parameter uncertainty history across all steps
            const uncHistory = steps.map(s => (s[param] && s[param].uncertainty != null) ? s[param].uncertainty : null);
            const color = COLORS[ci % COLORS.length];
            
            plotDivs.push({ div: plotDiv, uncDiv: uncDiv, param, uncHistory, color });
        });

        // SMC Diagnostics plotting setup
        const diagnosticsContainer = document.getElementById('smc-diagnostics-container');
        const firstParam = param_names[0];
        const hasParticles = steps[0] && steps[0][firstParam] && steps[0][firstParam].type === 'particles';
        
        let essHistory = [];
        let thresholdVal = 0;
        let nParticles = 0;
        
        if (hasParticles && diagnosticsContainer) {
            diagnosticsContainer.style.display = 'block';
            nParticles = steps[0][firstParam].weights.length;
            const thresholdPct = data.ess_threshold != null ? data.ess_threshold : 0.2;
            thresholdVal = thresholdPct * nParticles;
            
            for (let s = 0; s < nSteps; s++) {
                const stepEntry = steps[s][firstParam];
                if (stepEntry && stepEntry.weights) {
                    const w = stepEntry.weights;
                    const wSum = w.reduce((a, b) => a + b, 0);
                    const normW = wSum > 0 ? w.map(x => x / wSum) : w;
                    const sumSq = normW.reduce((a, b) => a + b * b, 0);
                    const ess = sumSq > 0 ? 1 / sumSq : 0;
                    essHistory.push(ess);
                } else {
                    essHistory.push(null);
                }
            }
        } else if (diagnosticsContainer) {
            diagnosticsContainer.style.display = 'none';
        }

        // Setup Slider Ticks Overlay
        const ticksContainer = document.getElementById('timeline-ticks-container');
        if (ticksContainer) {
            ticksContainer.innerHTML = '';
            if (resampled_steps && resampled_steps.length > 0 && nSteps > 1) {
                resampled_steps.forEach(idx => {
                    const pct = (idx / (nSteps - 1)) * 100;
                    const tick = document.createElement('div');
                    tick.className = 'timeline-tick';
                    tick.style.left = `calc(${pct}% - 1px)`;
                    ticksContainer.appendChild(tick);
                });
            }
        }

        // Auto-scale toggle button
        const autoscaleBtn = document.getElementById('posterior-autoscale-btn');
        window.POSTERIOR_AUTOSCALE = true; // default true
        if (autoscaleBtn) {
            autoscaleBtn.textContent = 'Disable Autoscale';
            autoscaleBtn.classList.remove('is-active');
            
            const newBtn = autoscaleBtn.cloneNode(true);
            autoscaleBtn.parentNode.replaceChild(newBtn, autoscaleBtn);
            newBtn.addEventListener('click', () => {
                window.POSTERIOR_AUTOSCALE = !window.POSTERIOR_AUTOSCALE;
                newBtn.textContent = window.POSTERIOR_AUTOSCALE ? 'Disable Autoscale' : 'Enable Autoscale';
                newBtn.classList.toggle('is-active', !window.POSTERIOR_AUTOSCALE);
                const currentIdx = parseInt(globalSlider.value, 10);
                if (!isNaN(currentIdx)) {
                    syncFrames(currentIdx);
                }
            });
        }

        function updateStep(stepIdx) {
            const step = steps[Math.max(0, Math.min(stepIdx, nSteps - 1))];
            const isResampled = resampled_steps && resampled_steps.includes(stepIdx);

            for (const { div, uncDiv, param, uncHistory, color } of plotDivs) {
                const entry = step[param];
                if (!entry) continue;

                const unit = param_units[param] ? ` (${param_units[param]})` : '';
                const bounds = physical_bounds[param];
                const traces = [];
                let lo = bounds ? bounds[0] : 0;
                let hi = bounds ? bounds[1] : 1;

                if (entry.type === 'particles') {
                    const values = entry.values;
                    const weights = entry.weights;
                    const n = values.length;

                    let wSum = 0;
                    for (let i = 0; i < n; i++) wSum += weights[i];

                    let mean = 0;
                    for (let i = 0; i < n; i++) mean += (weights[i] / wSum) * values[i];
                    let variance = 0;
                    for (let i = 0; i < n; i++) {
                        const d = values[i] - mean;
                        variance += (weights[i] / wSum) * d * d;
                    }
                    const sigma = Math.sqrt(Math.max(variance, 1e-30));
                    const bw_est = 0.12 * sigma * Math.pow(n, -0.2);

                    if (window.POSTERIOR_AUTOSCALE !== false) {
                        if (n > 0) {
                            const minVal = Math.min(...values);
                            const maxVal = Math.max(...values);
                            // Add 3 bandwidths padding to prevent cutoff
                            lo = minVal - 3 * bw_est;
                            hi = maxVal + 3 * bw_est;
                            // Clamp to physical bounds
                            if (bounds) {
                                lo = Math.max(lo, bounds[0]);
                                hi = Math.min(hi, bounds[1]);
                            }
                        }
                    } else {
                        lo = bounds ? bounds[0] : (n > 0 ? Math.min(...values) : 0);
                        hi = bounds ? bounds[1] : (n > 0 ? Math.max(...values) : 1);
                    }

                    const { grid, kde } = _weightedKDE(values, weights, lo, hi, 800);
                    traces.push({
                        type: 'scatter', x: grid, y: kde,
                        mode: 'lines',
                        fill: 'tozeroy',
                        fillcolor: isResampled ? 'rgba(255,140,0,0.18)' : 'rgba(0,100,200,0.18)',
                        line: { color: isResampled ? 'rgba(255,140,0,0.8)' : 'rgba(0,100,200,0.8)', width: 1.5 },
                        hoverinfo: 'skip', showlegend: false,
                    });
                } else if (entry.type === 'grid') {
                    traces.push({
                        type: 'bar', x: entry.axis, y: entry.posterior,
                        marker: { color: 'rgba(0,100,200,0.5)' },
                        hoverinfo: 'skip', showlegend: false,
                    });
                }

                // Ground truth line using layout shape (stretching full height)
                const shapes = [];
                if (true_params && true_params[param] != null) {
                    const tv = true_params[param];
                    shapes.push({
                        type: 'line',
                        xref: 'x',
                        yref: 'paper',
                        x0: tv,
                        x1: tv,
                        y0: 0,
                        y1: 1,
                        line: {
                            color: 'rgba(200,30,30,0.8)',
                            width: 1.5,
                            dash: 'dash'
                        }
                    });
                }

                let xrange;
                if (window.POSTERIOR_AUTOSCALE !== false) {
                    if (entry.type === 'particles') {
                        xrange = [lo, hi];
                    } else if (entry.type === 'grid' && entry.axis && entry.axis.length > 0) {
                        xrange = [Math.min(...entry.axis), Math.max(...entry.axis)];
                    } else {
                        xrange = bounds ? [bounds[0], bounds[1]] : undefined;
                    }
                } else {
                    xrange = bounds ? [bounds[0], bounds[1]] : undefined;
                }

                const layout = {
                    template: 'plotly_white',
                    margin: { l: 10, r: 10, t: 4, b: 36 },
                    xaxis: {
                        title: { text: param + unit, font: { size: 10 } },
                        range: xrange,
                        autorange: xrange === undefined
                    },
                    yaxis: { visible: false },
                    height: 180,
                    hovermode: false,
                    shapes: shapes,
                };
                Plotly.react(div, traces, layout, { responsive: true, displayModeBar: false });

                // Render the small uncertainty line chart
                if (uncDiv && uncHistory && uncHistory.some(v => v !== null)) {
                    const uncTraces = [{
                        type: 'scatter',
                        x: steps.map((_, idx) => idx),
                        y: uncHistory,
                        mode: 'lines',
                        line: { color: color, width: 1.5 },
                        hoverinfo: 'skip',
                        showlegend: false
                    }];

                    const uncShapes = [];
                    // Current step vertical indicator line
                    uncShapes.push({
                        type: 'line',
                        x0: stepIdx,
                        x1: stepIdx,
                        y0: 0,
                        y1: 1,
                        yref: 'paper',
                        line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                    });

                    // Add red dashed line for the threshold if available
                    let threshVal = null;
                    if (data.absolute_thresholds && data.absolute_thresholds[param] != null) {
                        threshVal = data.absolute_thresholds[param];
                    } else if (param === 'frequency') {
                        threshVal = 100000.0 / 1e9; // 100 KHz in GHz
                    } else if (data.convergence_threshold != null && bounds) {
                        threshVal = data.convergence_threshold * (bounds[1] - bounds[0]);
                    } else if (bounds) {
                        threshVal = 0.01 * (bounds[1] - bounds[0]);
                    }

                    if (threshVal !== null) {
                        uncShapes.push({
                            type: 'line',
                            x0: 0,
                            x1: nSteps - 1,
                            y0: threshVal,
                            y1: threshVal,
                            line: { color: '#ef4444', width: 1.2, dash: 'dash' }
                        });
                    }

                    const uncLayout = {
                        template: 'plotly_white',
                        margin: { l: 24, r: 5, t: 5, b: 20 },
                        xaxis: {
                            visible: true,
                            tickfont: { size: 8 },
                            title: { text: 'Step', font: { size: 8 } }
                        },
                        yaxis: {
                            visible: true,
                            tickfont: { size: 8 },
                            rangemode: 'tozero'
                        },
                        height: 180,
                        hovermode: false,
                        shapes: uncShapes
                    };

                    Plotly.react(uncDiv, uncTraces, uncLayout, { responsive: true, displayModeBar: false });
                }
            }

            // Redraw SMC diagnostics plots
            if (hasParticles && diagnosticsContainer) {
                // Update ESS chart
                const essDiv = document.getElementById('smc-ess-chart');
                const essTraces = [
                    {
                        type: 'scatter',
                        x: steps.map((_, i) => i),
                        y: essHistory,
                        mode: 'lines',
                        name: 'ESS',
                        line: { color: '#0ea5e9', width: 2 }
                    }
                ];
                const essLayout = {
                    template: 'plotly_white',
                    margin: { l: 40, r: 15, t: 15, b: 35 },
                    xaxis: { title: 'Step' },
                    yaxis: { title: 'ESS', range: [0, nParticles * 1.05] },
                    height: 180,
                    showlegend: false,
                    shapes: [
                        {
                            type: 'line',
                            x0: 0,
                            x1: nSteps - 1,
                            y0: thresholdVal,
                            y1: thresholdVal,
                            line: { color: '#f43f5e', width: 1.5, dash: 'dash' }
                        },
                        {
                            type: 'line',
                            x0: stepIdx,
                            x1: stepIdx,
                            y0: 0,
                            y1: 1,
                            yref: 'paper',
                            line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                        }
                    ]
                };
                Plotly.react(essDiv, essTraces, essLayout, { responsive: true, displayModeBar: false });

                // Update Sorted Weights chart
                const weightsDiv = document.getElementById('smc-weights-chart');
                const currentStep = steps[stepIdx];
                if (currentStep && currentStep[firstParam]) {
                    const w = currentStep[firstParam].weights;
                    const sortedW = [...w].sort((a, b) => b - a);
                    const weightsTraces = [
                        {
                            type: 'bar',
                            x: sortedW.map((_, idx) => idx),
                            y: sortedW,
                            marker: { color: '#6366f1' }
                        }
                    ];
                    const weightsLayout = {
                        template: 'plotly_white',
                        margin: { l: 40, r: 15, t: 15, b: 35 },
                        xaxis: { title: 'Sorted Particle Index' },
                        yaxis: { title: 'Weight', range: [0, Math.max(...sortedW) * 1.1] },
                        height: 180,
                        showlegend: false
                    };
                    Plotly.react(weightsDiv, weightsTraces, weightsLayout, { responsive: true, displayModeBar: false });
                }
            }
        }

        updateStep(0);
        setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
        }, 50);

        const adapter = {
            contentWindow: {
                showFrame: updateStep,
                totalFrames: nSteps,
                stepValues: steps.map((_, k) => k),
            },
            addEventListener: () => {},
        };
        if (onReady) onReady(adapter);
    }

    async function renderParameterConvergence(container, jsonPath, onReady) {
        container.innerHTML = '<div style="padding:1em;color:#64748b;text-align:center;">Loading…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load convergence data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'parameter_convergence_v1' || !data.steps) {
            container.innerHTML = '<div style="padding:1em;color:#64748b;">No convergence data.</div>';
            return;
        }
        if (!container.isConnected) return;

        await ensurePlotly();
        if (!container.isConnected) return;

        const { param_names, param_units, true_params, steps } = data;
        const xs = steps.map((_, i) => i);
        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];

        const traces = [];
        param_names.forEach((param, ci) => {
            const color = COLORS[ci % COLORS.length];
            const unit = param_units[param] ? ` (${param_units[param]})` : '';
            const uncerts = steps.map((s) => s.uncertainties[param] ?? null);
            traces.push({
                type: 'scatter', x: xs, y: uncerts,
                mode: 'lines', name: `${param}${unit} σ`,
                line: { color, width: 2 },
            });
            if (true_params && true_params[param] != null) {
                traces.push({
                    type: 'scatter', x: [xs[0], xs[xs.length - 1]], y: [true_params[param], true_params[param]],
                    mode: 'lines', name: `${param} true`,
                    line: { color, width: 1, dash: 'dot' },
                    showlegend: false,
                });
            }
        });

        const layout = {
            template: 'plotly_white',
            margin: { l: 60, r: 20, t: 20, b: 50 },
            xaxis: { title: 'Step' },
            yaxis: { title: 'Uncertainty' },
            legend: { orientation: 'h', y: -0.25 },
            height: 320,
        };

        container.innerHTML = '';
        const plotDiv = document.createElement('div');
        container.appendChild(plotDiv);

        function updateStep(stepIdx) {
            const activeStep = xs[Math.max(0, Math.min(stepIdx, xs.length - 1))];
            const updatedLayout = {
                ...layout,
                shapes: [
                    {
                        type: 'line',
                        x0: activeStep,
                        x1: activeStep,
                        y0: 0,
                        y1: 1,
                        yref: 'paper',
                        line: {
                            color: 'rgba(59, 130, 246, 0.8)',
                            width: 2,
                            dash: 'solid'
                        }
                    }
                ]
            };
            Plotly.react(plotDiv, traces, updatedLayout, { responsive: true, displayModeBar: false });
        }

        updateStep(0);

        const adapter = {
            contentWindow: {
                showFrame: updateStep,
                totalFrames: xs.length,
                stepValues: xs,
            },
            addEventListener: () => {},
        };
        if (onReady) onReady(adapter);
    }

    async function renderConvergenceMetrics(container, jsonPath, onReady) {
        container.innerHTML = '<div style="padding:1em;color:#64748b;text-align:center;">Loading…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load metrics: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'convergence_metrics_v1' || !data.steps) {
            container.innerHTML = '<div style="padding:1em;color:#64748b;">No convergence metrics.</div>';
            return;
        }
        if (!container.isConnected) return;

        await ensurePlotly();
        if (!container.isConnected) return;

        const { param_names, param_units, convergence_threshold, steps, param_bounds } = data;
        const xs = steps.map((s) => s.step);
        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];

        // Helper to format float numbers cleanly
        function formatNum(val) {
            if (val === null || val === undefined) return '';
            if (Math.abs(val - Math.round(val)) < 1e-4) {
                return Math.round(val).toString();
            }
            return parseFloat(val.toFixed(3)).toString();
        }

        // Compute per-parameter streaks dynamically
        const paramStreaks = {};
        param_names.forEach(p => {
            paramStreaks[p] = [];
            let currentStreak = 0;
            for (let s = 0; s < steps.length; s++) {
                const isConv = steps[s].converged_params[p];
                if (isConv) {
                    currentStreak++;
                } else {
                    currentStreak = 0;
                }
                paramStreaks[p].push(currentStreak);
            }
        });

        container.innerHTML = '';
        
        // Build cards stack for parameters
        const paramPlotContexts = [];
        param_names.forEach((param, ci) => {
            const wrapper = document.createElement('div');
            wrapper.className = 'convergence-card';
            wrapper.style.cssText = 'background:#ffffff; border:1px solid #e2e8f0; border-radius:8px; padding:12px; margin-bottom:12px; box-shadow:0 1px 2px rgba(0,0,0,0.05); display:flex; flex-direction:column; width:100%; box-sizing:border-box;';
            
            // Header
            const header = document.createElement('div');
            header.style.cssText = 'display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:8px;';
            
            // Title Info (Left)
            const infoDiv = document.createElement('div');
            infoDiv.style.cssText = 'display:flex; flex-direction:column;';
            
            const titleSpan = document.createElement('span');
            titleSpan.style.cssText = 'font-weight:600; font-size:0.9em; color:#1e293b;';
            const isAbs = data.absolute_thresholds && data.absolute_thresholds[param] != null;
            const uncTypeStr = isAbs ? 'absolute uncertainty, KHz' : 'relative uncertainty';
            titleSpan.textContent = `${param} (${uncTypeStr})`;
            
            const subtitleSpan = document.createElement('span');
            subtitleSpan.style.cssText = 'font-size:0.75em; color:#64748b; margin-top:2px;';
            
            // Calculate bounds and width text
            let boundsText = '';
            if (param_bounds && param_bounds[param]) {
                const [lo, hi] = param_bounds[param];
                const width = hi - lo;
                const bUnit = param_units[param] || '';
                boundsText = `bounds: [${formatNum(lo)}, ${formatNum(hi)}] ${bUnit} (width=${formatNum(width)} ${bUnit})`;
            }
            subtitleSpan.textContent = boundsText;
            
            infoDiv.appendChild(titleSpan);
            infoDiv.appendChild(subtitleSpan);
            header.appendChild(infoDiv);
            
            // Badge (Right)
            const badgeSpan = document.createElement('span');
            header.appendChild(badgeSpan);
            
            wrapper.appendChild(header);
            
            // Plot div
            const plotDiv = document.createElement('div');
            plotDiv.style.cssText = 'width:100%; height:180px;';
            wrapper.appendChild(plotDiv);
            
            container.appendChild(wrapper);
            
            // Calculate raw histories
            const vals = steps.map(s => s.uncertainties[param] ?? null);
            const color = COLORS[ci % COLORS.length];
            
            // Pre-calculate contiguous converged ranges for shaded rects
            const convergedRanges = [];
            let rangeStart = null;
            for (let s = 0; s < steps.length; s++) {
                const isConv = steps[s].converged_params[param];
                if (isConv) {
                    if (rangeStart === null) rangeStart = s;
                } else {
                    if (rangeStart !== null) {
                        convergedRanges.push([rangeStart, s - 1]);
                        rangeStart = null;
                    }
                }
            }
            if (rangeStart !== null) {
                convergedRanges.push([rangeStart, steps.length - 1]);
            }
            
            paramPlotContexts.push({
                param,
                plotDiv,
                badgeSpan,
                vals,
                color,
                convergedRanges,
                isAbs,
                bounds: param_bounds ? param_bounds[param] : null
            });
        });

        // Overall Convergence Streak Card at the bottom
        const streakWrapper = document.createElement('div');
        streakWrapper.className = 'convergence-card';
        streakWrapper.style.cssText = 'background:#ffffff; border:1px solid #e2e8f0; border-radius:8px; padding:12px; margin-bottom:12px; box-shadow:0 1px 2px rgba(0,0,0,0.05); display:flex; flex-direction:column; width:100%; box-sizing:border-box;';
        
        const streakHeader = document.createElement('div');
        streakHeader.style.cssText = 'display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;';
        
        const streakTitle = document.createElement('span');
        streakTitle.style.cssText = 'font-weight:600; font-size:0.9em; color:#1e293b;';
        streakTitle.textContent = 'Overall Convergence Streak';
        streakHeader.appendChild(streakTitle);
        
        const streakBadge = document.createElement('span');
        streakHeader.appendChild(streakBadge);
        
        streakWrapper.appendChild(streakHeader);
        
        const streakPlotDiv = document.createElement('div');
        streakPlotDiv.style.cssText = 'width:100%; height:180px;';
        streakWrapper.appendChild(streakPlotDiv);
        
        container.appendChild(streakWrapper);
        
        const streakHistory = steps.map(s => s.convergence_streak ?? 0);

        function updateStep(stepIdx) {
            const idx = Math.max(0, Math.min(stepIdx, steps.length - 1));
            const activeStepVal = xs[idx];
            const patience = data.convergence_patience || 8;

            // 1. Update individual parameter cards
            paramPlotContexts.forEach(({ param, plotDiv, badgeSpan, vals, color, convergedRanges, isAbs, bounds }) => {
                const isConvEnd = steps[steps.length - 1].converged_params[param];
                const isConvCurrent = steps[idx].converged_params[param];
                const streak = paramStreaks[param][idx];
                
                const endBg = isConvEnd ? '#dcfce7' : '#fee2e2';
                const endColor = isConvEnd ? '#15803d' : '#b91c1c';
                const endBorder = isConvEnd ? '1px solid #bbf7d0' : '1px solid #fca5a5';
                const endLabel = isConvEnd ? 'CONVERGED (FINAL)' : 'NOT CONVERGED (FINAL)';

                const currBg = isConvCurrent ? '#dcfce7' : '#fee2e2';
                const currColor = isConvCurrent ? '#15803d' : '#b91c1c';
                const currBorder = isConvCurrent ? '1px solid #bbf7d0' : '1px solid #fca5a5';
                const currLabel = isConvCurrent ? 'CONVERGED (NOW)' : 'NOT CONVERGED (NOW)';

                badgeSpan.innerHTML = `
                    <span style="background-color:${endBg}; color:${endColor}; padding:3px 8px; border-radius:4px; font-weight:600; font-size:0.75em; border: ${endBorder}; margin-right:6px;">${endLabel}</span>
                    <span style="background-color:${currBg}; color:${currColor}; padding:3px 8px; border-radius:4px; font-weight:600; font-size:0.75em; border: ${currBorder}; margin-right:6px;">${currLabel}</span>
                    <span style="font-size:0.85em; color:#475569;">Streak: <strong>${streak}</strong> / ${patience} steps</span>
                `;

                const traces = [{
                    type: 'scatter',
                    x: xs,
                    y: vals,
                    mode: 'lines',
                    line: { color: color, width: 2 },
                    hoverinfo: 'skip',
                    showlegend: false
                }];

                const shapes = [];

                // Shaded green rects for converged ranges
                convergedRanges.forEach(([start, end]) => {
                    shapes.push({
                        type: 'rect',
                        xref: 'x',
                        yref: 'paper',
                        x0: start,
                        x1: end,
                        y0: 0,
                        y1: 1,
                        fillcolor: 'rgba(34, 197, 94, 0.35)',
                        line: { width: 0 }
                    });
                });

                // Vertical active step indicator
                shapes.push({
                    type: 'line',
                    x0: activeStepVal,
                    x1: activeStepVal,
                    y0: 0,
                    y1: 1,
                    yref: 'paper',
                    line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                });

                // Red dashed line for the threshold
                let threshVal = null;
                let thresholdLabel = '';

                if (isAbs) {
                    threshVal = data.absolute_thresholds ? data.absolute_thresholds[param] : null;
                    if (threshVal === null && param === 'frequency') {
                        threshVal = 100000.0;
                    }
                    thresholdLabel = `${formatNum(threshVal / 1000)} KHz threshold`;
                } else {
                    threshVal = data.convergence_threshold != null ? data.convergence_threshold : 0.01;
                    thresholdLabel = `threshold (${formatNum(threshVal)})`;
                    
                    // 100% bound line
                    shapes.push({
                        type: 'line',
                        x0: xs[0],
                        x1: xs[xs.length - 1],
                        y0: 1.0,
                        y1: 1.0,
                        line: { color: 'rgba(100,100,100,0.3)', width: 1, dash: 'dash' }
                    });
                }

                if (threshVal !== null) {
                    shapes.push({
                        type: 'line',
                        x0: xs[0],
                        x1: xs[xs.length - 1],
                        y0: threshVal,
                        y1: threshVal,
                        line: { color: '#ef4444', width: 1.5, dash: 'dash' }
                    });
                }

                const annotations = [];
                if (threshVal !== null) {
                    annotations.push({
                        x: xs[xs.length - 1],
                        y: threshVal,
                        xref: 'x',
                        yref: 'y',
                        text: thresholdLabel,
                        showarrow: false,
                        xanchor: 'right',
                        yanchor: 'bottom',
                        font: { size: 9, color: '#b91c1c' }
                    });
                }

                if (!isAbs) {
                    annotations.push({
                        x: xs[xs.length - 1],
                        y: 1.0,
                        xref: 'x',
                        yref: 'y',
                        text: '100% of bound',
                        showarrow: false,
                        xanchor: 'right',
                        yanchor: 'bottom',
                        font: { size: 9, color: 'rgba(100,100,100,0.6)' }
                    });
                }

                // Add Plotly CONVERGED badge if converged at the active step
                let yMax = 1.1;
                if (isAbs) {
                    const maxVal = Math.max(...vals.filter(v => v !== null), threshVal);
                    yMax = maxVal * 1.05;
                } else {
                    const maxVal = Math.max(...vals.filter(v => v !== null), 1.0);
                    yMax = maxVal * 1.05;
                }

                if (isConvCurrent) {
                    annotations.push({
                        x: xs[xs.length - 1],
                        y: yMax * 0.9,
                        xref: 'x',
                        yref: 'y',
                        text: 'CONVERGED',
                        showarrow: false,
                        xanchor: 'right',
                        yanchor: 'top',
                        font: { size: 10, color: '#15803d', weight: 'bold' },
                        bgcolor: '#dcfce7',
                        bordercolor: '#bbf7d0',
                        borderwidth: 1,
                        borderpad: 4,
                        opacity: 0.95
                    });
                }

                const layout = {
                    template: 'plotly_white',
                    margin: { l: 45, r: 15, t: 15, b: 35 },
                    xaxis: { title: { text: 'Step', font: { size: 10 } }, tickfont: { size: 9 } },
                    yaxis: {
                        title: { text: isAbs ? 'Absolute uncertainty' : 'Relative uncertainty', font: { size: 10 } },
                        tickfont: { size: 9 },
                        range: [0, yMax],
                        rangemode: 'tozero'
                    },
                    height: 180,
                    hovermode: false,
                    shapes: shapes,
                    annotations: annotations
                };

                Plotly.react(plotDiv, traces, layout, { responsive: true, displayModeBar: false });
            });

            // 2. Update Streak Plot
            const currentStreak = streakHistory[idx];
            const isAchieved = currentStreak >= patience;
            
            const streakBg = isAchieved ? '#dcfce7' : '#f1f5f9';
            const streakTextColor = isAchieved ? '#15803d' : '#475569';
            const streakLabel = isAchieved ? 'ACHIEVED' : 'IN PROGRESS';
            const streakBorder = isAchieved ? '1px solid #bbf7d0' : '1px solid #cbd5e1';
            
            streakBadge.innerHTML = `<span style="background-color:${streakBg}; color:${streakTextColor}; padding:3px 8px; border-radius:4px; font-weight:600; font-size:0.75em; border: ${streakBorder};">${streakLabel}</span> <span style="font-size:0.85em; color:#475569; margin-left:6px;">Current Streak: <strong>${currentStreak}</strong> / ${patience} steps</span>`;

            const streakTraces = [{
                type: 'scatter',
                x: xs,
                y: streakHistory,
                mode: 'lines',
                line: { color: '#6366f1', width: 2 },
                hoverinfo: 'skip',
                showlegend: false
            }];

            const streakShapes = [
                {
                    type: 'line',
                    x0: xs[0],
                    x1: xs[xs.length - 1],
                    y0: patience,
                    y1: patience,
                    line: { color: '#ef4444', width: 1.5, dash: 'dash' }
                },
                {
                    type: 'line',
                    x0: activeStepVal,
                    x1: activeStepVal,
                    y0: 0,
                    y1: 1,
                    yref: 'paper',
                    line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                }
            ];

            const streakAnnotations = [{
                x: xs[xs.length - 1],
                y: patience,
                xref: 'x',
                yref: 'y',
                text: `patience (${patience} steps)`,
                showarrow: false,
                xanchor: 'right',
                yanchor: 'bottom',
                font: { size: 9, color: '#b91c1c' }
            }];

            const streakLayout = {
                template: 'plotly_white',
                margin: { l: 45, r: 15, t: 15, b: 35 },
                xaxis: { title: { text: 'Step', font: { size: 10 } }, tickfont: { size: 9 } },
                yaxis: {
                    title: { text: 'Consecutive converged steps', font: { size: 10 } },
                    tickfont: { size: 9 },
                    range: [0, Math.max(...streakHistory, patience) * 1.15],
                    rangemode: 'tozero'
                },
                height: 180,
                hovermode: false,
                shapes: streakShapes,
                annotations: streakAnnotations
            };

            Plotly.react(streakPlotDiv, streakTraces, streakLayout, { responsive: true, displayModeBar: false });
        }

        updateStep(0);
        setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
        }, 50);

        const adapter = {
            contentWindow: {
                showFrame: updateStep,
                totalFrames: xs.length,
                stepValues: xs,
            },
            addEventListener: () => {},
        };
        if (onReady) onReady(adapter);
    }

    async function renderFisher(container, jsonPath) {
        container.innerHTML = '<div style="padding:1em;color:#64748b;text-align:center;">Loading…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load Fisher data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'fisher_v1' || !data.steps) {
            container.innerHTML = '<div style="padding:1em;color:#64748b;">No Fisher information data.</div>';
            return;
        }
        if (!container.isConnected) return;

        await ensurePlotly();
        if (!container.isConnected) return;

        const { param_names, param_units, steps } = data;
        const xs = steps.map((_, i) => i);
        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];

        // One subplot per parameter: CRLB (lower bound) vs actual uncertainty
        container.innerHTML = '';
        container.style.cssText = 'display:flex; flex-wrap:wrap; gap:8px; margin-top:8px;';

        for (const [ci, param] of param_names.entries()) {
            const unit = param_units[param] ? ` (${param_units[param]})` : '';
            const color = COLORS[ci % COLORS.length];

            const crlb = steps.map((s) => s.fisher_bounds[param] ?? null);
            const actual = steps.map((s) => s.actual_uncertainty[param] ?? null);

            const traces = [
                {
                    type: 'scatter', x: xs, y: actual,
                    mode: 'lines', name: 'Actual σ',
                    line: { color, width: 2 },
                },
                {
                    type: 'scatter', x: xs, y: crlb,
                    mode: 'lines', name: 'CRLB',
                    line: { color, width: 1.5, dash: 'dash' },
                    fill: 'tonexty', fillcolor: `${color}22`,
                },
            ];

            const layout = {
                template: 'plotly_white',
                margin: { l: 55, r: 10, t: 28, b: 40 },
                title: { text: param + unit, font: { size: 11 }, y: 0.96 },
                xaxis: { title: { text: 'Step', font: { size: 10 } } },
                yaxis: { title: { text: 'Uncertainty', font: { size: 10 } }, rangemode: 'tozero' },
                showlegend: ci === 0,
                legend: { orientation: 'h', y: -0.3 },
                height: 240,
            };

            const wrapper = document.createElement('div');
            wrapper.style.cssText = 'flex:1; min-width:200px; max-width:420px;';
            container.appendChild(wrapper);
            Plotly.react(wrapper, traces, layout, { displayModeBar: false, responsive: true });
        }
    }

    // ---- End JSON-based render functions ----

    function renderJitterView(container, jitterPlot) {
        if (!container || !jitterPlot) return;

        const jitter = jitterPlot.jitter || {};
        const variances = jitterPlot.variances || {};
        const correlations = jitterPlot.correlations || {};
        const paramNames = Object.keys(jitter);

        const jitterItems = paramNames.map(name => ({
            label: name,
            val: formatMetricValue(jitter[name]),
            tip: 'Standard deviation of estimates over last 20 steps (physical units).',
            rawVal: jitter[name]
        }));

        const varItems = Object.keys(variances).length > 0
            ? paramNames.map(name => ({ label: name, val: formatMetricValue(variances[name]), rawVal: variances[name] }))
            : [];

        // Jitter cards row
        let html = '<h4>Jitter (last 20 steps)</h4>';
        html += '<div class="jitter-cards">' + renderItemsToHtml(jitterItems) + '</div>';

        // Variance cards row
        if (varItems.length > 0) {
            html += '<h4>Final Variances (diag Σ)</h4>';
            html += '<div class="jitter-cards">' + renderItemsToHtml(varItems) + '</div>';
        }

        // Correlation matrix — full-width block, not inside the card grid
        if (Object.keys(correlations).length > 0) {
            html += '<h4>Correlation Matrix <span class="help-icon" tabindex="0" title="Measures how tightly parameters are coupled. +1/-1 = perfect correlation; 0 = independent.">?</span></h4>';
            html += '<div class="correlation-table-wrapper"><table class="correlation-table">';
            html += '<thead><tr><th></th>' + paramNames.map(n => `<th>${escapeHtml(n)}</th>`).join('') + '</tr></thead>';
            html += '<tbody>';
            for (const ni of paramNames) {
                html += `<tr><th>${escapeHtml(ni)}</th>`;
                for (const nj of paramNames) {
                    const val = (correlations[ni] && correlations[ni][nj] !== undefined) ? correlations[ni][nj] : 0;
                    let color, textColor;
                    if (ni === nj) {
                        color = 'rgba(71, 85, 105, 0.15)';
                        textColor = '#1e293b';
                    } else if (val > 0) {
                        color = `rgba(30, 144, 255, ${0.1 + 0.9 * val})`;
                        textColor = val > 0.4 ? '#ffffff' : '#1e3a8a';
                    } else {
                        color = `rgba(239, 68, 68, ${0.1 + 0.9 * Math.abs(val)})`;
                        textColor = Math.abs(val) > 0.4 ? '#ffffff' : '#7f1d1d';
                    }
                    html += `<td class="corr-cell" style="background-color:${color}; color:${textColor};">${val.toFixed(2)}</td>`;
                }
                html += '</tr>';
            }
            html += '</tbody></table></div>';
        }

        container.innerHTML = html;
    }

    function renderItemsToHtml(items, useSliders = false) {
        return items.map(it => {
            const tipAttr = it.tip ? ' title="' + it.tip.replace(/"/g, '&quot;') + '"' : '';
            const icon = it.tip ? '<span class="help-icon" tabindex="0"' + tipAttr + '>?</span>' : '';

            let valueHtml = '<div class="metric-value">' + it.val + '</div>';

            if (useSliders && it.bounds && typeof it.rawVal === 'number') {
                const lo = it.bounds[0];
                const hi = it.bounds[1];
                const percent = Math.min(100, Math.max(0, (it.rawVal - lo) / (hi - lo) * 100));

                let markersHtml = '<div class="param-range-marker" title="True Value: ' + it.val + '" style="left: ' + percent + '%; background-color: #2563eb; z-index: 10;"></div>';

                if (typeof it.finalEst === 'number' && Number.isFinite(it.finalEst)) {
                    const finalPct = Math.min(100, Math.max(0, (it.finalEst - lo) / (hi - lo) * 100));
                    const formattedFinal = it.name && (it.name.toLowerCase().includes('freq') || it.name.toLowerCase().includes('linewidth') || it.name.toLowerCase().includes('split') || it.name === 'fwhm_total') ? formatFrequency(it.finalEst) : it.finalEst.toFixed(3);
                    markersHtml += '<div class="param-range-marker" title="Final Inferred: ' + formattedFinal + '" style="left: ' + finalPct + '%; background-color: #ef4444; width: 8px; height: 8px; z-index: 9;"></div>';
                }

                if (typeof it.fbAtMilestone === 'number' && Number.isFinite(it.fbAtMilestone)) {
                    const fbPct = Math.min(100, Math.max(0, (it.fbAtMilestone - lo) / (hi - lo) * 100));
                    const formattedFb = formatFrequency(it.fbAtMilestone);
                    markersHtml += '<div class="param-range-marker" title="Milestone Conv Freq: ' + formattedFb + '" style="left: ' + fbPct + '%; background-color: #f59e0b; width: 8px; height: 8px; z-index: 8;"></div>';
                }

                valueHtml =
                    '<div class="metric-value">' + it.val + '</div>' +
                    '<div class="param-range-container">' +
                    '<div class="param-range-track">' +
                    markersHtml +
                    '</div>' +
                    '<div class="param-range-bounds">' +
                    '<span>' + it.fmtLo + '</span>' +
                    '<span>' + it.fmtHi + '</span>' +
                    '</div>' +
                    '</div>';
            }

            const extraClass = it.cardClass ? ' ' + it.cardClass : '';
            return '<div class="metric-item' + extraClass + '">' +
                '<div class="metric-label">' + it.label + icon + '</div>' +
                valueHtml +
                '</div>';
        }).join('');
    }

    function findSobolBaselineForPlot(plot) {
        if (!window.MANIFEST || !plot) return null;
        return window.MANIFEST.find(p =>
            p.strategy === "SimpleSobol" &&
            p.generator === plot.generator &&
            p.noise === plot.noise &&
            p.repeat === plot.repeat
        );
    }

    function findOtherStrategyPlots(plot) {
        if (!window.MANIFEST || !plot) return [];
        return window.MANIFEST.filter(p =>
            p.type === 'scan' &&
            p.generator === plot.generator &&
            p.noise === plot.noise &&
            p.repeat === plot.repeat &&
            p.strategy !== plot.strategy &&
            p.strategy !== 'SimpleSobol'
        );
    }

    // Reverse-lookup: entity id (lowercase+underscores) → original strategy string
    const strategyIdMap = new Map(
        [...new Set(scanPlots.map(p => p.strategy))].map(s =>
            [s.toLowerCase().replace(/[^a-z0-9]/g, '_'), s])
    );

    // Overlay B's measurement traces on the primary scan plot (single-repeat view).
    // Uses Plotly.deleteTraces + Plotly.addTraces; traces are tagged with meta.isComparison.
    async function applyComparisonOverlay(entityB) {
        const scanPlotDiv = document.getElementById('scan-plot-div');
        if (!scanPlotDiv || !window.Plotly || scanPlotDiv.style.display === 'none') return;

        // Remove previous comparison traces
        if (Array.isArray(scanPlotDiv.data)) {
            const compIdx = scanPlotDiv.data
                .map((t, i) => (t.meta && t.meta.isComparison) ? i : -1)
                .filter(i => i >= 0);
            if (compIdx.length) await Plotly.deleteTraces(scanPlotDiv, compIdx).catch(() => {});
        }

        if (!entityB || !currentPlot) return;
        const baseId = entityB.id.replace(/_freq$|_conv$/, '');
        const bStrategy = strategyIdMap.get(baseId);
        if (!bStrategy || bStrategy === currentPlot.strategy) return;

        const bPlot = scanPlots.find(p =>
            p.generator === currentPlot.generator &&
            p.noise === currentPlot.noise &&
            p.strategy === bStrategy &&
            p.repeat === currentPlot.repeat
        );
        if (!bPlot || !bPlot.path) return;

        try {
            const bFig = await _fetchJson(bPlot.path);
            if (!bFig || !Array.isArray(bFig.data)) return;

            const MEASUREMENT_NAMES = [
                'measurements (coarse)', 'measurements (inference)',
                'measurements (secondary)', 'measurements (tertiary)',
                'measurements (noisy)', 'locator most likely signal',
                'locator mode belief signal',
            ];
            const isCompTrace = name => name && MEASUREMENT_NAMES.some(n => name.includes(n));

            const toPlain = o => {
                if (o === null || o === undefined) return o;
                if (ArrayBuffer.isView(o)) return Array.from(o);
                if (Array.isArray(o)) return o.map(toPlain);
                if (typeof o === 'object') { const r = {}; for (const k of Object.keys(o)) r[k] = toPlain(o[k]); return r; }
                return o;
            };

            const compTraces = bFig.data
                .filter(t => isCompTrace(t.name))
                .map(t => {
                    const plain = toPlain(t);
                    return {
                        ...plain,
                        name: `${plain.name || ''} (${bStrategy})`,
                        meta: { isComparison: true },
                        opacity: 0.55,
                        marker: plain.marker ? { ...plain.marker, symbol: 'diamond', size: (plain.marker.size || 8) * 0.85 } : undefined,
                        line: plain.line ? { ...plain.line, dash: 'dot', width: (plain.line.width || 2) * 0.8 } : undefined,
                    };
                });

            if (compTraces.length) Plotly.addTraces(scanPlotDiv, compTraces);
        } catch (e) {
            console.warn('applyComparisonOverlay failed:', e);
        }
    }

    let lastSummaryKey = null;
    let lastComparePairIds = { a: null, b: null };
    // Single source of truth for the "savings baseline" strategy, shared across
    // the Highlights, Dashboard, and Noise-metrics views so the choice is set
    // once and stays consistent when switching between them.
    let sharedBaselineStrategy = null;

    // ── Entity helpers ────────────────────────────────────────────────────────
    function _phaseData(p) {
        // Legacy manifest format: nested coarse/fine dicts (pre-slim)
        if (p && p.coarse && p.fine) return p.fine;
        // Slim manifest format: flattened coarse_measurements/fine_measurements
        // For Bayesian 2-phase runs show fine-phase measurement count in comparisons
        if (p && p.fine_measurements != null) return { ...p, measurements: p.fine_measurements };
        return p;
    }
    function _mv(obj, ...keys) {
        if (!obj) return null;
        const m = obj.metrics || {};
        for (const k of keys) {
            if (obj[k] != null) return obj[k];
            if (m[k] != null) return m[k];
        }
        return null;
    }

    function buildSummaryEntities(generator, noise) {
        const noiseSet = new Set(Array.isArray(noise) ? noise : [noise]);
        const genSet = toGenSet(generator);
        const all = (window.MANIFEST || []).filter(p =>
            genSet.has(p.generator) && noiseSet.has(p.noise) && p.type === 'scan' && isSuccessRun(p)
        );
        const strategies = [...new Set(all.map(p => p.strategy))].sort();
        const entities = [];
        for (const strategy of strategies) {
            const strategyPlots = all.filter(p => p.strategy === strategy);
            const runs = strategyPlots.map(p => _phaseData(p));
            if (runs.length) {
                entities.push(..._makeStrategyEntities(runs, strategy, true, strategyPlots));
            }
        }
        return entities;
    }

    function _shortStratLabel(strategy) {
        return strategy
            .replace('Bayesian-', '')
            .replace('SimpleSobol', 'Sobol')
            .replace('SimpleSweep', 'Sweep')
            .replace('StagedSobolSweep', 'StagedSobol')
            .replace('GaussianMixture', 'GaussMix');
    }

    function _makeStrategyEntities(d, strategy, isArray, parentPlots) {
        const push = (arr, v) => { if (v != null) arr.push(v); };
        const label = _shortStratLabel(strategy);
        const id = strategy.toLowerCase().replace(/[^a-z0-9]/g, '_');

        if (isArray) {
            const base = {
                id, label,
                steps: [], uncert: [], err: [],
                steps_to_fb: [], uncert_at_fb: [], err_at_fb: [],
                f_spans: [], repeats: [],
                stepsType: 'measurements',
            };
            const freqConv = {
                id: id + '_freq', label: label + ' freq converged',
                steps: [], uncert: [], err: [],
                steps_to_fb: [], uncert_at_fb: [], err_at_fb: [],
                f_spans: [], repeats: [],
                stepsType: 'steps',
            };
            const allConv = {
                id: id + '_conv', label: label + ' converged',
                steps: [], uncert: [], err: [],
                steps_to_fb: [], uncert_at_fb: [], err_at_fb: [],
                f_spans: [], repeats: [],
                stepsType: 'steps',
            };
            for (let i = 0; i < d.length; i++) {
                const item = d[i];
                const p = parentPlots ? parentPlots[i] : null;
                
                let f_span = null;
                if (p && p.true_params && p.true_params.params) {
                    const params = p.true_params.params;
                    const lw = params.linewidth;
                    const split = params.split || 0.0;
                    let domain_width = 5.0e8;
                    if (p.true_params.bounds && p.true_params.bounds.frequency) {
                        const freq_bounds = p.true_params.bounds.frequency;
                        if (freq_bounds.length === 2 && freq_bounds[1] > freq_bounds[0]) {
                            domain_width = freq_bounds[1] - freq_bounds[0];
                        }
                    }
                    if (lw && lw > 0) {
                        f_span = Math.max(2.0 * lw, split + lw) / domain_width;
                    }
                }
                
                const rep = p ? p.repeat : null;

                const base_step = _mv(item, 'measurements');
                if (base_step != null) {
                    base.steps.push(base_step);
                    base.uncert.push(_mv(item, 'uncert'));
                    base.err.push(_mv(item, 'abs_err_x'));
                    base.steps_to_fb.push(_mv(item, 'steps_to_fb', 'freq_converged_step'));
                    base.uncert_at_fb.push(_mv(item, 'uncert_fb_at_milestone'));
                    base.err_at_fb.push(_mv(item, 'err_fb_at_milestone'));
                    base.f_spans.push(f_span);
                    base.repeats.push(rep);
                }

                const freq_step = _mv(item, 'freq_converged_step', 'steps_to_fb');
                if (freq_step != null) {
                    freqConv.steps.push(freq_step);
                    freqConv.uncert.push(_mv(item, 'uncert_fb_at_milestone'));
                    freqConv.uncert_at_fb.push(_mv(item, 'uncert_fb_at_milestone'));
                    freqConv.err.push(_mv(item, 'err_fb_at_milestone'));
                    freqConv.f_spans.push(f_span);
                    freqConv.repeats.push(rep);
                }

                const all_step = _mv(item, 'all_converged_step');
                if (all_step != null) {
                    allConv.steps.push(all_step);
                    allConv.uncert.push(_mv(item, 'uncert'));
                    allConv.err.push(_mv(item, 'abs_err_x'));
                    allConv.f_spans.push(f_span);
                    allConv.repeats.push(rep);
                }
            }
            const results = [];
            if (base.steps.length) results.push(base);
            if (freqConv.steps.length) results.push(freqConv);
            if (allConv.steps.length) results.push(allConv);
            return results;
        } else {
            const base = {
                id, label,
                steps:        _mv(d, 'measurements'),
                uncert:       _mv(d, 'uncert'),
                err:          _mv(d, 'abs_err_x'),
                steps_to_fb:  _mv(d, 'steps_to_fb', 'freq_converged_step'),
                uncert_at_fb: _mv(d, 'uncert_fb_at_milestone'),
                err_at_fb:    _mv(d, 'err_fb_at_milestone'),
                stepsType: 'measurements',
            };
            const freqStep = _mv(d, 'freq_converged_step', 'steps_to_fb');
            const allStep  = _mv(d, 'all_converged_step');
            const results = [base];
            if (freqStep != null) {
                results.push({
                    id: id + '_freq', label: label + ' freq converged',
                    steps: freqStep,
                    uncert: _mv(d, 'uncert_fb_at_milestone'),
                    err:    _mv(d, 'err_fb_at_milestone'),
                    steps_to_fb: null, uncert_at_fb: null, err_at_fb: null,
                    stepsType: 'steps',
                });
            }
            if (allStep != null) {
                results.push({
                    id: id + '_conv', label: label + ' converged',
                    steps: allStep,
                    uncert: _mv(d, 'uncert'),
                    err:    _mv(d, 'abs_err_x'),
                    steps_to_fb: null, uncert_at_fb: null, err_at_fb: null,
                    stepsType: 'steps',
                });
            }
            return results;
        }
    }

    function buildRepeatEntities(plot) {
        if (!window.MANIFEST) return [];
        const group = window.MANIFEST.filter(p =>
            p.type === 'scan' &&
            p.generator === plot.generator &&
            p.noise === plot.noise &&
            p.repeat === plot.repeat
        );

        const strategies = [...new Set(group.map(p => p.strategy))].sort();
        const entities = [];
        for (const strategy of strategies) {
            const p = group.find(q => q.strategy === strategy);
            if (p) entities.push(..._makeStrategyEntities(_phaseData(p), strategy, false));
        }
        return entities;
    }

    // ── Pairwise metric rows ──────────────────────────────────────────────────
    function buildPairwiseRows(eA, eB) {
        const isArr = v => Array.isArray(v);
        const has = v => isArr(v) ? v.length > 0 : v != null;
        const sub = (a, b) => {
            if (!has(a) || !has(b)) return null;
            if (isArr(a) && isArr(b)) {
                const n = Math.min(a.length, b.length);
                return Array.from({length: n}, (_, i) => b[i] - a[i]);
            }
            return (!isArr(a) && !isArr(b)) ? b - a : null;
        };
        // Δ card header — use the full entity labels. CSS (text-overflow:
        // ellipsis) handles any overflow at render time based on the card's
        // actual width, instead of hard-clipping in JS.
        const deltaLabel = `Δ  ${eB.label} − ${eA.label}`;
        const rows = [];
        const addRow = (metric, aVal, bVal, cA, cB, cD, type) => {
            // Every metric should be present for every entity by construction
            // (the backend captures both "at convergence" and "final" snapshots).
            // If you see a row skipped here, it means the backend data-capture
            // gap has reappeared — investigate rather than hide.
            if (!has(aVal) || !has(bVal)) return;
            rows.push({ label: metric, cards: [
                { label: eA.label, sublabel: metric, data: aVal, color: cA, type },
                { label: eB.label, sublabel: metric, data: bVal, color: cB, type },
                { label: deltaLabel, data: sub(aVal, bVal), color: cD, type },
            ]});
        };
        addRow('Steps to completion',       eA.steps,        eB.steps,        '#f472b6','#60a5fa','#22c55e', eA.stepsType || 'measurements');
        addRow('Final frequency uncertainty',eA.uncert,       eB.uncert,       '#a78bfa','#34d399','#f59e0b','frequency');
        addRow('Final frequency error',      eA.err,          eB.err,          '#c084fc','#10b981','#6366f1','frequency');
        addRow('Steps to freq. convergence', eA.steps_to_fb,  eB.steps_to_fb,  '#fb923c','#38bdf8','#a3e635','steps');
        addRow('Uncertainty @ freq. conv.',  eA.uncert_at_fb, eB.uncert_at_fb, '#818cf8','#2dd4bf','#fbbf24','frequency');
        addRow('Error @ freq. conv.',        eA.err_at_fb,    eB.err_at_fb,    '#d946ef','#4ade80','#f43f5e','frequency');
        return rows;
    }

    // ── Shared selector + card renderer ──────────────────────────────────────
    function entityCriterion(id) {
        // Entity ids end in '_freq' (freq converged) or '_conv' (all converged);
        // no suffix means the full run.
        if (id.endsWith('_freq')) return 'freq';
        if (id.endsWith('_conv')) return 'conv';
        return 'full';
    }

    function criterionLabel(id) {
        if (id.endsWith('_freq')) return 'Freq. converged';
        if (id.endsWith('_conv')) return 'Converged';
        return 'Full run';
    }

    function baseLocatorId(id) {
        if (id.endsWith('_freq') || id.endsWith('_conv')) return id.slice(0, -5);
        return id;
    }

    function baseLocatorLabel(label) {
        if (label.endsWith(' freq converged')) return label.slice(0, -15);
        if (label.endsWith(' converged')) return label.slice(0, -10);
        return label;
    }

    const SPEED_METRICS = [
        { key: 'steps',       label: 'Steps to completion',        type: 'measurements', color: '#f472b6', deltaColor: '#22c55e' },
        { key: 'steps_to_fb', label: 'Steps to freq. convergence', type: 'steps',        color: '#fb923c', deltaColor: '#a3e635' },
    ];
    const ACCURACY_METRICS = [
        { key: 'uncert_at_fb', label: 'Claimed σ @ freq. conv.', type: 'frequency', color: '#818cf8', deltaColor: '#fbbf24' },
        { key: 'uncert',       label: 'Claimed σ (final)',        type: 'frequency', color: '#a78bfa', deltaColor: '#f59e0b' },
    ];
    // Full set kept for backward compat (buildPairwiseRows single-scan view)
    const ENTITY_METRICS = [
        ...SPEED_METRICS,
        ...ACCURACY_METRICS,
        { key: 'err',      label: 'Final freq. error',     type: 'frequency', color: '#c084fc', deltaColor: '#6366f1' },
        { key: 'err_at_fb', label: 'Error @ freq. conv.',  type: 'frequency', color: '#d946ef', deltaColor: '#f43f5e' },
    ];

    // Renders a group of entities (all criteria for one base locator) as a
    // table: rows = metrics, columns = stopping criteria.
    // allowedKeys: if provided, only show metrics whose key is in this array.
    function renderEntityGroup(groupLabel, entities, container, isSummary, allowedKeys = null) {
        const isDeltaGroup = entities.length > 0 && entities[0].isDelta;
        const groupDiv = document.createElement('div');
        groupDiv.className = 'entity-group' + (isDeltaGroup ? ' entity-group-delta' : '');

        const hdr = document.createElement('div');
        hdr.className = 'entity-group-header';
        hdr.textContent = groupLabel;
        groupDiv.appendChild(hdr);

        const table = document.createElement('div');
        table.className = 'entity-table';
        // label col + one col per criterion entity
        table.style.gridTemplateColumns = `minmax(140px,auto) ${entities.map(() => '1fr').join(' ')}`;

        // Column header row
        const blank = document.createElement('div');
        blank.className = 'entity-table-blank';
        table.appendChild(blank);
        for (const e of entities) {
            const colHdr = document.createElement('div');
            colHdr.className = 'entity-table-col-header';
            colHdr.textContent = criterionLabel(e.id);
            table.appendChild(colHdr);
        }

        const metricsToRender = allowedKeys
            ? ENTITY_METRICS.filter(m => allowedKeys.includes(m.key))
            : ENTITY_METRICS;

        // One row per metric
        for (const m of metricsToRender) {
            const anyHas = entities.some(e => {
                const v = e[m.key];
                return Array.isArray(v) ? v.length > 0 : v != null;
            });
            if (!anyHas) continue;

            const rowLbl = document.createElement('div');
            rowLbl.className = 'entity-table-row-label';
            rowLbl.textContent = m.label;
            table.appendChild(rowLbl);

            for (const e of entities) {
                const val = e[m.key];
                const has = Array.isArray(val) ? val.length > 0 : val != null;
                const type = e.stepsType === 'ratio' ? 'ratio'
                           : m.key === 'steps' ? (e.stepsType || 'measurements')
                           : m.type;

                const cell = document.createElement('div');
                cell.className = 'entity-table-cell';

                if (!has) {
                    const na = document.createElement('span');
                    na.className = 'entity-metric-na';
                    na.textContent = '—';
                    cell.appendChild(na);
                } else if (isSummary) {
                    const color = (e.isDelta && m.deltaColor) ? m.deltaColor : m.color;
                    createCardHistogram(cell, val, m.label, color, type, 80);
                } else {
                    const vEl = document.createElement('div');
                    vEl.className = 'entity-metric-scalar';
                    if (type === 'frequency') vEl.textContent = formatFrequency(val);
                    else vEl.textContent = formatCount(val);
                    cell.appendChild(vEl);
                }

                table.appendChild(cell);
            }
        }

        groupDiv.appendChild(table);
        container.appendChild(groupDiv);
    }

    // Groups entities by base locator and renders each group as a table card.
    // category: 'speed' shows only step metrics, 'accuracy' shows only uncertainty metrics, 'all' shows everything.
    function renderEntityCards(entities, container, isSummary, category = 'all') {
        container.innerHTML = '';
        if (!entities || !entities.length) {
            const p = document.createElement('p');
            p.style.cssText = 'color:#94a3b8;padding:1em 0;font-size:0.9em;';
            p.textContent = 'No data.';
            container.appendChild(p);
            return;
        }

        const allowedKeys = category === 'speed'    ? SPEED_METRICS.map(m => m.key)
                          : category === 'accuracy' ? ACCURACY_METRICS.map(m => m.key)
                          : null;

        const order = [];
        const groups = new Map();
        for (const e of entities) {
            const bid = baseLocatorId(e.id);
            if (!groups.has(bid)) {
                groups.set(bid, { label: baseLocatorLabel(e.label), entities: [] });
                order.push(bid);
            }
            groups.get(bid).entities.push(e);
        }

        // SimpleSweep is the reference: sort its group first.
        order.sort((a, b) => (isSweepBaseline(a) ? 0 : 1) - (isSweepBaseline(b) ? 0 : 1));

        for (const bid of order) {
            const { label, entities: grpEntities } = groups.get(bid);
            renderEntityGroup(label, grpEntities, container, isSummary, allowedKeys);
        }

        // Ratio cards (summary mode only) — adaptive / SimpleSweep only, never all pairs.
        if (isSummary && order.length >= 2) {
            const sweepId = order.find(bid => isSweepBaseline(bid));
            if (sweepId) {
                const gSweep = groups.get(sweepId);
                const ratioMetrics = allowedKeys
                    ? ENTITY_METRICS.filter(m => allowedKeys.includes(m.key))
                    : ENTITY_METRICS.filter(m => SPEED_METRICS.some(sm => sm.key === m.key) || ACCURACY_METRICS.some(am => am.key === m.key));
                for (const bid of order) {
                    if (bid === sweepId) continue;
                    const gAdaptive = groups.get(bid);
                    const ratioLabel = `${gAdaptive.label} / ${gSweep.label}`;
                    const ratioEntities = [];
                    for (const eSweep of gSweep.entities) {
                        const crit = entityCriterion(eSweep.id);
                        const eAdaptive = gAdaptive.entities.find(e => entityCriterion(e.id) === crit);
                        if (!eAdaptive) continue;
                        const ratioE = { id: eSweep.id, label: ratioLabel, isDelta: true, stepsType: 'ratio' };
                        for (const m of ratioMetrics) {
                            const aVal = eSweep[m.key];
                            const bVal = eAdaptive[m.key];
                            if (Array.isArray(aVal) && Array.isArray(bVal)) {
                                const aHasData = aVal.some(v => v != null && v > 0);
                                if (aHasData) {
                                    // Normal ratio: adaptive / sweep
                                    const n = Math.min(aVal.length, bVal.length);
                                    ratioE[m.key] = Array.from({length: n}, (_, idx) => aVal[idx] > 0 ? bVal[idx] / aVal[idx] : null).filter(v => v !== null);
                                } else {
                                    // Sweep has no data for this metric (e.g. uncert_at_fb) —
                                    // fall back to adaptive / sweep.uncert so the ratio is still meaningful
                                    const aFallback = eSweep['uncert'];
                                    if (Array.isArray(aFallback)) {
                                        const n = Math.min(aFallback.length, bVal.length);
                                        ratioE[m.key] = Array.from({length: n}, (_, idx) => aFallback[idx] > 0 ? bVal[idx] / aFallback[idx] : null).filter(v => v !== null);
                                    } else {
                                        ratioE[m.key] = [];
                                    }
                                }
                            } else {
                                ratioE[m.key] = null;
                            }
                        }
                        ratioEntities.push(ratioE);
                    }
                    if (ratioEntities.length) renderEntityGroup(ratioLabel, ratioEntities, container, isSummary, ratioMetrics.map(m => m.key));
                }
            }
        }
    }

    function buildTwoDropdownSelector(entities, onPairChange, defaultAId, defaultBId) {
        const wrapper = document.createElement('div');
        wrapper.className = 'control-row';
        wrapper.style.cssText = 'gap:0.5em;margin:0.5em 0 0.75em;flex-wrap:wrap;align-items:center;';
        const lbl = document.createElement('span');
        lbl.className = 'control-label';
        lbl.textContent = 'Compare:';
        const selA = document.createElement('select');
        selA.className = 'control-select';
        const vs = document.createElement('span');
        vs.style.cssText = 'padding:0 0.3em;color:#64748b;font-size:0.9em;';
        vs.textContent = 'with';
        const selB = document.createElement('select');
        selB.className = 'control-select';
        const hint = document.createElement('span');
        hint.style.cssText = 'color:#94a3b8;font-size:0.78em;';
        hint.textContent = 'Only pairs with the same stopping criterion are comparable.';
        for (const e of entities) {
            const opt = document.createElement('option');
            opt.value = e.id;
            opt.textContent = e.label;
            selA.appendChild(opt);
        }
        // B only ever offers entities with the same stopping criterion as A:
        // cross-criterion pairs vary both quality and cost at once and answer
        // neither question, so they are not offered at all.
        const refreshBOptions = () => {
            const crit = entityCriterion(selA.value || '');
            const prev = selB.value;
            selB.innerHTML = '';
            const candidates = entities.filter(e => e.id !== selA.value && entityCriterion(e.id) === crit);
            for (const e of candidates) {
                const opt = document.createElement('option');
                opt.value = e.id;
                opt.textContent = e.label;
                selB.appendChild(opt);
            }
            if (candidates.some(e => e.id === prev)) selB.value = prev;
            selB.disabled = candidates.length === 0;
        };
        if (defaultAId) { const i = entities.findIndex(e => e.id === defaultAId); if (i >= 0) selA.selectedIndex = i; }
        refreshBOptions();
        if (defaultBId && entityCriterion(defaultBId) === entityCriterion(selA.value || '') && defaultBId !== selA.value) {
            selB.value = defaultBId;
        }
        const notify = () => {
            const eA = entities.find(e => e.id === selA.value);
            const eB = entities.find(e => e.id === selB.value);
            if (eA && eB) onPairChange(eA, eB);
        };
        selA.addEventListener('change', () => { refreshBOptions(); notify(); });
        selB.addEventListener('change', notify);
        wrapper.appendChild(lbl);
        wrapper.appendChild(selA);
        wrapper.appendChild(vs);
        wrapper.appendChild(selB);
        wrapper.appendChild(hint);
        return { wrapper, notify };
    }

    function renderPairwiseCards(rows, container, isSummary) {
        container.innerHTML = '';
        if (!rows || !rows.length) {
            const p = document.createElement('p');
            p.style.cssText = 'color:#94a3b8;padding:1em 0;font-size:0.9em;';
            p.textContent = 'No shared metrics for this pair.';
            container.appendChild(p);
            return;
        }
        for (const row of rows) {
            const hdr = document.createElement('div');
            hdr.style.cssText = 'margin-top:1em;margin-bottom:0.4em;font-weight:600;color:#334155;font-size:0.85em;';
            hdr.textContent = row.label;
            container.appendChild(hdr);
            const rowDiv = document.createElement('div');
            rowDiv.className = 'scan-metrics-panel' + (isSummary ? ' summary-grid' : '');
            rowDiv.style.marginBottom = '0.75em';
            container.appendChild(rowDiv);
            for (const card of row.cards) {
                const cardDiv = document.createElement('div');
                cardDiv.className = 'metric-item';
                rowDiv.appendChild(cardDiv);
                const lblDiv = document.createElement('div');
                lblDiv.className = 'metric-label';
                // For entity cards (not the Δ card) show the metric as secondary text
                // so it's always clear what's being shown even when scrolling past the heading
                if (card.sublabel) {
                    lblDiv.title = `${card.label} — ${card.sublabel}`;
                }
                lblDiv.textContent = card.label;
                cardDiv.appendChild(lblDiv);
                if (isSummary) {
                    createCardHistogram(cardDiv, card.data, card.label, card.color, card.type);
                } else {
                    const valEl = document.createElement('div');
                    valEl.className = 'metric-value';
                    const v = card.data;
                    if (v == null) { valEl.textContent = 'N/A'; valEl.style.color = '#94a3b8'; }
                    else if (card.type === 'frequency') valEl.textContent = formatFrequency(v);
                    else valEl.textContent = formatCount(v);
                    cardDiv.appendChild(valEl);
                }
            }
        }
    }

    function updateStoppingCriteriaVisibility(plot) {
        // Don't override the row when noise view is active — it has its own logic
        const activeMode = document.querySelector('#scan-view-mode button.is-active');
        if (activeMode && activeMode.dataset.value === 'noise') return;

        const row = document.getElementById('stopping-criteria-row');
        if (!row) return;
        const d = plot ? _phaseData(plot) : null;
        const hasFreq = d && (_mv(d, 'freq_converged_step') != null || _mv(d, 'steps_to_fb') != null);
        const hasAll  = d && _mv(d, 'all_converged_step') != null;
        row.style.display = (hasFreq || hasAll) ? '' : 'none';
        // Disable individual buttons if the data isn't available
        const btns = row.querySelectorAll('button[data-value]');
        for (const btn of btns) {
            const v = btn.dataset.value;
            if (v === 'freq_converged') btn.disabled = !hasFreq;
            else if (v === 'all_converged') btn.disabled = !hasAll;
            else btn.disabled = false;
        }
        // If current criteria is now unavailable, reset to 'full'
        if ((currentStoppingCriteria === 'freq_converged' && !hasFreq) ||
            (currentStoppingCriteria === 'all_converged' && !hasAll)) {
            setStoppingCriteria('full');
        }
    }

    function updateStoppingCriteriaForNoiseView(generator) {
        const row = document.getElementById('stopping-criteria-row');
        if (!row) return;
        const summaryPlots = plots.filter(p => p.type === 'summary' && p.generator === generator);
        const hasFreq = summaryPlots.some(p => p.metric === 'freq_converged_step');
        const hasAll  = summaryPlots.some(p => p.metric === 'all_converged_step');
        row.style.display = (hasFreq || hasAll) ? '' : 'none';
        const btns = row.querySelectorAll('button[data-value]');
        for (const btn of btns) {
            const v = btn.dataset.value;
            if (v === 'freq_converged') btn.disabled = !hasFreq;
            else if (v === 'all_converged') btn.disabled = !hasAll;
            else btn.disabled = false;
        }
        // If current criteria is unavailable for this generator, reset to 'full'
        if ((currentStoppingCriteria === 'freq_converged' && !hasFreq) ||
            (currentStoppingCriteria === 'all_converged' && !hasAll)) {
            setStoppingCriteria('full');
        }
    }

    function setStoppingCriteria(value) {
        currentStoppingCriteria = value;
        const group = document.getElementById('scan-stopping-criteria');
        if (group) {
            group.querySelectorAll('button').forEach(b => {
                const active = b.dataset.value === value;
                b.classList.toggle('is-active', active);
                b.setAttribute('aria-checked', String(active));
                b.tabIndex = active ? 0 : -1;
            });
        }
        applyStoppingFrameLimit();
        // Refresh summary plots if the noise-sweep view is visible
        const noiseView = document.getElementById('noise-metrics-view');
        if (noiseView && !noiseView.hidden) {
            updateNoiseSweepPlots(controlValue(scanGenerator));
        }
    }

    function setupRepeatComparisonUI(plot) {
        const selContainer = document.getElementById('scan-comparison-selector');
        const cardContainer = document.getElementById('scan-comparison-cards');
        if (!selContainer || !cardContainer) return;
        selContainer.innerHTML = '';
        cardContainer.innerHTML = '';
        const entities = buildRepeatEntities(plot);
        if (entities.length < 2) return;

        // Determine which entity IDs to pre-select based on stopping criteria and current strategy
        const currentStrategy = plot ? plot.strategy : null;
        const currentId = currentStrategy
            ? currentStrategy.toLowerCase().replace(/[^a-z0-9]/g, '_')
            : null;
        let defaultAId = entities[0].id;
        let defaultBId = entities[1].id;
        if (currentId) {
            const suffix = currentStoppingCriteria === 'freq_converged' ? '_freq'
                         : currentStoppingCriteria === 'all_converged'  ? '_conv'
                         : '';
            const preferred = currentId + suffix;
            const found = entities.find(e => e.id === preferred) || entities.find(e => e.id === currentId);
            if (found) defaultAId = found.id;
            // Pick a different entity for B
            const bEntity = entities.find(e => e.id !== defaultAId);
            if (bEntity) defaultBId = bEntity.id;
        }

        // Also restore saved pair if nothing explicit was computed
        if (!currentId && lastComparePairIds.a) {
            const saved = entities.find(e => e.id === lastComparePairIds.a);
            if (saved) defaultAId = saved.id;
        }
        if (lastComparePairIds.b && entities.find(e => e.id === lastComparePairIds.b && e.id !== defaultAId)) {
            defaultBId = lastComparePairIds.b;
        }

        const { wrapper, notify } = buildTwoDropdownSelector(entities, (eA, eB) => {
            lastComparePairIds = { a: eA.id, b: eB.id };
            renderPairwiseCards(buildPairwiseRows(eA, eB), cardContainer, false);
            applyComparisonOverlay(eB);
        }, defaultAId, defaultBId);
        selContainer.appendChild(wrapper);
        notify();
    }

    function createCardHistogram(cardContainer, data, name, color, unitType = null, height = 140) {
        if (!data || data.length === 0) {
            const empty = document.createElement('div');
            empty.style.cssText = `height:${height}px;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:0.9em;font-weight:500;`;
            empty.textContent = 'N/A';
            cardContainer.appendChild(empty);
            return;
        }
        const plotDiv = document.createElement('div');
        plotDiv.style.height = `${height}px`;
        plotDiv.style.width = '100%';
        cardContainer.appendChild(plotDiv);
        let scaledData = data;
        let unit = '';
        if (unitType === 'frequency') {
            let maxAbs = 0;
            for (let i = 0; i < data.length; i++) { const a = Math.abs(data[i]); if (a > maxAbs) maxAbs = a; }
            let factor = 1;
            unit = 'Hz';
            if (maxAbs >= 1e9) { factor = 1e9; unit = 'GHz'; }
            else if (maxAbs >= 1e6) { factor = 1e6; unit = 'MHz'; }
            else if (maxAbs >= 1e3) { factor = 1e3; unit = 'kHz'; }
            scaledData = data.map(v => v != null ? v / factor : null);
        } else if (unitType === 'steps') { unit = 'steps'; }
        else if (unitType === 'measurements') { unit = 'meas.'; }
        else if (unitType === 'ratio') { unit = 'adaptive / sweep'; }

        // Clip the long tail so the populated region fills the axis. These
        // distributions are heavily right-skewed: a fixed-percentile clip still
        // leaves a sparse tail that crushes all the real data into one bar.
        // Use Tukey upper fence (Q3 + 1.5·IQR), which adapts to the skew and
        // trims the tail hard, then bin the kept range into many bins.
        let plotData = scaledData.filter(v => v != null && isFinite(v));
        let binCfg = { autobinx: true };
        let tailNote = null;
        if (plotData.length >= 10) {
            const s = [...plotData].sort((a, b) => a - b);
            const q = f => s[Math.min(s.length - 1, Math.floor(s.length * f))];
            const q1 = q(0.25), q3 = q(0.75), iqr = q3 - q1;
            let lo = Math.max(s[0], q1 - 1.5 * iqr);
            let hi = q3 + 1.5 * iqr;
            // Degenerate skew: when the bulk is a single spike (IQR ≈ 0) the
            // Tukey fence collapses to a zero-width window and the old code fell
            // back to autobin — showing the full impossible tail with every real
            // value crushed into one bar. Fall back to a high percentile so the
            // dense region keeps a visible span; if >95% are identical, walk up
            // to the first strictly-greater value to guarantee non-zero width.
            if (!(hi > lo)) {
                lo = s[0];
                hi = q(0.95);
                if (!(hi > lo)) {
                    const firstBigger = s.find(v => v > lo);
                    hi = firstBigger != null ? firstBigger : lo + (Math.abs(lo) || 1) * 1e-6;
                }
            }
            if (hi > lo) {
                const clipped = plotData.filter(v => v > hi);
                plotData = plotData.filter(v => v >= lo && v <= hi);
                const nbins = 30;
                binCfg = { xbins: { start: lo, end: hi, size: (hi - lo) / nbins } };
                if (clipped.length) {
                    const maxTail = Math.max(...clipped);
                    const fmt = v => Math.abs(v) >= 100 ? v.toFixed(0)
                        : Math.abs(v) >= 1 ? v.toFixed(2) : Number(v.toPrecision(3)).toString();
                    tailNote = `▸ tail ${clipped.length} pt${clipped.length > 1 ? 's' : ''} · max ${fmt(maxTail)}`;
                }
            }
        }

        const histX = plotData;

        Plotly.newPlot(plotDiv, [{
            x: histX, type: 'histogram', name,
            marker: { color, line: { color: 'rgba(255,255,255,0.6)', width: 0.5 } },
            opacity: 0.85, ...binCfg,
        }], {
            margin: { l: 25, r: 10, t: 10, b: 25 },
            xaxis: {
                title: { text: unit, font: { size: 9, color: '#64748b', family: 'system-ui, sans-serif' } },
                tickfont: { size: 8, color: '#64748b' }, showgrid: true, gridcolor: '#f1f5f9', zeroline: true, zerolinecolor: '#cbd5e1',
            },
            yaxis: { tickfont: { size: 8, color: '#64748b' }, showgrid: true, gridcolor: '#f1f5f9' },
            showlegend: false, plot_bgcolor: 'transparent', paper_bgcolor: 'transparent',
            bargap: 0.05, dragmode: false, hovermode: 'x',
            annotations: tailNote ? [{
                xref: 'paper', yref: 'paper', x: 0.98, y: 0.96, xanchor: 'right', yanchor: 'top',
                text: tailNote, showarrow: false,
                font: { size: 8, color: '#94a3b8', family: 'system-ui, sans-serif' },
                bgcolor: 'rgba(255,255,255,0.75)', borderpad: 2,
            }] : [],
        }, { displayModeBar: false, responsive: true });
    }

    function renderRepeatsSummary(generator, noise) {
        const selContainer = document.getElementById('summary-comparison-selector');
        const container = document.getElementById('summary-subjects-container');
        const noiseKey = Array.isArray(noise) ? [...noise].sort().join(',') : (noise || '');
        const currentKey = `${generator}|${noiseKey}`;
        if (currentKey === lastSummaryKey) {
            window.dispatchEvent(new Event('resize'));
            return;
        }
        lastSummaryKey = currentKey;
        if (selContainer) selContainer.innerHTML = '';
        if (container) container.innerHTML = '';

        const spanContainer = document.getElementById('summary-span-container');
        if (spanContainer) spanContainer.style.display = 'none';

        const entities = buildSummaryEntities(generator, Array.isArray(noise) ? noise : [noise]);
        if (!entities.length) {
            if (container) {
                const ph = document.createElement('div');
                ph.style.cssText = 'padding:3em 2em;color:#64748b;text-align:center;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;margin:1em 0;';
                ph.innerHTML = '💡 <strong>Not enough data.</strong><br><span style="font-size:0.9em;color:#94a3b8;display:block;margin-top:0.5em;">Run at least one strategy for this generator and noise configuration.</span>';
                container.appendChild(ph);
            }
            return;
        }

        ensurePlotly().then(() => {
            if (!container) return;
            // Defer one frame so the CSS grid has its final width before Plotly
            // sizes the histograms — otherwise they paint at a fallback width and
            // overlap until the next resize. Nudge a resize after paint as a belt.
            requestAnimationFrame(() => {
                if (lastSummaryKey !== currentKey) return; // selection changed mid-frame
                renderEntityCards(entities, container, true, 'accuracy');
                requestAnimationFrame(() => window.dispatchEvent(new Event('resize')));
            });
        });
    }

    function renderSavingsVsSpanChart(eA, eB) {
        const container = document.getElementById('summary-span-container');
        const plotDiv = document.getElementById('summary-span-plot-div');
        if (!container || !plotDiv) return;

        const mapA = {};
        for (let i = 0; i < eA.repeats.length; i++) {
            const r = eA.repeats[i];
            if (r != null) {
                mapA[r] = { step: eA.steps[i], f_span: eA.f_spans[i] };
            }
        }

        const xs = [];
        const ys = [];
        for (let i = 0; i < eB.repeats.length; i++) {
            const r = eB.repeats[i];
            if (r != null && mapA[r] !== undefined) {
                const valA = mapA[r].step;
                const valB = eB.steps[i];
                const f_span = mapA[r].f_span;
                if (valA != null && valB != null && f_span != null) {
                    xs.push(f_span);
                    ys.push(valB - valA);
                }
            }
        }

        if (xs.length === 0) {
            container.style.display = 'none';
            return;
        }

        container.style.display = 'block';

        const trace = {
            x: xs,
            y: ys,
            mode: 'markers',
            type: 'scatter',
            name: `${eB.label} vs ${eA.label}`,
            marker: {
                color: 'rgba(56, 189, 248, 0.7)',
                size: 8,
                line: {
                    color: 'rgba(3, 105, 161, 0.9)',
                    width: 1
                }
            },
            hovertemplate: 'f_span=%{x:.4e}<br>saved steps=%{y}<extra></extra>'
        };

        const layout = {
            title: {
                text: `Measurement Savings: ${eB.label} vs ${eA.label}`,
                font: { size: 14, color: '#334155', family: 'system-ui, sans-serif', weight: '600' }
            },
            xaxis: {
                title: { text: 'Fractional Signal Span (f_span)', font: { size: 11, color: '#64748b' } },
                type: 'log',
                tickfont: { size: 9, color: '#64748b' },
                showgrid: true,
                gridcolor: '#f1f5f9'
            },
            yaxis: {
                title: { text: `Steps Saved (${eB.label} - ${eA.label})`, font: { size: 11, color: '#64748b' } },
                tickfont: { size: 9, color: '#64748b' },
                showgrid: true,
                gridcolor: '#f1f5f9',
                zeroline: true,
                zerolinecolor: '#cbd5e1'
            },
            margin: { l: 50, r: 20, t: 40, b: 50 },
            plot_bgcolor: 'transparent',
            paper_bgcolor: 'transparent',
            dragmode: false
        };

        ensurePlotly().then(() => {
            Plotly.newPlot(plotDiv, [trace], layout, { displayModeBar: false, responsive: true });
        });
    }

    // ── Highlights view ───────────────────────────────────────────────────────
    // Curated quick view answering four questions with only fair comparisons:
    //   1. Error vs measurements (anytime curves; sweep = practical baseline)
    //   2. Convergence vs measurements (survival curves; adaptive locators only)
    //   3. Uncertainty calibration (coverage of claimed uncertainty vs Gaussian nominals)
    //   4. Savings vs signal span (paired, matched-promise) + search/refine split
    const HL_NOMINAL_1S = 0.683;
    const HL_NOMINAL_2S = 0.954;
    const HL_NOMINAL_3S = 0.997;
    const HL_COLORS = ['#2563eb', '#f59e0b', '#10b981', '#8b5cf6', '#ec4899', '#ef4444', '#06b6d4', '#14b8a6'];
    let hlTauMult = 1;
    let hlSpeedCriteria = 'freq';  // 'freq' | 'all'
    let hlLastArgs = null;

    function isSweepBaseline(strategy) {
        return /sweep/i.test(strategy || '') && !/sobol/i.test(strategy || '');
    }

    function hlSorted(values) {
        return values.filter(v => v != null && isFinite(v)).sort((a, b) => a - b);
    }
    function hlQuantileSorted(sorted, q) {
        if (!sorted.length) return null;
        const pos = (sorted.length - 1) * q;
        const lo = Math.floor(pos), hi = Math.ceil(pos);
        return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
    }
    function hlMedian(values) { return hlQuantileSorted(hlSorted(values), 0.5); }

    // Collapse a scatter (xs,ys) into per-bin median + IQR over log-spaced x bins.
    // Returns {cx, med, lo, hi, n} arrays (one entry per non-empty bin with >= minN
    // points), so a dense cloud reads as a trend line with a spread band.
    function hlLogBinMedian(xs, ys, nBins = 25, minN = 3) {
        const pts = [];
        for (let i = 0; i < xs.length; i++) {
            if (xs[i] > 0 && Number.isFinite(ys[i])) pts.push([xs[i], ys[i]]);
        }
        const out = { cx: [], med: [], lo: [], hi: [], n: [] };
        if (pts.length < minN) return out;
        let xmin = Infinity, xmax = -Infinity;
        for (const [x] of pts) { if (x < xmin) xmin = x; if (x > xmax) xmax = x; }
        const lmin = Math.log(xmin), lmax = Math.log(xmax);
        const span = lmax - lmin || 1;
        const bins = Array.from({ length: nBins }, () => []);
        for (const [x, y] of pts) {
            let b = Math.floor(((Math.log(x) - lmin) / span) * nBins);
            if (b >= nBins) b = nBins - 1;
            if (b < 0) b = 0;
            bins[b].push([x, y]);
        }
        for (const bin of bins) {
            if (bin.length < minN) continue;
            const bx = hlSorted(bin.map(p => p[0]));
            const by = hlSorted(bin.map(p => p[1]));
            out.cx.push(hlQuantileSorted(bx, 0.5));
            out.med.push(hlQuantileSorted(by, 0.5));
            out.lo.push(hlQuantileSorted(by, 0.25));
            out.hi.push(hlQuantileSorted(by, 0.75));
            out.n.push(bin.length);
        }
        return out;
    }

    // Build a log-binned median line (+ IQR band) trace pair for one (xs,ys) cloud.
    // Returns { traces, bin } so callers can reuse the bin for guide-line anchoring.
    function hlBinnedLineTraces(xs, ys, color, name, opts = {}) {
        const { dash = null, fillAlpha = 0.12, symbol = 'circle', lineColor = color, showlegend = true, hoverY = 'value' } = opts;
        const bin = hlLogBinMedian(xs, ys);
        if (!bin.cx.length) return { traces: [], bin };
        const band = {
            x: bin.cx.concat([...bin.cx].reverse()),
            y: bin.hi.concat([...bin.lo].reverse()),
            fill: 'toself', fillcolor: hlHexToRgba(color, fillAlpha),
            line: { width: 0, shape: 'spline' }, mode: 'lines', type: 'scatter', hoverinfo: 'skip', showlegend: false,
        };
        const line = {
            x: bin.cx, y: bin.med, mode: 'lines+markers', type: 'scatter', name,
            line: { color: lineColor, width: 2.5, shape: 'spline', smoothing: 0.8, ...(dash ? { dash } : {}) },
            marker: { color: lineColor, size: 4, symbol },
            customdata: bin.n, showlegend,
            hovertemplate: `f_span %{x:.2e}<br>${hoverY} %{y:.3g}<br>n=%{customdata}<extra>${name}</extra>`,
        };
        return { traces: [band, line], bin };
    }

    // Search/refine decomposition traces for one slice of runs (one noise facet).
    function hlBuildDecompTraces(runsByStrat, strategies, adaptive, showlegend) {
        const dTraces = [];
        for (const strat of adaptive) {
            const runs = runsByStrat.get(strat) || [];
            const sx = [], sy = [], rx = [], ry = [];
            for (const p of runs) {
                if (!p.series) continue;
                const fSpan = hlFSpan(p);
                if (fSpan == null) continue;
                const first = hlFirstSignalStep(p.series);
                const conv = hlConvStep(p, hlTauMult);
                if (first != null) { sx.push(fSpan); sy.push(first); }
                if (first != null && conv != null && conv >= first) { rx.push(fSpan); ry.push(Math.max(conv - first, 1)); }
            }
            const color = hlStratColor(strategies, strat);
            if (sx.length) dTraces.push({ x: sx, y: sy, mode: 'markers', type: 'scatter', showlegend: false, hoverinfo: 'skip',
                marker: { color: hlHexToRgba(color, 0.12), size: 2, symbol: 'circle' } });
            if (rx.length) dTraces.push({ x: rx, y: ry, mode: 'markers', type: 'scatter', showlegend: false, hoverinfo: 'skip',
                marker: { color: hlHexToRgba(color, 0.12), size: 2, symbol: 'diamond' } });
            const s = hlBinnedLineTraces(sx, sy, color, `${_shortStratLabel(strat)} search`,
                { symbol: 'circle', showlegend, hoverY: 'median steps to first signal' });
            const r = hlBinnedLineTraces(rx, ry, color, `${_shortStratLabel(strat)} refine`,
                { symbol: 'diamond', dash: 'dot', lineColor: hlHexToRgba(color, 0.55), fillAlpha: 0.08, showlegend, hoverY: 'median refine steps' });
            dTraces.push(...s.traces, ...r.traces);
        }
        return dTraces;
    }

    // Uncertainty-at-convergence vs f_span traces for one slice of runs.
    function hlBuildUncertTraces(runsByStrat, strategies, adaptive, showlegend) {
        const dTraces = [];
        for (const strat of adaptive) {
            const runs = runsByStrat.get(strat) || [];
            const xs = [], ys = [];
            for (const p of runs) {
                if (!p.series) continue;
                const fSpan = hlFSpan(p);
                if (fSpan == null) continue;
                const conv = hlConvStep(p, hlTauMult);
                if (conv == null) continue;
                const u = hlSeriesValueAt(p.series, 'u', conv);
                if (u != null && u > 0) { xs.push(fSpan); ys.push(u); }
            }
            const color = hlStratColor(strategies, strat);
            if (xs.length) dTraces.push({ x: xs, y: ys, mode: 'markers', type: 'scatter', showlegend: false, hoverinfo: 'skip',
                marker: { color: hlHexToRgba(color, 0.18), size: 4, symbol: 'circle' } });
            const t = hlBinnedLineTraces(xs, ys, color, `${_shortStratLabel(strat)}`,
                { symbol: 'circle', showlegend, hoverY: 'median σ at convergence' });
            dTraces.push(...t.traces);
        }
        return dTraces;
    }

    // Deterministic PRNG so bootstrap intervals are stable across re-renders.
    function hlMulberry32(seed) {
        return function () {
            seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
            let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function hlBootstrapMedianCI(values, B = 300) {
        const vals = hlSorted(values);
        if (vals.length < 3) return null;
        const rand = hlMulberry32(vals.length * 7919 + 17);
        const medians = new Array(B);
        const sample = new Array(vals.length);
        for (let b = 0; b < B; b++) {
            for (let i = 0; i < vals.length; i++) sample[i] = vals[(rand() * vals.length) | 0];
            sample.sort((x, y) => x - y);
            medians[b] = hlQuantileSorted(sample, 0.5);
        }
        medians.sort((x, y) => x - y);
        return [hlQuantileSorted(medians, 0.025), hlQuantileSorted(medians, 0.975)];
    }
    function hlWilson(k, n) {
        if (!n) return null;
        const z = 1.96, p = k / n, z2 = z * z;
        const denom = 1 + z2 / n;
        const center = (p + z2 / (2 * n)) / denom;
        const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / denom;
        return { p, lo: Math.max(0, center - half), hi: Math.min(1, center + half) };
    }

    // Series helpers — series is {s: steps[], e: errors[], u: uncertainties[], tau}
    function hlSeriesValueAt(series, key, step) {
        const s = series.s, arr = series[key];
        let v = null;
        for (let i = 0; i < s.length && s[i] <= step; i++) {
            if (arr[i] != null) v = arr[i];
        }
        return v;
    }
    function hlFirstStepBelow(series, key, threshold) {
        for (let i = 0; i < series.s.length; i++) {
            const v = series[key][i];
            if (v != null && v < threshold) return series.s[i];
        }
        return null;
    }
    function hlFirstSignalStep(series) {
        // Proxy for first informative observation: the claimed uncertainty
        // first halves from its initial value.
        let u0 = null;
        for (let i = 0; i < series.u.length; i++) {
            if (series.u[i] != null) { u0 = series.u[i]; break; }
        }
        return u0 == null ? null : hlFirstStepBelow(series, 'u', 0.5 * u0);
    }
    function hlFSpan(p) {
        const tp = p.true_params;
        if (!tp || !tp.params) return null;
        const lw = tp.params.linewidth;
        const split = tp.params.split || 0.0;
        let domainWidth = 5.0e8;
        const fb = tp.bounds && tp.bounds.frequency;
        if (fb && fb.length === 2 && fb[1] > fb[0]) domainWidth = fb[1] - fb[0];
        return (lw && lw > 0) ? Math.max(2.0 * lw, split + lw) / domainWidth : null;
    }
    function hlConvStep(p, mult) {
        // 'u' (frequency uncertainty) and 'tau' (its threshold) in the series are
        // the SAME quantities behind the backend's freq_converged_step. At the
        // standard threshold the milestone is exact and full-resolution — use it
        // directly, and treat null as "did not converge" rather than falling
        // through to the downsampled series (whose finalize-overridden endpoint
        // can fake a crossing). Only the τ-sensitivity views fall back to the
        // series, the only data available at multipliers other than 1×.
        //
        // Limitation: because exact data exists only at 1×, a τ slightly above 1×
        // (looser) can land on a later downsampled grid point than the exact 1×
        // step. Accepted tradeoff — the 1× false-positive is what we eliminate.
        if (mult === 1) return p.freq_converged_step ?? null;
        const ser = p.series;
        if (ser && ser.u && ser.tau != null) return hlFirstStepBelow(ser, 'u', ser.tau * mult);
        return null;
    }
    function hlRunSteps(p) {
        return p.measurements ?? (p.series && p.series.s.length ? p.series.s[p.series.s.length - 1] : null);
    }
    // Matched quality vs the sweep: first step where the median anytime error
    // reaches the target (the full sweep's delivered accuracy).
    function hlCrossStep(seriesRuns, target) {
        if (!seriesRuns.length || target == null) return null;
        const maxStep = Math.max(...seriesRuns.map(p => hlRunSteps(p) || 1));
        for (const step of hlStepGrid(maxStep, 120)) {
            const med = hlMedian(seriesRuns.map(p => hlSeriesValueAt(p.series, 'e', step)));
            if (med != null && med <= target) return step;
        }
        return null;
    }
    // Censoring check for a non-converged run: was the claimed uncertainty
    // still falling in the last 20% of the budget? If yes, the run was
    // budget-censored (more steps would help); if flat, it stalled and a
    // bigger budget is wasted compute.
    function hlStillImproving(p) {
        const ser = p.series;
        if (!ser || !ser.u || !ser.s.length) return null;
        const lastStep = ser.s[ser.s.length - 1];
        const uLate = hlSeriesValueAt(ser, 'u', Math.max(1, Math.floor(lastStep * 0.8)));
        const uFinal = hlSeriesValueAt(ser, 'u', lastStep);
        if (uLate == null || uFinal == null || uLate <= 0) return null;
        return uFinal < 0.95 * uLate;
    }
    function sortNoiseLabels(noises) {
        return [...noises].sort((a, b) => {
            const ga = String(a).match(/Gauss\(([\d.]+)\)/);
            const gb = String(b).match(/Gauss\(([\d.]+)\)/);
            if (ga && gb) return parseFloat(ga[1]) - parseFloat(gb[1]);
            if (ga) return -1;
            if (gb) return 1;
            return String(a).localeCompare(String(b));
        });
    }
    function noiseSigma(noise) {
        const m = String(noise).match(/Gauss\(([\d.]+)\)/);
        return m ? parseFloat(m[1]) : null;
    }

    function isSuccessRun(p) { return p.failure_reason == null; }

    // Normalizes the aggregate-view "generator" argument (single string in the
    // plain-generator case, array in Width/Contrast-style multi-select) into a
    // Set for membership checks, mirroring the noise-array handling above.
    function toGenSet(gen) {
        return new Set((Array.isArray(gen) ? gen : [gen]).filter(Boolean));
    }

    function hlCollect(generator, noises) {
        const noiseSet = new Set((Array.isArray(noises) ? noises : [noises]).filter(Boolean));
        const genSet = toGenSet(generator);
        const byStrategy = new Map();
        for (const p of scanPlots) {
            if (!genSet.has(p.generator) || !noiseSet.has(p.noise) || !p.strategy) continue;
            if (p.generator === 'Dummy-Generator') continue;
            if (!isSuccessRun(p)) continue;
            if (!byStrategy.has(p.strategy)) byStrategy.set(p.strategy, []);
            byStrategy.get(p.strategy).push(p);
        }
        return byStrategy;
    }

    function hlStepGrid(maxStep, nPoints = 60) {
        const grid = [];
        const head = Math.min(10, maxStep);
        for (let i = 1; i <= head; i++) grid.push(i);
        if (maxStep > head) {
            const ratio = maxStep / head;
            const rem = Math.max(nPoints - head, 8);
            for (let k = 1; k <= rem; k++) {
                const v = Math.round(head * Math.pow(ratio, k / rem));
                if (v > grid[grid.length - 1]) grid.push(v);
            }
        }
        return grid;
    }

    function hlStratColor(strategies, strategy) {
        return HL_COLORS[strategies.indexOf(strategy) % HL_COLORS.length];
    }
    function hlHexToRgba(hex, alpha) {
        const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
        return `rgba(${r},${g},${b},${alpha})`;
    }

    const hlBaseLayout = () => ({
        template: 'plotly_white',
        margin: { t: 30, b: 55, l: 65, r: 15 },
        hovermode: 'closest',
        legend: { orientation: 'h', yanchor: 'bottom', y: 1.02, xanchor: 'right', x: 1, font: { size: 10 } },
        xaxis: { gridcolor: '#f1f5f9' },
        yaxis: { gridcolor: '#f1f5f9' },
        plot_bgcolor: 'transparent',
        paper_bgcolor: 'transparent',
    });

    function renderHighlights(generator, noises) {
        const view = document.getElementById('highlights-view');
        if (!view || !generator) return;
        hlLastArgs = { generator, noises };
        const byStrategy = hlCollect(generator, noises);
        const strategies = [...byStrategy.keys()].sort();
        const sweepCandidates = strategies.filter(isSweepBaseline);
        const sweepName = sweepCandidates.find(s => /^SimpleSweep/.test(s)) || sweepCandidates[0] || null;

        const warn = document.getElementById('hl-warning');
        if (warn) {
            const missing = strategies.filter(s => !byStrategy.get(s).some(p => p.series));
            warn.innerHTML = '';
            if (strategies.length === 0) {
                warn.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;">No scan data for this generator/noise selection.</div>';
                ['hl-headline', 'hl-error-curves', 'hl-survival', 'hl-coverage', 'hl-span', 'hl-firstsignal'].forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.innerHTML = '';
                });
                return;
            }
            if (missing.length) {
                warn.innerHTML = `<div style="padding:0.6em 1em;color:#92400e;background:#fef3c7;border:1px solid #fde68a;border-radius:6px;font-size:0.85em;margin-bottom:0.8em;">No per-step series for: ${missing.join(', ')} — these runs predate the series export. Re-run (or recalculate with <code>--no-cache</code>) to include them in the curve panels.</div>`;
            }
        }

        hlSetupControls(byStrategy, strategies, sweepName);
        ensurePlotly().then(() => {
            renderHlErrorCurves(byStrategy, strategies, sweepName);
            renderHlSurvival(byStrategy, strategies, sweepName);
            renderHlCoverage(byStrategy, strategies);
            renderHlSpan(byStrategy, strategies, sweepName);
            renderHlHeadline(byStrategy, strategies, sweepName);
        });
    }

    // Reflect the current hlTauMult onto the shared τ control's active button.
    function syncTauControl() {
        const tauGroup = document.getElementById('hl-tau-select');
        if (!tauGroup) return;
        tauGroup.querySelectorAll('button').forEach(b => {
            const active = parseFloat(b.dataset.value) === hlTauMult;
            b.classList.toggle('is-active', active);
            b.setAttribute('aria-checked', active ? 'true' : 'false');
            b.tabIndex = active ? 0 : -1;
        });
    }

    // Wire the shared τ control once. Changing τ updates hlTauMult and re-renders
    // the active Compare axis, so every τ-sensitive view (Highlights, Pooled)
    // stays in sync regardless of which axis the user is on.
    function setupTauControl() {
        const tauGroup = document.getElementById('hl-tau-select');
        if (!tauGroup || tauGroup._hasListener) return;
        tauGroup.addEventListener('click', (e) => {
            const btn = e.target.closest('button[data-value]');
            if (!btn) return;
            hlTauMult = parseFloat(btn.dataset.value);
            syncTauControl();
            const active = document.querySelector('#scan-view-mode button.is-active');
            if (active && active.dataset.value === 'speed') showScanViewPanels('speed');
        });
        tauGroup._hasListener = true;
    }

    function hlSetupControls(byStrategy, strategies, sweepName) {
        setupTauControl();
        // The savings baseline is always the SimpleSweep — no chooser.
    }

    function renderSpeedEntityCards(gen, noises) {
        const container = document.getElementById('speed-subjects-container');
        if (!container) return;
        const noiseArr = Array.isArray(noises) ? noises : (noises ? [noises] : []);
        const entities = buildSummaryEntities(gen, noiseArr);
        if (!entities.length) { container.innerHTML = ''; return; }
        ensurePlotly().then(() => {
            requestAnimationFrame(() => {
                renderEntityCards(entities, container, true, 'speed');
                requestAnimationFrame(() => window.dispatchEvent(new Event('resize')));
            });
        });
    }

    // ── Speed tab ────────────────────────────────────────────────────────────

    function renderSpeedTab(gen, noises) {
        if (toGenSet(gen).size === 0) return;
        hlLastArgs = { generator: gen, noises };
        const byStrategy = hlCollect(gen, noises);
        const strategies = [...byStrategy.keys()].sort();
        const sweepName = strategies.filter(isSweepBaseline).find(s => /^SimpleSweep/.test(s))
            || strategies.filter(isSweepBaseline)[0] || null;

        const warn = document.getElementById('hl-warning');
        if (warn) {
            warn.innerHTML = '';
            if (!strategies.length) {
                warn.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;">No scan data for this generator/noise selection.</div>';
                ['hl-headline', 'hl-error-curves', 'hl-survival', 'hl-span', 'hl-firstsignal'].forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.innerHTML = '';
                });
                return;
            }
        }

        hlSetupControls(byStrategy, strategies, sweepName);
        const speedView = document.getElementById('speed-view');
        if (speedView) speedView.dataset.renderDebug = `renderSpeedTab called: gen=${gen}, noises=${JSON.stringify(noises)}, strategies=${strategies.length}`;
        ensurePlotly().then(() => {
            if (speedView) speedView.dataset.renderDebug += ' | Plotly ready';
            renderHlErrorCurves(byStrategy, strategies, sweepName);
            renderHlSurvival(byStrategy, strategies, sweepName);
            renderHlHeadline(byStrategy, strategies, sweepName);
            renderSpeedNoise(gen);
            renderSpeedSpan();
            renderHlSpan(byStrategy, strategies, sweepName);
            renderSpeedEntityCards(gen, noises);
        }).catch(err => {
            const warn = document.getElementById('hl-warning');
            if (warn) warn.innerHTML = `<div style="padding:1em;color:#721c24;background:#f8d7da;border:1px solid #f5c6cb;border-radius:6px;margin:1em 0;"><strong>Speed render error:</strong> ${err.message || err}<br><pre style="white-space:pre-wrap;font-size:11px">${err.stack || ''}</pre></div>`;
        });
    }

    function renderSpeedNoise(gen) {
        const container = document.getElementById('speed-noise-content');
        if (!container) return;
        container.innerHTML = '';

        const genPlots = scanPlots.filter(p => toGenSet(gen).has(p.generator));
        const noises = sortNoiseLabels([...new Set(genPlots.map(p => p.noise))].filter(Boolean));
        const strategies = [...new Set(genPlots.map(p => p.strategy))].filter(Boolean).sort();
        const adaptive = strategies.filter(s => !isSweepBaseline(s));
        const sweepName = strategies.filter(isSweepBaseline).find(s => /^SimpleSweep/.test(s))
            || strategies.filter(isSweepBaseline)[0] || null;

        if (!strategies.length || !noises.length) {
            container.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;">No data for this generator.</div>';
            return;
        }

        const cellConv = new Map();
        for (const noise of noises) {
            const cell = dashCell(gen, noise);
            const sweepRuns = sweepName ? (cell.get(sweepName) || []) : [];
            const sweepMeasMed = sweepRuns.length ? hlMedian(sweepRuns.map(p => hlRunSteps(p)).filter(v => v != null)) : null;
            for (const strat of strategies) {
                const runs = cell.get(strat) || [];
                if (!runs.length) continue;
                const isSweep = isSweepBaseline(strat);
                const convSteps = isSweep
                    ? runs.map(p => hlRunSteps(p)).filter(v => v != null)
                    : runs.map(p => hlConvStep(p, hlTauMult)).filter(v => v != null);
                const medConv = convSteps.length ? hlMedian(convSteps) : null;
                const k = (!isSweep && medConv != null && sweepMeasMed != null) ? sweepMeasMed / medConv : null;
                const saved = (!isSweep && sweepMeasMed != null && medConv != null) ? sweepMeasMed - medConv : null;
                cellConv.set(`${strat}|${noise}`, { medConv, sweepMeasMed, k, saved, n: runs.length, convN: convSteps.length });
            }
        }

        // Mode (biggest histogram bin) of paired per-repeat speedup ratios.
        // "How much better SBED is" — one number per noise, plus one over all repeats.
        if (sweepName && adaptive.length) {
            // Log-spaced bins (per factor of √2): speedups span a wide range (single×
            // to several-hundred×) and k = sweep_steps / small_integer snaps to
            // discrete spikes, so linear bins would crown a few lucky fast runs.
            // Fold-change bins give the meaningful "most likely speedup".
            // Median of a ratio list.
            const medianK = (ks) => {
                if (!ks.length) return null;
                return { mid: hlMedian(ks), count: ks.length };
            };

            // Sweep total steps per repeat, per noise (pairing key = p.repeat).
            const sweepByNoiseRepeat = {};
            for (const noise of noises) {
                const byRepeat = new Map();
                (dashCell(gen, noise).get(sweepName) || []).forEach(p => {
                    const v = hlRunSteps(p);
                    if (v != null && p.repeat != null) byRepeat.set(p.repeat, v);
                });
                sweepByNoiseRepeat[noise] = byRepeat;
            }

            // Paired k_i = sweep_steps / sbed_conv_steps, per (noise, strat); pooled for overall.
            const perNoiseKs = {};   // noise -> strat -> [k_i]
            const allKByStrat = {};  // strat -> [all k_i across noises]
            for (const noise of noises) {
                perNoiseKs[noise] = {};
                const cell = dashCell(gen, noise);
                const sweepByRepeat = sweepByNoiseRepeat[noise];
                for (const strat of adaptive) {
                    const ks = [];
                    (cell.get(strat) || []).forEach(p => {
                        const adaptiveSteps = hlSpeedCriteria === 'all'
                            ? (p.all_converged_step ?? null)
                            : hlConvStep(p, hlTauMult);
                        const sweepSteps = p.repeat != null ? sweepByRepeat.get(p.repeat) : null;
                        if (adaptiveSteps != null && sweepSteps != null && adaptiveSteps > 0) {
                            ks.push(sweepSteps / adaptiveSteps);
                        }
                    });
                    perNoiseKs[noise][strat] = ks;
                    (allKByStrat[strat] = allKByStrat[strat] || []).push(...ks);
                }
            }

            const fmtX = (v) => v >= 100 ? Math.round(v).toString() : v >= 10 ? v.toFixed(1) : v.toFixed(2);
            const fmt = (b) => b
                ? `${fmtX(b.mid)}× <span style="color:#94a3b8;font-size:0.85em;">(n=${b.count})</span>`
                : '—';

            const tbl = document.createElement('div');
            tbl.style.cssText = 'overflow-x:auto; margin-bottom:1.4em;';
            const th = s => `<th style="padding:4px 10px; text-align:left; border-bottom:2px solid #e2e8f0; white-space:nowrap;">${s}</th>`;
            const td = (s, extra = '') => `<td style="padding:3px 10px; border-bottom:1px solid #f1f5f9; white-space:nowrap; ${extra}">${s}</td>`;
            const criterionLabel = hlSpeedCriteria === 'all' ? 'All params converged' : `Freq converged — τ×${hlTauMult}`;
            const btnStyle = (active) =>
                `cursor:pointer; border:1px solid #cbd5e1; border-radius:3px; padding:1px 7px; font-size:0.78em;` +
                (active ? 'background:#1e40af;color:#fff;' : 'background:#f8fafc;color:#475569;');
            let html = `<div style="display:flex;align-items:center;gap:8px;font-size:0.8em;color:#64748b;margin-bottom:0.4em;flex-wrap:wrap;">`;
            html += `<span>Median speedup vs ${_shortStratLabel(sweepName)} (median of paired step ratios)</span>`;
            html += `<button data-speed-crit="freq" style="${btnStyle(hlSpeedCriteria==='freq')}">Freq</button>`;
            html += `<button data-speed-crit="all"  style="${btnStyle(hlSpeedCriteria==='all')}">All params</button>`;
            html += `<span style="color:#94a3b8">${criterionLabel}</span></div>`;
            html += `<table style="border-collapse:collapse; font-size:0.85em;"><thead><tr>${th('Noise')}${adaptive.map(s => th(_shortStratLabel(s) + ' — median k×')).join('')}</tr></thead><tbody>`;
            for (const noise of noises) {
                html += `<tr>${td(noise)}`;
                for (const strat of adaptive) html += td(fmt(medianK(perNoiseKs[noise][strat])));
                html += '</tr>';
            }
            const topBorder = 'border-top:2px solid #e2e8f0;';
            html += `<tr style="font-weight:600;">${td('Overall', topBorder)}`;
            for (const strat of adaptive) html += td(fmt(medianK(allKByStrat[strat])), topBorder);
            html += '</tr></tbody></table>';
            tbl.innerHTML = html;
            tbl.addEventListener('click', e => {
                const btn = e.target.closest('[data-speed-crit]');
                if (!btn) return;
                hlSpeedCriteria = btn.dataset.speedCrit;
                renderSpeedNoise(gen);
            });
            container.appendChild(tbl);
        }

        const shortNoises = noises.map(n => { const m = n.match(/Gauss\(([\d.]+)\)/); return m ? m[1] : n; });
        const mkXAxis = () => ({ type: 'category', tickangle: -60, tickfont: { size: 9 }, categoryorder: 'array', categoryarray: noises, tickvals: noises, ticktext: shortNoises });

        // Steps to convergence vs noise
        {
            const plotDiv = dashPanelDiv(container,
                `Steps to convergence vs noise — τ×${hlTauMult}`,
                'Median steps to convergence at the current τ threshold. Sweep (dashed) = total measurement count.',
                Math.max(240, 140 + 20 * strategies.length));
            const traces = strategies.map(strat => {
                const color = hlStratColor(strategies, strat);
                const isSweep = isSweepBaseline(strat);
                const ys = [], texts = [];
                for (const noise of noises) {
                    const st = cellConv.get(`${strat}|${noise}`);
                    ys.push(st ? st.medConv : null);
                    texts.push(st ? `${st.convN}/${st.n} converged` : '');
                }
                return {
                    x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                    name: _shortStratLabel(strat),
                    line: { color, width: isSweep ? 2.5 : 2, dash: isSweep ? 'dash' : 'solid' },
                    marker: { color, size: 6 }, text: texts,
                    hovertemplate: '%{y:.0f} steps<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                };
            });
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, ...mkXAxis() };
            layout.yaxis = { ...layout.yaxis, title: { text: 'Median steps', font: { size: 11 } }, rangemode: 'tozero' };
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }

        // k× savings vs noise
        if (sweepName && adaptive.length) {
            const plotDiv = dashPanelDiv(container,
                `k× savings vs noise — τ×${hlTauMult}`,
                'Ratio of sweep total steps to adaptive convergence steps. k=2 = half the measurements. Reference line at k=1.',
                Math.max(240, 140 + 20 * adaptive.length));
            const traces = adaptive.map(strat => {
                const color = hlStratColor(strategies, strat);
                const ys = [], texts = [];
                for (const noise of noises) {
                    const st = cellConv.get(`${strat}|${noise}`);
                    ys.push(st ? st.k : null);
                    texts.push(st && st.k != null
                        ? `${Math.round(st.medConv)} vs ${Math.round(st.sweepMeasMed)} sweep steps (n=${st.convN}/${st.n})`
                        : 'did not converge');
                }
                return {
                    x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                    name: _shortStratLabel(strat),
                    line: { color, width: 2 }, marker: { color, size: 6 }, text: texts,
                    hovertemplate: '%{y:.1f}× faster<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                };
            });
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, ...mkXAxis() };
            layout.yaxis = { ...layout.yaxis, title: { text: 'Median sweep steps / conv steps', font: { size: 11 } }, rangemode: 'tozero' };
            layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 1, y1: 1, line: { color: '#94a3b8', width: 1.5, dash: 'dash' } }];
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }

        // Absolute steps saved vs noise
        if (sweepName && adaptive.length) {
            const plotDiv = dashPanelDiv(container,
                `Steps saved vs noise — τ×${hlTauMult}`,
                'Median absolute steps saved (sweep total − adaptive convergence steps). Positive = faster than sweep.',
                Math.max(240, 140 + 20 * adaptive.length));
            const traces = adaptive.map(strat => {
                const color = hlStratColor(strategies, strat);
                const ys = [], texts = [];
                for (const noise of noises) {
                    const st = cellConv.get(`${strat}|${noise}`);
                    ys.push(st ? st.saved : null);
                    texts.push(st && st.saved != null ? `n=${st.convN}/${st.n}` : 'did not converge');
                }
                return {
                    x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                    name: _shortStratLabel(strat),
                    line: { color, width: 2 }, marker: { color, size: 6 }, text: texts,
                    hovertemplate: '%{y:.0f} steps saved<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                };
            });
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, ...mkXAxis() };
            layout.yaxis = { ...layout.yaxis, title: { text: 'Steps saved (median)', font: { size: 11 } } };
            layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 0, y1: 0, line: { color: '#94a3b8', width: 1.5, dash: 'dash' } }];
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }
    }

    function renderSpeedSpan() {
        const container = document.getElementById('speed-span-content');
        if (!container) return;
        container.innerHTML = '';
        const allStrats = [...new Set(scanPlots.map(p => p.strategy))].filter(Boolean).sort();
        const plotDiv = dashPanelDiv(container,
            `Steps to convergence vs signal span — pooled, τ×${hlTauMult}`,
            'Each run by fractional signal span (linewidth / spectrum width). Log-binned median + IQR band. Sweep shown as total measurement count (dashed).',
            340, true);
        const traces = [];
        for (const strat of allStrats) {
            const isSweep = isSweepBaseline(strat);
            const xs = [], ys = [];
            for (const p of scanPlots) {
                if (p.strategy !== strat || p.generator === 'Dummy-Generator') continue;
                const fSpan = hlFSpan(p);
                if (fSpan == null) continue;
                const step = isSweep ? hlRunSteps(p) : hlConvStep(p, hlTauMult);
                if (step == null) continue;
                xs.push(fSpan); ys.push(step);
            }
            if (!xs.length) continue;
            const color = hlStratColor(allStrats, strat);
            const { traces: t } = hlBinnedLineTraces(xs, ys, color, _shortStratLabel(strat), {
                dash: isSweep ? 'dash' : null, hoverY: 'median steps',
            });
            traces.push(...t);
        }
        if (!traces.length) {
            plotDiv.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No f_span data — runs need linewidth in true_params.</p>';
        } else {
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, title: { text: 'Fractional signal span (f_span)', font: { size: 11 } }, type: 'log' };
            layout.yaxis = { ...layout.yaxis, title: { text: 'Median steps to convergence', font: { size: 11 } } };
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }
    }

    // ── Accuracy tab ─────────────────────────────────────────────────────────

    function renderAccuracyTab(gen, noises) {
        if (toGenSet(gen).size === 0) return;
        hlLastArgs = { generator: gen, noises };
        const byStrategy = hlCollect(gen, noises);
        const strategies = [...byStrategy.keys()].sort();
        const sweepName = strategies.filter(isSweepBaseline).find(s => /^SimpleSweep/.test(s))
            || strategies.filter(isSweepBaseline)[0] || null;

        const accView = document.getElementById('accuracy-view');
        if (accView) accView.dataset.renderDebug = `renderAccuracyTab called: gen=${gen}, noises=${JSON.stringify(noises)}, strategies=${strategies.length}`;
        ensurePlotly().then(() => {
            if (accView) accView.dataset.renderDebug += ' | Plotly ready';
            renderHlCoverage(byStrategy, strategies);
            renderAccuracyNoise(gen);
            renderAccuracySpan();
            renderHlSpan(byStrategy, strategies, sweepName);
            renderRepeatsSummary(gen, noises);
        }).catch(err => {
            const errDiv = accView || document.getElementById('acc-noise-content');
            if (errDiv) {
                const msg = document.createElement('div');
                msg.style.cssText = 'padding:1em;color:#721c24;background:#f8d7da;border:1px solid #f5c6cb;border-radius:6px;margin:1em;';
                msg.innerHTML = `<strong>Accuracy render error:</strong> ${err.message || err}<br><pre style="white-space:pre-wrap;font-size:11px">${err.stack || ''}</pre>`;
                errDiv.prepend(msg);
            }
        });
    }

    // ── Failed Runs tab ───────────────────────────────────────────────────────

    const FAILURE_LABELS = {
        max_steps: 'Max steps exhausted',
        theory_budget: 'Theory budget (CRLB backstop)',
        infeasible_crlb: 'Infeasible CRLB (run skipped)',
        timeout: 'Timeout',
    };

    function collectFailedRuns(generator, noises) {
        const noiseSet = new Set((Array.isArray(noises) ? noises : [noises]).filter(Boolean));
        const genSet = toGenSet(generator);
        return scanPlots.filter(p =>
            genSet.has(p.generator) &&
            (noiseSet.size === 0 || noiseSet.has(p.noise)) &&
            !isSuccessRun(p)
        );
    }

    function updateFailedRunsButton(generator, noises) {
        const btn = document.getElementById('scan-view-failed-runs-btn');
        if (!btn) return;
        const failed = collectFailedRuns(generator, noises);
        btn.style.display = failed.length > 0 ? '' : 'none';
        btn.textContent = failed.length > 0 ? `Failed Runs (${failed.length})` : 'Failed Runs';
    }

    // Shared table builder for the by-noise and by-span breakdown matrices.
    // rows: [{label, ...reason_counts}], reasons: string[]
    function _frBreakdownTable(rows, reasons) {
        const REASON_COLORS = {
            max_steps: '#b45309', theory_budget: '#1d4ed8',
            infeasible_crlb: '#dc2626', timeout: '#7c3aed',
        };
        const table = document.createElement('table');
        table.style.cssText = 'border-collapse:collapse;font-size:0.85em;margin-bottom:1.2em;';
        const thead = table.createTHead();
        const hrow = thead.insertRow();
        for (const h of ['', ...reasons.map(r => FAILURE_LABELS[r] || r), 'Total']) {
            const th = document.createElement('th');
            th.textContent = h;
            th.style.cssText = 'text-align:right;padding:5px 10px;border-bottom:2px solid #e2e8f0;white-space:nowrap;color:#475569;font-weight:600;';
            if (h === '') th.style.textAlign = 'left';
            hrow.appendChild(th);
        }
        const tbody = table.createTBody();
        for (const row of rows) {
            const tr = tbody.insertRow();
            tr.style.borderBottom = '1px solid #f1f5f9';
            const labelTd = tr.insertCell();
            labelTd.textContent = row.label;
            labelTd.style.cssText = 'padding:4px 10px;white-space:nowrap;color:#334155;font-weight:500;';
            let rowTotal = 0;
            for (const r of reasons) {
                const td = tr.insertCell();
                const n = row[r] || 0;
                rowTotal += n;
                td.textContent = n > 0 ? String(n) : '—';
                td.style.cssText = 'padding:4px 10px;text-align:right;';
                if (n > 0) td.style.color = REASON_COLORS[r] || '#374151';
            }
            const totalTd = tr.insertCell();
            totalTd.textContent = String(rowTotal);
            totalTd.style.cssText = 'padding:4px 10px;text-align:right;font-weight:600;color:#374151;';
        }
        return table;
    }

    function _frSectionHeader(text) {
        const h = document.createElement('h3');
        h.textContent = text;
        h.style.cssText = 'margin:1.2em 0 0.4em;color:#475569;font-size:0.92em;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;';
        return h;
    }

    function renderFailedRunsTab(generator, noises) {
        const summary = document.getElementById('failed-runs-summary');
        const tableContainer = document.getElementById('failed-runs-table-container');
        if (!summary || !tableContainer) return;

        const failed = collectFailedRuns(generator, noises);

        if (!failed.length) {
            summary.textContent = 'No failed runs for the current selection.';
            summary.style.background = '#f0fdf4';
            summary.style.borderColor = '#86efac';
            summary.style.color = '#166534';
            tableContainer.innerHTML = '';
            return;
        }

        // Overall counts by reason
        const counts = {};
        for (const p of failed) {
            const r = p.failure_reason || 'unknown';
            counts[r] = (counts[r] || 0) + 1;
        }
        const total = failed.length;
        const reasons = Object.keys(counts).sort();
        const countParts = reasons.map(r => `${counts[r]} ${FAILURE_LABELS[r] || r}`).join(', ');
        summary.textContent = `${total} run${total !== 1 ? 's' : ''} failed: ${countParts}`;
        summary.style.background = '#fef3c7';
        summary.style.borderColor = '#fde68a';
        summary.style.color = '#92400e';

        const frag = document.createDocumentFragment();

        // ── By Noise ────────────────────────────────────────────────────────
        const noiseKeys = sortNoiseLabels([...new Set(failed.map(p => p.noise).filter(Boolean))]);
        if (noiseKeys.length > 1) {
            frag.appendChild(_frSectionHeader('By Noise'));
            const noiseRows = noiseKeys.map(nk => {
                const row = { label: nk };
                for (const p of failed.filter(fp => fp.noise === nk)) {
                    const r = p.failure_reason || 'unknown';
                    row[r] = (row[r] || 0) + 1;
                }
                return row;
            });
            frag.appendChild(_frBreakdownTable(noiseRows, reasons));
        }

        // ── By Signal Span ───────────────────────────────────────────────────
        const SPAN_BINS = [
            { label: '< 0.5%', lo: 0, hi: 0.005 },
            { label: '0.5 – 2%', lo: 0.005, hi: 0.02 },
            { label: '2 – 5%', lo: 0.02, hi: 0.05 },
            { label: '5 – 15%', lo: 0.05, hi: 0.15 },
            { label: '> 15%', lo: 0.15, hi: Infinity },
        ];
        const spanEntries = failed.map(p => ({ p, span: hlFSpan(p) })).filter(e => e.span != null);
        if (spanEntries.length > 0) {
            frag.appendChild(_frSectionHeader('By Signal Span'));
            const spanRows = SPAN_BINS.map(bin => {
                const inBin = spanEntries.filter(e => e.span >= bin.lo && e.span < bin.hi);
                if (!inBin.length) return null;
                const row = { label: bin.label };
                for (const { p } of inBin) {
                    const r = p.failure_reason || 'unknown';
                    row[r] = (row[r] || 0) + 1;
                }
                return row;
            }).filter(Boolean);
            if (spanRows.length) frag.appendChild(_frBreakdownTable(spanRows, reasons));
        }

        // ── All Failed Runs (flat table) ─────────────────────────────────────
        frag.appendChild(_frSectionHeader('All Failed Runs'));
        const table = document.createElement('table');
        table.style.cssText = 'width:100%;border-collapse:collapse;font-size:0.88em;';
        const thead = table.createTHead();
        const hrow = thead.insertRow();
        for (const h of ['Repeat', 'Strategy', 'Noise', 'Span', 'Reason', 'Steps Used', 'Max Steps', 'Theory Budget', 'Notes']) {
            const th = document.createElement('th');
            th.textContent = h;
            th.style.cssText = 'text-align:left;padding:6px 10px;border-bottom:2px solid #e2e8f0;white-space:nowrap;color:#475569;font-weight:600;';
            hrow.appendChild(th);
        }
        const tbody = table.createTBody();
        const sorted = [...failed].sort((a, b) =>
            (a.strategy || '').localeCompare(b.strategy || '') ||
            (a.noise || '').localeCompare(b.noise || '') ||
            (a.repeat || 0) - (b.repeat || 0)
        );
        for (const p of sorted) {
            const row = tbody.insertRow();
            row.style.borderBottom = '1px solid #f1f5f9';
            const reason = p.failure_reason || 'unknown';
            const reasonLabel = FAILURE_LABELS[reason] || reason;
            const fspan = hlFSpan(p);
            const spanStr = fspan != null ? (fspan * 100).toFixed(1) + '%' : '—';
            let notes = '';
            if (reason === 'theory_budget' && p.theory_step_budget != null) {
                notes = `Budget was ${p.theory_step_budget} steps`;
            } else if (reason === 'infeasible_crlb') {
                notes = 'Run never started';
            } else if (reason === 'max_steps') {
                notes = 'Hit measurement limit';
            } else if (reason === 'timeout') {
                notes = 'Repeat timed out';
            }
            const cells = [
                p.repeat ?? '—', p.strategy ?? '—', p.noise ?? '—', spanStr,
                reasonLabel, p.locator_steps ?? '—', p.max_steps ?? '—',
                p.theory_step_budget ?? '—', notes,
            ];
            for (let i = 0; i < cells.length; i++) {
                const td = row.insertCell();
                td.textContent = String(cells[i]);
                td.style.cssText = 'padding:5px 10px;';
                if (i === 4) {
                    if (reason === 'max_steps') td.style.color = '#b45309';
                    else if (reason === 'theory_budget') td.style.color = '#1d4ed8';
                    else if (reason === 'infeasible_crlb') td.style.color = '#dc2626';
                    else if (reason === 'timeout') td.style.color = '#7c3aed';
                }
            }
        }
        frag.appendChild(table);

        tableContainer.innerHTML = '';
        tableContainer.appendChild(frag);
    }

    function renderAccuracyNoise(gen) {
        const container = document.getElementById('acc-noise-content');
        if (!container) return;
        container.innerHTML = '';

        const genPlots = scanPlots.filter(p => toGenSet(gen).has(p.generator));
        const noises = sortNoiseLabels([...new Set(genPlots.map(p => p.noise))].filter(Boolean));
        const strategies = [...new Set(genPlots.map(p => p.strategy))].filter(Boolean).sort();

        if (!strategies.length || !noises.length) {
            container.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;">No data for this generator.</div>';
            return;
        }

        const cellStats = new Map();
        for (const noise of noises) {
            const cell = dashCell(gen, noise);
            for (const strat of strategies) {
                const runs = cell.get(strat) || [];
                if (!runs.length) continue;
                const covPairs = runs.filter(p => p.abs_err_x != null && p.uncert != null && p.uncert > 0);
                const k1 = covPairs.filter(p => p.abs_err_x <= p.uncert).length;
                const uncerts = runs.map(p => p.uncert).filter(v => v != null && v > 0);
                const errors = runs.map(p => p.abs_err_x).filter(v => v != null);
                cellStats.set(`${strat}|${noise}`, {
                    cal: covPairs.length ? k1 / covPairs.length : null,
                    calK: k1, calN: covPairs.length,
                    medUncert: uncerts.length ? hlMedian(uncerts) : null,
                    medErr: errors.length ? hlMedian(errors) : null,
                    n: runs.length,
                });
            }
        }

        const shortNoises = noises.map(n => { const m = n.match(/Gauss\(([\d.]+)\)/); return m ? m[1] : n; });
        const mkXAxis = () => ({ type: 'category', tickangle: -60, tickfont: { size: 9 }, categoryorder: 'array', categoryarray: noises, tickvals: noises, ticktext: shortNoises });

        // 1σ calibration vs noise
        {
            const plotDiv = dashPanelDiv(container,
                '1σ calibration vs noise',
                'Fraction of repeats where |true error| ≤ claimed 1σ uncertainty. Near 68% is well-calibrated.',
                Math.max(240, 140 + 20 * strategies.length));
            const traces = strategies.map(strat => {
                const color = hlStratColor(strategies, strat);
                const ys = [], texts = [];
                for (const noise of noises) {
                    const st = cellStats.get(`${strat}|${noise}`);
                    ys.push(st && st.cal != null ? st.cal : null);
                    texts.push(st && st.cal != null ? `${st.calK}/${st.calN} within 1σ` : '');
                }
                return {
                    x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                    name: _shortStratLabel(strat),
                    line: { color, width: 2 }, marker: { color, size: 6 }, text: texts,
                    hovertemplate: '%{y:.0%} coverage<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                };
            });
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, ...mkXAxis() };
            layout.yaxis = { ...layout.yaxis, range: [0, 1.05], tickformat: '.0%', title: { text: '|err| ≤ 1σ fraction', font: { size: 11 } } };
            layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 0.68, y1: 0.68, line: { color: '#94a3b8', width: 1.5, dash: 'dash' } }];
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }

        // Median absolute error vs noise
        {
            const plotDiv = dashPanelDiv(container,
                'Median absolute error vs noise',
                'Median absolute frequency error at end of run. Lower is more accurate.',
                Math.max(240, 140 + 20 * strategies.length));
            const traces = strategies.map(strat => {
                const color = hlStratColor(strategies, strat);
                const ys = [], texts = [];
                for (const noise of noises) {
                    const st = cellStats.get(`${strat}|${noise}`);
                    ys.push(st && st.medErr != null ? st.medErr : null);
                    texts.push(st ? `n=${st.n}` : '');
                }
                return {
                    x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                    name: _shortStratLabel(strat),
                    line: { color, width: 2 }, marker: { color, size: 6 }, text: texts,
                    hovertemplate: '%{y:.3g} Hz<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                };
            });
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, ...mkXAxis() };
            layout.yaxis = { ...layout.yaxis, title: { text: 'Median |error| (Hz)', font: { size: 11 } }, rangemode: 'tozero' };
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }

        // Final claimed σ vs noise
        {
            const plotDiv = dashPanelDiv(container,
                'Final claimed uncertainty vs noise',
                'Median claimed 1σ frequency uncertainty at end of run. Lower = tighter result delivered.',
                Math.max(240, 140 + 20 * strategies.length));
            const traces = strategies.map(strat => {
                const color = hlStratColor(strategies, strat);
                const ys = [], texts = [];
                for (const noise of noises) {
                    const st = cellStats.get(`${strat}|${noise}`);
                    ys.push(st && st.medUncert != null ? st.medUncert : null);
                    texts.push(st ? `n=${st.n}` : '');
                }
                return {
                    x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                    name: _shortStratLabel(strat),
                    line: { color, width: 2 }, marker: { color, size: 6 }, text: texts,
                    hovertemplate: '%{y:.3g} σ<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                };
            });
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, ...mkXAxis() };
            layout.yaxis = { ...layout.yaxis, title: { text: 'Median claimed σ', font: { size: 11 } }, rangemode: 'tozero' };
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }
    }

    function renderAccuracySpan() {
        const container = document.getElementById('acc-span-content');
        if (!container) return;
        container.innerHTML = '';
        const allStrats = [...new Set(scanPlots.map(p => p.strategy))].filter(Boolean).sort();
        const plotDiv = dashPanelDiv(container,
            'Calibration vs signal span — pooled',
            'Per-run 1σ calibration log-binned by fractional signal span. Near 68% is ideal (dashed line).',
            320, true);
        const traces = [];
        for (const strat of allStrats) {
            const xs = [], ys = [];
            for (const p of scanPlots) {
                if (p.strategy !== strat || p.generator === 'Dummy-Generator') continue;
                if (p.abs_err_x == null || p.uncert == null || p.uncert <= 0) continue;
                const fSpan = hlFSpan(p);
                if (fSpan == null) continue;
                xs.push(fSpan);
                ys.push(p.abs_err_x <= p.uncert ? 1 : 0);
            }
            if (!xs.length) continue;
            const color = hlStratColor(allStrats, strat);
            const { traces: t } = hlBinnedLineTraces(xs, ys, color, _shortStratLabel(strat), { hoverY: 'fraction within 1σ' });
            traces.push(...t);
        }
        if (!traces.length) {
            plotDiv.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No f_span data — runs need linewidth in true_params.</p>';
        } else {
            const layout = hlBaseLayout();
            layout.xaxis = { ...layout.xaxis, title: { text: 'Fractional signal span (f_span)', font: { size: 11 } }, type: 'log' };
            layout.yaxis = { ...layout.yaxis, range: [0, 1.05], tickformat: '.0%', title: { text: '|err| ≤ 1σ fraction', font: { size: 11 } } };
            layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 0.68, y1: 0.68, line: { color: '#94a3b8', width: 1.5, dash: 'dash' } }];
            Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
        }
    }

    // Panel 1: anytime error curves (median + IQR band), sweep emphasized.
    function renderHlErrorCurves(byStrategy, strategies, sweepName) {
        const div = document.getElementById('hl-error-curves');
        if (!div) return;
        let globalMax = 1;
        for (const s of strategies) {
            if (isSweepBaseline(s)) continue; // sweep's 2500-step total would swamp the adaptive scale
            for (const p of byStrategy.get(s)) {
                const m = hlRunSteps(p);
                if (m != null && m > globalMax) globalMax = m;
            }
        }
        const grid = hlStepGrid(globalMax);
        const traces = [];
        for (const strat of strategies) {
            const runs = byStrategy.get(strat).filter(p => p.series && p.series.e);
            if (!runs.length) continue;
            const color = hlStratColor(strategies, strat);
            const isSweep = strat === sweepName;
            const med = [], qLo = [], qHi = [], xs = [];
            for (const step of grid) {
                const vals = hlSorted(runs.map(p => hlSeriesValueAt(p.series, 'e', step)));
                if (!vals.length) continue;
                xs.push(step);
                med.push(hlQuantileSorted(vals, 0.5));
                qLo.push(hlQuantileSorted(vals, 0.25));
                qHi.push(hlQuantileSorted(vals, 0.75));
            }
            if (!xs.length) continue;
            traces.push({
                x: xs, y: qHi, mode: 'lines', line: { width: 0 },
                hoverinfo: 'skip', showlegend: false, legendgroup: strat,
            });
            traces.push({
                x: xs, y: qLo, mode: 'lines', line: { width: 0 }, fill: 'tonexty',
                fillcolor: hlHexToRgba(color, 0.13), hoverinfo: 'skip', showlegend: false, legendgroup: strat,
            });
            traces.push({
                x: xs, y: med, mode: 'lines', legendgroup: strat,
                name: `${_shortStratLabel(strat)}${isSweep ? ' (baseline)' : ''} (n=${runs.length})`,
                line: { color, width: isSweep ? 4 : 2, dash: isSweep ? 'solid' : undefined },
                hovertemplate: 'step %{x}<br>median err %{y:.4g} Hz<extra>' + _shortStratLabel(strat) + '</extra>',
            });
        }
        const layout = hlBaseLayout();
        layout.xaxis = { ...layout.xaxis, title: { text: 'Measurements', font: { size: 11 } }, type: 'log' };
        layout.yaxis = { ...layout.yaxis, title: { text: 'Median |frequency error| (Hz)', font: { size: 11 } }, type: 'log' };
        // Sweep-quality target: the practical accuracy delivered by the full sweep.
        const sweepRuns = sweepName ? byStrategy.get(sweepName) : [];
        const sweepFinalMed = sweepRuns && sweepRuns.length ? hlMedian(sweepRuns.map(p => p.abs_err_x)) : null;
        if (sweepFinalMed != null && sweepFinalMed > 0) {
            // On log axes Plotly shapes take raw data values, annotations log10
            layout.shapes = [{
                type: 'line', xref: 'paper', x0: 0, x1: 1, yref: 'y',
                y0: sweepFinalMed, y1: sweepFinalMed,
                line: { color: '#64748b', width: 1.5, dash: 'dash' },
            }];
            layout.annotations = [{
                xref: 'paper', x: 0.99, yref: 'y', y: Math.log10(sweepFinalMed),
                text: 'sweep quality', showarrow: false, font: { size: 9, color: '#64748b' },
                yanchor: 'bottom', xanchor: 'right',
            }];
        }
        Plotly.react(div, traces, layout, { displayModeBar: false, responsive: true });
    }

    // Panel 2: convergence survival curves at the (scaled) shared threshold.
    function renderHlSurvival(byStrategy, strategies, sweepName) {
        const div = document.getElementById('hl-survival');
        if (!div) return;
        // Sweep excluded: its convergence step reflects dip position in the
        // fixed scan order, not method efficiency.
        const adaptive = strategies.filter(s => s !== sweepName);
        let maxX = 1;
        const traces = [];
        const censorNotes = [];
        for (const strat of adaptive) {
            const runs = byStrategy.get(strat);
            const n = runs.length;
            if (!n) continue;
            const steps = hlSorted(runs.map(p => hlConvStep(p, hlTauMult)));
            const runMax = Math.max(...runs.map(p => hlRunSteps(p) || 1), 1);
            if (runMax > maxX) maxX = runMax;
            const xs = [0], ys = [0];
            steps.forEach((s, i) => { xs.push(s); ys.push((i + 1) / n); });
            xs.push(runMax); ys.push(steps.length / n);
            traces.push({
                x: xs, y: ys, mode: 'lines', line: { shape: 'hv', color: hlStratColor(strategies, strat), width: 2 },
                name: `${_shortStratLabel(strat)} (n=${n})`,
                hovertemplate: 'step %{x}<br>%{y:.0%} of repeats converged<extra>' + _shortStratLabel(strat) + '</extra>',
            });
            // Budget-censoring diagnostic: among non-converged runs, how many
            // were still improving at the budget? High → raise max steps;
            // zero → the threshold is unreachable at this noise level.
            const nonConv = runs.filter(p => hlConvStep(p, hlTauMult) == null);
            if (nonConv.length) {
                const improving = nonConv.filter(p => hlStillImproving(p) === true).length;
                censorNotes.push(`${_shortStratLabel(strat)}: ${improving}/${nonConv.length} non-converged still improving at budget${improving ? ' → budget-censored' : ' → stalled'}`);
            }
        }
        const layout = hlBaseLayout();
        layout.xaxis = { ...layout.xaxis, title: { text: 'Measurements', font: { size: 11 } } };
        layout.yaxis = { ...layout.yaxis, title: { text: 'Fraction of repeats converged', font: { size: 11 } }, range: [0, 1.04], tickformat: '.0%' };
        if (censorNotes.length) {
            layout.margin = { ...layout.margin, b: 55 + 14 * censorNotes.length };
            layout.annotations = censorNotes.map((note, i) => ({
                xref: 'paper', x: 0, yref: 'paper', y: -0.18 - 0.07 * i,
                xanchor: 'left', yanchor: 'top', showarrow: false,
                font: { size: 9.5, color: '#64748b' }, text: note,
            }));
        }
        if (!traces.length) {
            div.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No adaptive locators in this selection.</p>';
            return;
        }
        Plotly.react(div, traces, layout, { displayModeBar: false, responsive: true });
    }

    // Panel 3: coverage of the claimed final uncertainty vs Gaussian nominals.
    function renderHlCoverage(byStrategy, strategies) {
        const div = document.getElementById('hl-coverage');
        if (!div) return;
        const labels = [], c1 = [], c1err = [], c2 = [], c2err = [], c3 = [], c3err = [], colors1 = [], colors2 = [], colors3 = [], hover1 = [], hover2 = [], hover3 = [];
        for (const strat of strategies) {
            const pairs = byStrategy.get(strat).filter(p => p.abs_err_x != null && p.uncert != null && p.uncert > 0);
            const n = pairs.length;
            if (!n) continue;
            const k1 = pairs.filter(p => p.abs_err_x <= p.uncert).length;
            const k2 = pairs.filter(p => p.abs_err_x <= 2 * p.uncert).length;
            const k3 = pairs.filter(p => p.abs_err_x <= 3 * p.uncert).length;
            const w1 = hlWilson(k1, n), w2 = hlWilson(k2, n), w3 = hlWilson(k3, n);
            labels.push(_shortStratLabel(strat));
            c1.push(w1.p); c2.push(w2.p); c3.push(w3.p);
            c1err.push({ up: w1.hi - w1.p, down: w1.p - w1.lo });
            c2err.push({ up: w2.hi - w2.p, down: w2.p - w2.lo });
            c3err.push({ up: w3.hi - w3.p, down: w3.p - w3.lo });
            // Red only when the whole Wilson interval sits below nominal.
            colors1.push(w1.hi < HL_NOMINAL_1S ? '#dc2626' : '#60a5fa');
            colors2.push(w2.hi < HL_NOMINAL_2S ? '#dc2626' : '#1d4ed8');
            colors3.push(w3.hi < HL_NOMINAL_3S ? '#dc2626' : '#1e3a8a');
            hover1.push(`${k1}/${n} repeats with |err| ≤ 1σ`);
            hover2.push(`${k2}/${n} repeats with |err| ≤ 2σ`);
            hover3.push(`${k3}/${n} repeats with |err| ≤ 3σ`);
        }
        if (!labels.length) {
            div.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No (error, uncertainty) pairs available.</p>';
            return;
        }
        const traces = [
            {
                x: labels, y: c1, type: 'bar', name: '|err| ≤ 1σ',
                marker: { color: colors1 }, text: hover1, textposition: 'none',
                hovertemplate: '%{y:.0%}<br>%{text}<extra></extra>',
                error_y: { type: 'data', array: c1err.map(e => e.up), arrayminus: c1err.map(e => e.down), color: '#475569', thickness: 1 },
            },
            {
                x: labels, y: c2, type: 'bar', name: '|err| ≤ 2σ',
                marker: { color: colors2 }, text: hover2, textposition: 'none',
                hovertemplate: '%{y:.0%}<br>%{text}<extra></extra>',
                error_y: { type: 'data', array: c2err.map(e => e.up), arrayminus: c2err.map(e => e.down), color: '#475569', thickness: 1 },
            },
            {
                x: labels, y: c3, type: 'bar', name: '|err| ≤ 3σ',
                marker: { color: colors3 }, text: hover3, textposition: 'none',
                hovertemplate: '%{y:.0%}<br>%{text}<extra></extra>',
                error_y: { type: 'data', array: c3err.map(e => e.up), arrayminus: c3err.map(e => e.down), color: '#475569', thickness: 1 },
            },
        ];
        const layout = hlBaseLayout();
        layout.barmode = 'group';
        layout.yaxis = { ...layout.yaxis, title: { text: 'Coverage (fraction of repeats)', font: { size: 11 } }, range: [0, 1.06], tickformat: '.0%' };
        layout.shapes = [
            { type: 'line', xref: 'paper', x0: 0, x1: 1, yref: 'y', y0: HL_NOMINAL_1S, y1: HL_NOMINAL_1S, line: { color: '#60a5fa', width: 1, dash: 'dash' } },
            { type: 'line', xref: 'paper', x0: 0, x1: 1, yref: 'y', y0: HL_NOMINAL_2S, y1: HL_NOMINAL_2S, line: { color: '#1d4ed8', width: 1, dash: 'dash' } },
            { type: 'line', xref: 'paper', x0: 0, x1: 1, yref: 'y', y0: HL_NOMINAL_3S, y1: HL_NOMINAL_3S, line: { color: '#1e3a8a', width: 1, dash: 'dash' } },
        ];
        layout.annotations = [
            { xref: 'paper', x: 0.005, yref: 'y', y: HL_NOMINAL_1S, text: '68% nominal', showarrow: false, font: { size: 9, color: '#60a5fa' }, yanchor: 'bottom', xanchor: 'left' },
            { xref: 'paper', x: 0.005, yref: 'y', y: HL_NOMINAL_2S, text: '95% nominal', showarrow: false, font: { size: 9, color: '#1d4ed8' }, yanchor: 'bottom', xanchor: 'left' },
            { xref: 'paper', x: 0.005, yref: 'y', y: HL_NOMINAL_3S, text: '99.7% nominal', showarrow: false, font: { size: 9, color: '#1e3a8a' }, yanchor: 'bottom', xanchor: 'left' },
        ];
        Plotly.react(div, traces, layout, { displayModeBar: false, responsive: true });
    }

    // Panel 4: paired matched-promise savings vs f_span + search/refine split.
    function renderHlSpan(byStrategy, strategies, sweepName) {
        const div = document.getElementById('hl-span');
        const decompDiv = document.getElementById('hl-firstsignal');
        if (!div) return;
        // SimpleSweep is always the reference; SBED/Sobol are plotted as savings vs it.
        const baseline = sweepName;
        const adaptive = strategies.filter(s => s !== sweepName);

        const traces = [];
        const annotations = [];
        if (baseline && byStrategy.has(baseline)) {
            const baseByRepeat = new Map();
            for (const p of byStrategy.get(baseline)) {
                const step = hlConvStep(p, hlTauMult);
                if (p.repeat != null && step != null) baseByRepeat.set(p.repeat, { step, fSpan: hlFSpan(p) });
            }
            let annotY = 1.0;
            for (const strat of adaptive) {
                if (strat === baseline) continue;
                const xs = [], ys = [];
                for (const p of byStrategy.get(strat)) {
                    const base = baseByRepeat.get(p.repeat);
                    const step = hlConvStep(p, hlTauMult);
                    if (!base || step == null || base.fSpan == null) continue;
                    xs.push(base.fSpan);
                    ys.push(base.step - step);
                }
                if (!xs.length) continue;
                const color = hlStratColor(strategies, strat);
                traces.push({
                    x: xs, y: ys, mode: 'markers', type: 'scatter',
                    name: `${_shortStratLabel(strat)} (n=${xs.length})`,
                    marker: { color: hlHexToRgba(color, 0.75), size: 8, line: { color, width: 1 } },
                    hovertemplate: 'f_span %{x:.3e}<br>steps saved %{y}<extra>' + _shortStratLabel(strat) + '</extra>',
                });
                const medD = hlMedian(ys);
                const ci = hlBootstrapMedianCI(ys);
                const won = ys.filter(v => v > 0).length;
                annotations.push({
                    xref: 'paper', x: 0.01, yref: 'paper', y: annotY, xanchor: 'left', yanchor: 'top', showarrow: false,
                    font: { size: 10, color },
                    text: `${_shortStratLabel(strat)}: median Δ ${medD != null ? medD.toFixed(0) : '?'}${ci ? ` [${ci[0].toFixed(0)}, ${ci[1].toFixed(0)}]` : ''} steps · won ${won}/${ys.length}`,
                });
                annotY -= 0.07;
            }
        }
        const layout = hlBaseLayout();
        layout.xaxis = { ...layout.xaxis, title: { text: 'Fractional signal span (f_span)', font: { size: 11 } }, type: 'log' };
        layout.yaxis = { ...layout.yaxis, title: { text: `Steps saved vs ${baseline ? _shortStratLabel(baseline) : 'baseline'} (paired)`, font: { size: 11 } }, zeroline: true, zerolinecolor: '#cbd5e1' };
        layout.annotations = annotations;
        if (!traces.length) {
            div.style.height = 'auto';
            div.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">Needs a SimpleSweep baseline and at least one adaptive locator sharing repeats that converged at the same threshold.</p>';
        } else {
            div.style.height = '300px';
            Plotly.react(div, traces, layout, { displayModeBar: false, responsive: true });
        }

        // Search vs refine + uncertainty-at-convergence, both vs f_span, faceted
        // into small multiples by noise level. A raw per-repeat scatter is an
        // unreadable cloud, so each facet collapses every phase to a log-binned
        // median line with an IQR band — the trend (rising search ∝ 1/f_span, flat
        // refine; uncertainty floor vs span) is the whole point, and only the
        // binned per-noise summary makes it legible.
        const uncertDiv = document.getElementById('hl-uncert-span');

        // Noise levels present across the adaptive runs, sorted numerically.
        const noiseSet = new Set();
        for (const strat of adaptive)
            for (const p of (byStrategy.get(strat) || []))
                if (p.noise != null) noiseSet.add(p.noise);
        const noiseLevels = [...noiseSet].sort(
            (a, b) => (parseFloat(a) - parseFloat(b)) || String(a).localeCompare(String(b)));

        // Render one metric as a row of per-noise facets into `container`.
        const renderFacets = (container, buildTraces, yTitle) => {
            if (!container) return;
            container.innerHTML = '';
            container.style.display = 'block';
            if (!noiseLevels.length) {
                container.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">Needs per-step series data (re-run to generate).</p>';
                return;
            }
            // Build legend items from a representative trace set (first noise with data).
            let legendTraces = null;
            for (const noise of noiseLevels) {
                const rbs = new Map();
                for (const strat of adaptive)
                    rbs.set(strat, (byStrategy.get(strat) || []).filter(p => p.noise === noise));
                const t = buildTraces(rbs, strategies, adaptive, true);
                if (t.length) { legendTraces = t; break; }
            }
            if (legendTraces) {
                const legendEl = document.createElement('div');
                legendEl.style.cssText = 'display:flex; flex-wrap:wrap; gap:16px; margin:0 0 10px 0; padding:6px 10px; border-bottom:1px solid #e2e8f0; font-size:10px; color:#334155; align-items:center;';
                for (const tr of legendTraces) {
                    if (!tr.name || tr.showlegend === false) continue;
                    const item = document.createElement('span');
                    item.style.cssText = 'display:flex; align-items:center; gap:5px; white-space:nowrap;';
                    const swatch = document.createElement('span');
                    const c = (tr.line && tr.line.color) ? tr.line.color : (tr.marker && tr.marker.color ? tr.marker.color : '#888');
                    const dash = tr.line && tr.line.dash ? tr.line.dash : null;
                    swatch.style.cssText = `display:inline-block; width:28px; height:2px; background:${c}; border-radius:1px;${dash ? 'border-top:2px dashed ' + c + '; background:transparent;' : ''}`;
                    item.appendChild(swatch);
                    item.appendChild(document.createTextNode(tr.name));
                    legendEl.appendChild(item);
                }
                container.appendChild(legendEl);
            }
            const grid = document.createElement('div');
            grid.style.cssText = 'display:flex; flex-wrap:wrap; gap:8px;';
            container.appendChild(grid);
            noiseLevels.forEach((noise) => {
                const rbs = new Map();
                for (const strat of adaptive)
                    rbs.set(strat, (byStrategy.get(strat) || []).filter(p => p.noise === noise));
                const traces = buildTraces(rbs, strategies, adaptive, false);
                const cell = document.createElement('div');
                cell.style.cssText = 'flex:1 1 280px; min-width:255px;';
                grid.appendChild(cell);
                if (!traces.length) {
                    cell.innerHTML = `<p style="color:#94a3b8;padding:1em;font-size:0.85em;">noise ${noise}: no converged runs</p>`;
                    return;
                }
                const titleEl = document.createElement('div');
                const shortLabel = noise.match(/Gauss\(([\d.]+)\)/) ? `σ=${noise.match(/Gauss\(([\d.]+)\)/)[1]}` : noise;
                titleEl.style.cssText = 'font-size:10px; color:#475569; text-align:center; padding:2px 0;';
                titleEl.textContent = shortLabel;
                cell.appendChild(titleEl);
                const plotEl = document.createElement('div');
                plotEl.style.height = '240px';
                cell.appendChild(plotEl);
                const lay = hlBaseLayout();
                lay.margin = { t: 4, b: 40, l: 52, r: 10 };
                lay.showlegend = false;
                lay.xaxis = { ...lay.xaxis, title: { text: 'f_span', font: { size: 10 } }, type: 'log', tickfont: { size: 9 } };
                lay.yaxis = { ...lay.yaxis, title: { text: yTitle, font: { size: 10 } }, type: 'log', tickfont: { size: 9 } };
                Plotly.react(plotEl, traces, lay, { displayModeBar: false, responsive: true });
            });
        };

        renderFacets(decompDiv, hlBuildDecompTraces, 'Steps (median, IQR)');
        renderFacets(uncertDiv, hlBuildUncertTraces, 'σ at conv. (median, IQR)');
    }

    // Headline: practical one-liner per adaptive locator, anchored to the sweep.
    function renderHlHeadline(byStrategy, strategies, sweepName) {
        const container = document.getElementById('hl-headline');
        if (!container) return;
        container.innerHTML = '';
        const card = (html, accent) => {
            const d = document.createElement('div');
            d.style.cssText = `flex:1 1 280px;background:#fff;border:1px solid #e2e8f0;border-left:4px solid ${accent};border-radius:8px;padding:0.7em 1em;font-size:0.88em;color:#334155;`;
            d.innerHTML = html;
            container.appendChild(d);
        };
        if (!sweepName) {
            card('No full-sweep baseline in this selection — run a SimpleSweep to anchor the practical comparison.', '#94a3b8');
            return;
        }
        const sweepRuns = byStrategy.get(sweepName);
        const sweepFinalMed = hlMedian(sweepRuns.map(p => p.abs_err_x));
        const sweepMeasMed = hlMedian(sweepRuns.map(p => hlRunSteps(p)));
        if (sweepFinalMed == null || sweepMeasMed == null) {
            card('Sweep baseline present but missing final error/measurement data.', '#94a3b8');
            return;
        }
        for (const strat of strategies) {
            if (strat === sweepName) continue;
            const runs = byStrategy.get(strat);
            const seriesRuns = runs.filter(p => p.series && p.series.e);
            const color = hlStratColor(strategies, strat);
            const crossStep = hlCrossStep(seriesRuns, sweepFinalMed);
            const covPairs = runs.filter(p => p.abs_err_x != null && p.uncert != null && p.uncert > 0);
            const w = covPairs.length ? hlWilson(covPairs.filter(p => p.abs_err_x <= p.uncert).length, covPairs.length) : null;
            const covText = w ? `1σ coverage: ${(w.p * 100).toFixed(0)}% [${(w.lo * 100).toFixed(0)}–${(w.hi * 100).toFixed(0)}%] (n=${covPairs.length})` : 'coverage unavailable';
            let main;
            if (!seriesRuns.length) {
                main = 'no per-step series — re-run to compute the sweep-quality crossing';
            } else if (crossStep == null) {
                main = `does not reach sweep-quality accuracy (median ${formatHz(sweepFinalMed)}) within its budget`;
            } else {
                const factor = sweepMeasMed / crossStep;
                main = `sweep-quality accuracy in <strong>~${crossStep}</strong> of the sweep's ${Math.round(sweepMeasMed)} measurements (<strong>${factor.toFixed(1)}× fewer</strong>)`;
            }
            card(`<strong style="color:${color};">${_shortStratLabel(strat)}</strong> — ${main} · ${covText}`, color);
        }
    }

    function formatHz(v) {
        if (v == null || !isFinite(v)) return '?';
        if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(1) + ' MHz';
        if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(1) + ' kHz';
        return v.toFixed(1) + ' Hz';
    }

    // ── Dashboard tab ─────────────────────────────────────────────────────────
    // Aggregates the per-cell stories across ALL generators and noise levels,
    // so nothing interesting stays hidden behind the Scan view dropdowns.

    function dashCell(generator, noise) {
        const byStrategy = new Map();
        for (const p of scanPlots) {
            if (p.generator !== generator || p.noise !== noise || !p.strategy) continue;
            if (!byStrategy.has(p.strategy)) byStrategy.set(p.strategy, []);
            byStrategy.get(p.strategy).push(p);
        }
        return byStrategy;
    }

    function dashPanelDiv(parent, title, tip, height, fullWidth = false) {
        const box = document.createElement('div');
        box.style.cssText = `flex:1 1 ${fullWidth ? '100%' : '31%'}; min-width:380px; background:#fff; border:1px solid #f1f5f9; border-radius:8px; padding:10px;`;
        const h = document.createElement('h4');
        h.style.cssText = 'margin:0 0 0.4em 10px; font-size:0.9em; color:#334155;';
        h.innerHTML = `${title} <span tabindex="0" class="help-icon-visible" title="${tip.replace(/"/g, '&quot;')}">?</span>`;
        box.appendChild(h);
        const plot = document.createElement('div');
        plot.style.cssText = `height:${height}px; width:100%;`;
        box.appendChild(plot);
        parent.appendChild(box);
        return plot;
    }

    const dashHeatLayout = (xLabels, yLabels) => ({
        template: 'plotly_white',
        margin: { t: 10, b: Math.max(70, 50 + Math.max(...(xLabels.map(l => (l || '').length)), 0) * 4), l: 110, r: 15 },
        xaxis: { type: 'category', tickangle: -35, tickfont: { size: 9.5 }, categoryorder: 'array', categoryarray: xLabels },
        yaxis: { type: 'category', tickfont: { size: 10 }, categoryorder: 'array', categoryarray: yLabels },
        plot_bgcolor: 'transparent',
        paper_bgcolor: 'transparent',
    });

    function renderDashboard() {
        const content = document.getElementById('dashboard-content');
        if (!content) return;
        content.innerHTML = '';

        const generators = [...new Set(scanPlots.map(p => p.generator))]
            .filter(g => g && g !== 'Dummy-Generator').sort();
        if (!generators.length) {
            content.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;">No scan data yet.</div>';
            return;
        }

        ensurePlotly().then(() => {
            renderPooledMeasurements(content, generators);
            renderPooledUncertainty(content, generators);
        });
    }

    // ── Pooled: Measurement Savings ─────────────────────────────────────────
    // Section 1 — per-generator line charts (steps vs noise, k× vs noise)
    //             + pooled binned line (steps vs f_span)
    function renderPooledMeasurements(content, generators) {
        const hdr = document.createElement('div');
        hdr.innerHTML = '<h2 style="margin-bottom:0.2em;">Measurement Savings <span tabindex="0" class="help-icon-visible" title="How many measurements each locator needs to converge, compared to the full sweep, as a function of noise level and signal span. τ toggle scales the convergence threshold.">?</span></h2>';
        content.appendChild(hdr);

        const allStrats = [...new Set(scanPlots.map(p => p.strategy))].filter(Boolean).sort();
        const sweepName = allStrats.filter(isSweepBaseline).find(s => /^SimpleSweep/.test(s))
            || allStrats.filter(isSweepBaseline)[0] || null;

        for (const gen of generators) {
            const genPlots = scanPlots.filter(p => p.generator === gen);
            const noises = sortNoiseLabels([...new Set(genPlots.map(p => p.noise))].filter(Boolean));
            const strategies = [...new Set(genPlots.map(p => p.strategy))].filter(Boolean).sort();
            const adaptive = strategies.filter(s => !isSweepBaseline(s));
            if (!strategies.length) continue;

            const genSection = document.createElement('div');
            genSection.style.cssText = 'margin-top:1.2em;';
            const gh = document.createElement('h3');
            gh.style.cssText = 'margin:0 0 0.6em;';
            gh.textContent = gen;
            genSection.appendChild(gh);
            const row = document.createElement('div');
            row.style.cssText = 'display:flex; flex-wrap:wrap; gap:1.2em;';
            genSection.appendChild(row);
            content.appendChild(genSection);

            // Per-(strategy, noise) median conv steps and k× factor
            const cellConv = new Map();
            for (const noise of noises) {
                const cell = dashCell(gen, noise);
                const sweepRuns = sweepName ? (cell.get(sweepName) || []) : [];
                const sweepMeasMed = sweepRuns.length ? hlMedian(sweepRuns.map(p => hlRunSteps(p)).filter(v => v != null)) : null;
                for (const strat of strategies) {
                    const runs = cell.get(strat) || [];
                    if (!runs.length) continue;
                    const isSweep = isSweepBaseline(strat);
                    const convSteps = isSweep
                        ? runs.map(p => hlRunSteps(p)).filter(v => v != null)
                        : runs.map(p => hlConvStep(p, hlTauMult)).filter(v => v != null);
                    const medConv = convSteps.length ? hlMedian(convSteps) : null;
                    const k = (!isSweep && medConv != null && sweepMeasMed != null) ? sweepMeasMed / medConv : null;
                    cellConv.set(`${strat}|${noise}`, {
                        medConv, sweepMeasMed, k, n: runs.length, convN: convSteps.length,
                    });
                }
            }

            // Panel 1a: steps to convergence vs noise
            {
                const plotDiv = dashPanelDiv(row,
                    'Steps to convergence vs noise',
                    'Median steps to convergence at the current τ threshold. Sweep (dashed) = total measurement count — it runs to completion, not to a convergence criterion. Lower is faster.',
                    Math.max(260, 160 + 20 * strategies.length));
                const traces = strategies.map(strat => {
                    const color = hlStratColor(strategies, strat);
                    const isSweep = isSweepBaseline(strat);
                    const ys = [], texts = [];
                    for (const noise of noises) {
                        const st = cellConv.get(`${strat}|${noise}`);
                        ys.push(st ? st.medConv : null);
                        texts.push(st ? `${st.convN}/${st.n} converged` : '');
                    }
                    return {
                        x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                        name: _shortStratLabel(strat),
                        line: { color, width: isSweep ? 2.5 : 2, dash: isSweep ? 'dash' : 'solid' },
                        marker: { color, size: 6 },
                        text: texts,
                        hovertemplate: '%{y:.0f} steps<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                    };
                });
                const layout = hlBaseLayout();
                layout.xaxis = { ...layout.xaxis, type: 'category', tickangle: -35, tickfont: { size: 9.5 }, categoryorder: 'array', categoryarray: noises };
                layout.yaxis = { ...layout.yaxis, title: { text: 'Median steps', font: { size: 11 } }, rangemode: 'tozero' };
                Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
            }

            // Panel 1b: k× savings vs noise (adaptive only)
            if (sweepName && adaptive.length) {
                const plotDiv = dashPanelDiv(row,
                    `k× savings vs noise — τ×${hlTauMult}`,
                    'Ratio of sweep total steps to adaptive convergence steps at the current τ. k=2 means the locator needed half as many measurements. Blank = did not converge. Reference line at k=1 (same as sweep).',
                    Math.max(260, 160 + 20 * adaptive.length));
                const traces = adaptive.map(strat => {
                    const color = hlStratColor(strategies, strat);
                    const ys = [], texts = [];
                    for (const noise of noises) {
                        const st = cellConv.get(`${strat}|${noise}`);
                        ys.push(st ? st.k : null);
                        texts.push(st && st.k != null
                            ? `${Math.round(st.medConv)} vs ${Math.round(st.sweepMeasMed)} sweep steps (n=${st.convN}/${st.n})`
                            : 'did not converge');
                    }
                    return {
                        x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                        name: _shortStratLabel(strat),
                        line: { color, width: 2 }, marker: { color, size: 6 },
                        text: texts,
                        hovertemplate: '%{y:.1f}× faster<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                    };
                });
                const layout = hlBaseLayout();
                layout.xaxis = { ...layout.xaxis, type: 'category', tickangle: -35, tickfont: { size: 9.5 }, categoryorder: 'array', categoryarray: noises };
                layout.yaxis = { ...layout.yaxis, title: { text: 'Median sweep steps / conv steps', font: { size: 11 } }, rangemode: 'tozero' };
                layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 1, y1: 1, line: { color: '#94a3b8', width: 1.5, dash: 'dash' } }];
                Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
            }
        }

        // Panel 1c: steps vs f_span, pooled across all generators + noises
        {
            const poolRow = document.createElement('div');
            poolRow.style.cssText = 'margin-top:1.2em;';
            content.appendChild(poolRow);
            const plotDiv = dashPanelDiv(poolRow,
                `Steps to convergence vs signal span — pooled, τ×${hlTauMult}`,
                'Each run plotted by its fractional signal span (linewidth / full spectrum width). Log-binned median + IQR band. Sweep shown as total measurement count (dashed). Slim signals (small f_span) may need more measurements to locate.',
                340, true);
            const traces = [];
            for (const strat of allStrats) {
                const isSweep = isSweepBaseline(strat);
                const xs = [], ys = [];
                for (const p of scanPlots) {
                    if (p.strategy !== strat || p.generator === 'Dummy-Generator') continue;
                    const fSpan = hlFSpan(p);
                    if (fSpan == null) continue;
                    const step = isSweep ? hlRunSteps(p) : hlConvStep(p, hlTauMult);
                    if (step == null) continue;
                    xs.push(fSpan); ys.push(step);
                }
                if (!xs.length) continue;
                const color = hlStratColor(allStrats, strat);
                const { traces: t } = hlBinnedLineTraces(xs, ys, color, _shortStratLabel(strat), {
                    dash: isSweep ? 'dash' : null, hoverY: 'median steps',
                });
                traces.push(...t);
            }
            if (!traces.length) {
                plotDiv.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No f_span data — runs need linewidth in true_params.</p>';
            } else {
                const layout = hlBaseLayout();
                layout.xaxis = { ...layout.xaxis, title: { text: 'Fractional signal span (f_span)', font: { size: 11 } }, type: 'log' };
                layout.yaxis = { ...layout.yaxis, title: { text: 'Median steps to convergence', font: { size: 11 } } };
                Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
            }
        }
    }

    // ── Pooled: Uncertainty Quality ──────────────────────────────────────────
    // Section 2 — per-generator line charts (calibration vs noise, final σ vs noise)
    //             + pooled binned line (calibration vs f_span)
    function renderPooledUncertainty(content, generators) {
        const sep = document.createElement('div');
        sep.style.cssText = 'border-top:2px solid #e2e8f0; margin:2em 0 0.5em;';
        content.appendChild(sep);
        const hdr = document.createElement('div');
        hdr.innerHTML = '<h2 style="margin-bottom:0.2em;">Uncertainty Quality <span tabindex="0" class="help-icon-visible" title="Whether the locator\'s claimed uncertainty matches the true error (calibration) and how tight the final answer is, as a function of noise level and signal span.">?</span></h2>';
        content.appendChild(hdr);

        const allStrats = [...new Set(scanPlots.map(p => p.strategy))].filter(Boolean).sort();

        for (const gen of generators) {
            const genPlots = scanPlots.filter(p => p.generator === gen);
            const noises = sortNoiseLabels([...new Set(genPlots.map(p => p.noise))].filter(Boolean));
            const strategies = [...new Set(genPlots.map(p => p.strategy))].filter(Boolean).sort();
            if (!strategies.length) continue;

            const genSection = document.createElement('div');
            genSection.style.cssText = 'margin-top:1.2em;';
            const gh = document.createElement('h3');
            gh.style.cssText = 'margin:0 0 0.6em;';
            gh.textContent = gen;
            genSection.appendChild(gh);
            const row = document.createElement('div');
            row.style.cssText = 'display:flex; flex-wrap:wrap; gap:1.2em;';
            genSection.appendChild(row);
            content.appendChild(genSection);

            // Per-(strategy, noise) calibration and final uncertainty stats
            const cellUncert = new Map();
            for (const noise of noises) {
                const cell = dashCell(gen, noise);
                for (const strat of strategies) {
                    const runs = cell.get(strat) || [];
                    if (!runs.length) continue;
                    const covPairs = runs.filter(p => p.abs_err_x != null && p.uncert != null && p.uncert > 0);
                    const k1 = covPairs.filter(p => p.abs_err_x <= p.uncert).length;
                    const uncerts = runs.map(p => p.uncert).filter(v => v != null && v > 0);
                    cellUncert.set(`${strat}|${noise}`, {
                        cal: covPairs.length ? k1 / covPairs.length : null,
                        calK: k1, calN: covPairs.length,
                        medUncert: uncerts.length ? hlMedian(uncerts) : null,
                        n: runs.length,
                    });
                }
            }

            // Panel 2a: 1σ calibration vs noise
            {
                const plotDiv = dashPanelDiv(row,
                    '1σ calibration vs noise',
                    'Fraction of repeats where |true error| ≤ claimed 1σ uncertainty. A well-calibrated locator should be near the 68% dashed line. Below = overconfident; above = conservative.',
                    Math.max(260, 160 + 20 * strategies.length));
                const traces = strategies.map(strat => {
                    const color = hlStratColor(strategies, strat);
                    const ys = [], texts = [];
                    for (const noise of noises) {
                        const st = cellUncert.get(`${strat}|${noise}`);
                        ys.push(st && st.cal != null ? st.cal : null);
                        texts.push(st && st.cal != null ? `${st.calK}/${st.calN} within 1σ` : '');
                    }
                    return {
                        x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                        name: _shortStratLabel(strat),
                        line: { color, width: 2 }, marker: { color, size: 6 },
                        text: texts,
                        hovertemplate: '%{y:.0%} coverage<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                    };
                });
                const layout = hlBaseLayout();
                layout.xaxis = { ...layout.xaxis, type: 'category', tickangle: -35, tickfont: { size: 9.5 }, categoryorder: 'array', categoryarray: noises };
                layout.yaxis = { ...layout.yaxis, range: [0, 1.05], tickformat: '.0%', title: { text: '|err| ≤ 1σ fraction', font: { size: 11 } } };
                layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 0.68, y1: 0.68, line: { color: '#94a3b8', width: 1.5, dash: 'dash' } }];
                Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
            }

            // Panel 2b: median final claimed uncertainty vs noise
            {
                const plotDiv = dashPanelDiv(row,
                    'Final claimed uncertainty vs noise',
                    'Median claimed 1σ frequency uncertainty at the end of the run. Lower = tighter result delivered. Compare locators to see who promises more precision, and whether louder noise forces a looser answer.',
                    Math.max(260, 160 + 20 * strategies.length));
                const traces = strategies.map(strat => {
                    const color = hlStratColor(strategies, strat);
                    const ys = [], texts = [];
                    for (const noise of noises) {
                        const st = cellUncert.get(`${strat}|${noise}`);
                        ys.push(st && st.medUncert != null ? st.medUncert : null);
                        texts.push(st ? `n=${st.n}` : '');
                    }
                    return {
                        x: noises, y: ys, mode: 'lines+markers', type: 'scatter',
                        name: _shortStratLabel(strat),
                        line: { color, width: 2 }, marker: { color, size: 6 },
                        text: texts,
                        hovertemplate: '%{y:.3g} σ<br>%{text}<extra>' + _shortStratLabel(strat) + '</extra>',
                    };
                });
                const layout = hlBaseLayout();
                layout.xaxis = { ...layout.xaxis, type: 'category', tickangle: -35, tickfont: { size: 9.5 }, categoryorder: 'array', categoryarray: noises };
                layout.yaxis = { ...layout.yaxis, title: { text: 'Median claimed σ', font: { size: 11 } }, rangemode: 'tozero' };
                Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
            }
        }

        // Panel 2c: 1σ calibration vs f_span, pooled
        {
            const poolRow = document.createElement('div');
            poolRow.style.cssText = 'margin-top:1.2em;';
            content.appendChild(poolRow);
            const plotDiv = dashPanelDiv(poolRow,
                'Calibration vs signal span — pooled',
                'Per-run 1σ calibration (1 = error within 1σ, 0 = outside), log-binned by fractional signal span. Near 68% is ideal (dashed line). Drops for slim signals indicate calibration degrades for narrow features.',
                320, true);
            const traces = [];
            for (const strat of allStrats) {
                const xs = [], ys = [];
                for (const p of scanPlots) {
                    if (p.strategy !== strat || p.generator === 'Dummy-Generator') continue;
                    if (p.abs_err_x == null || p.uncert == null || p.uncert <= 0) continue;
                    const fSpan = hlFSpan(p);
                    if (fSpan == null) continue;
                    xs.push(fSpan);
                    ys.push(p.abs_err_x <= p.uncert ? 1 : 0);
                }
                if (!xs.length) continue;
                const color = hlStratColor(allStrats, strat);
                const { traces: t } = hlBinnedLineTraces(xs, ys, color, _shortStratLabel(strat), {
                    hoverY: 'fraction within 1σ',
                });
                traces.push(...t);
            }
            if (!traces.length) {
                plotDiv.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No f_span data — runs need linewidth in true_params.</p>';
            } else {
                const layout = hlBaseLayout();
                layout.xaxis = { ...layout.xaxis, title: { text: 'Fractional signal span (f_span)', font: { size: 11 } }, type: 'log' };
                layout.yaxis = { ...layout.yaxis, range: [0, 1.05], tickformat: '.0%', title: { text: '|err| ≤ 1σ fraction', font: { size: 11 } } };
                layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 0.68, y1: 0.68, line: { color: '#94a3b8', width: 1.5, dash: 'dash' } }];
                Plotly.react(plotDiv, traces, layout, { displayModeBar: false, responsive: true });
            }
        }
    }


    // Stopping criteria selector
    const stoppingCriteriaGroup = document.getElementById('scan-stopping-criteria');
    if (stoppingCriteriaGroup) {
        stoppingCriteriaGroup.addEventListener('click', (e) => {
            const btn = e.target.closest('button[data-value]');
            if (!btn || btn.disabled) return;
            setStoppingCriteria(btn.dataset.value);
            if (currentPlot) findAndDisplayPlot();
        });
    }

    // ── Noise Sweep summary plots (generator-level) ─────────────────────────

    function initAndRenderNoiseSweepPlots(generator) {
        const genPlots = scanPlots.filter(p => p.generator === generator);
        const strategies = [...new Set(genPlots.map(p => p.strategy))].filter(Boolean).sort();

        // 1. Initialize selections if empty or invalid
        if (!window._selectedNoiseLocators) {
            window._selectedNoiseLocators = new Set(strategies);
        } else {
            // Remove strategies that are no longer available for this generator
            for (const strat of window._selectedNoiseLocators) {
                if (!strategies.includes(strat)) {
                    window._selectedNoiseLocators.delete(strat);
                }
            }
            if (window._selectedNoiseLocators.size === 0 && strategies.length > 0) {
                window._selectedNoiseLocators = new Set(strategies);
            }
        }

        const convergences = ['full', 'freq_converged', 'all_converged'];
        const convergenceLabels = {
            'full': 'Full',
            'freq_converged': 'Freq. converged',
            'all_converged': 'Converged'
        };

        if (!window._selectedNoiseConvergences) {
            window._selectedNoiseConvergences = new Set(['freq_converged']);
        }

        // 2. Render Locator buttons
        const locContainer = document.getElementById('noise-locators-select');
        if (locContainer) {
            locContainer.innerHTML = '';
            strategies.forEach(strat => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.dataset.value = strat;
                btn.setAttribute('role', 'checkbox');
                const active = window._selectedNoiseLocators.has(strat);
                btn.classList.toggle('is-active', active);
                btn.setAttribute('aria-checked', String(active));
                btn.tabIndex = 0;
                btn.textContent = strat;
                btn.className = 'tab-button'; // styling
                btn.style.margin = '2px';
                btn.addEventListener('click', () => {
                    if (window._selectedNoiseLocators.has(strat)) {
                        if (window._selectedNoiseLocators.size > 1) { // keep at least one
                            window._selectedNoiseLocators.delete(strat);
                            btn.classList.remove('is-active');
                            btn.setAttribute('aria-checked', 'false');
                        }
                    } else {
                        window._selectedNoiseLocators.add(strat);
                        btn.classList.add('is-active');
                        btn.setAttribute('aria-checked', 'true');
                    }
                    updateBaselineOptionsAndRedraw(generator);
                });
                locContainer.appendChild(btn);
            });
        }

        // 3. Render Convergence buttons
        const convContainer = document.getElementById('noise-convergences-select');
        if (convContainer) {
            convContainer.innerHTML = '';
            convergences.forEach(conv => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.dataset.value = conv;
                btn.setAttribute('role', 'checkbox');
                const active = window._selectedNoiseConvergences.has(conv);
                btn.classList.toggle('is-active', active);
                btn.setAttribute('aria-checked', String(active));
                btn.tabIndex = 0;
                btn.textContent = convergenceLabels[conv];
                btn.className = 'tab-button'; // styling
                btn.style.margin = '2px';
                btn.addEventListener('click', () => {
                    if (window._selectedNoiseConvergences.has(conv)) {
                        if (window._selectedNoiseConvergences.size > 1) { // keep at least one
                            window._selectedNoiseConvergences.delete(conv);
                            btn.classList.remove('is-active');
                            btn.setAttribute('aria-checked', 'false');
                        }
                    } else {
                        window._selectedNoiseConvergences.add(conv);
                        btn.classList.add('is-active');
                        btn.setAttribute('aria-checked', 'true');
                    }
                    updateBaselineOptionsAndRedraw(generator);
                });
                convContainer.appendChild(btn);
            });
        }

        updateBaselineOptionsAndRedraw(generator);
    }

    function updateBaselineOptionsAndRedraw(generator) {
        const baselineSelect = document.getElementById('noise-baseline-select');
        if (!baselineSelect) return;

        // Build list of all available strategy-convergence pairs (independent of current selection)
        const genPlots = scanPlots.filter(p => p.generator === generator);
        const strategies = [...new Set(genPlots.map(p => p.strategy))].filter(Boolean).sort();
        const convergences = ['full', 'freq_converged', 'all_converged'];

        const pairs = [];
        strategies.forEach(strat => {
            convergences.forEach(conv => {
                // A sweep's "convergence step" reflects where the dip sits in
                // the fixed scan order, not efficiency — only its full run is
                // a meaningful entity.
                if (conv !== 'full' && isSweepBaseline(strat)) return;
                pairs.push({ strategy: strat, convergence: conv });
            });
        });

        // Save current baseline selection
        const prevBaseline = baselineSelect.value;

        // Populate baseline select dropdown
        baselineSelect.innerHTML = '';
        pairs.forEach(p => {
            const opt = document.createElement('option');
            opt.value = `${p.strategy}::${p.convergence}`;
            const convLabel = p.convergence === 'full' ? 'Full' : (p.convergence === 'freq_converged' ? 'Freq. converged' : 'Converged');
            opt.textContent = `${p.strategy} (${convLabel})`;
            baselineSelect.appendChild(opt);
        });

        // Restore baseline selection if still valid, otherwise choose a smart default
        let newBaseline = prevBaseline;
        const validValues = pairs.map(p => `${p.strategy}::${p.convergence}`);
        // The shared Compare control bar dictates the baseline strategy: if it
        // disagrees with the previous selection, adopt it (preserving the prior
        // convergence choice when that pair exists, else Full).
        if (sharedBaselineStrategy) {
            const prevConv = prevBaseline ? (prevBaseline.split('::')[1] || 'full') : 'full';
            const prevStrat = prevBaseline ? prevBaseline.split('::')[0] : null;
            if (prevStrat !== sharedBaselineStrategy) {
                newBaseline = validValues.find(v => v === `${sharedBaselineStrategy}::${prevConv}`)
                    || validValues.find(v => v === `${sharedBaselineStrategy}::full`)
                    || newBaseline;
            }
        }
        if (!validValues.includes(newBaseline)) {
            // Honor the shared baseline strategy (Full convergence) if available
            // for this generator; otherwise prefer SimpleSweep (Full), then
            // SimpleSweep (any), then SimpleSobol (Full), then any.
            const sharedFull = sharedBaselineStrategy
                ? validValues.find(v => v === `${sharedBaselineStrategy}::full`)
                : null;
            const sweepFull = validValues.find(v => v.startsWith('SimpleSweep::full') || v.startsWith('GenericSweep::full'));
            const sweepAny = validValues.find(v => v.includes('Sweep::'));
            const sobolFull = validValues.find(v => v.startsWith('SimpleSobol::full'));
            newBaseline = sharedFull || sweepFull || sweepAny || sobolFull || validValues[0] || '';
        }
        baselineSelect.value = newBaseline;
        // Adopt the chosen strategy as the shared baseline so other views agree.
        if (newBaseline) sharedBaselineStrategy = newBaseline.split('::')[0];

        // Setup event listener if not already done
        if (!baselineSelect._hasListener) {
            baselineSelect.addEventListener('change', () => {
                const val = baselineSelect.value;
                if (val) sharedBaselineStrategy = val.split('::')[0];
                redrawDynamicNoisePlots(controlValue(scanGenerator));
            });
            baselineSelect._hasListener = true;
        }

        redrawDynamicNoisePlots(generator);
    }

    async function redrawDynamicNoisePlots(generator) {
        await ensurePlotly();
        const genPlots = scanPlots.filter(p => p.generator === generator);
        const noises = [...new Set(genPlots.map(p => p.noise))].filter(Boolean);

        const uniqueNoises = noises.sort((a, b) => {
            const ga = a.match(/Gauss\(([\d.]+)\)/);
            const gb = b.match(/Gauss\(([\d.]+)\)/);
            if (ga && gb) return parseFloat(ga[1]) - parseFloat(gb[1]);
            if (ga) return -1; if (gb) return 1;
            return a.localeCompare(b);
        });

        const baselineVal = document.getElementById('noise-baseline-select').value;
        const [baselineStrat, baselineConv] = baselineVal ? baselineVal.split('::') : [null, null];

        const errorTraces = [];
        const measTraces = [];
        const savingsTraces = [];

        const measValueOf = (p, conv) => {
            if (conv === 'freq_converged') return p.freq_converged_step ?? p.steps_to_fb ?? p.measurements;
            if (conv === 'all_converged') return p.all_converged_step ?? p.final_steps ?? p.measurements;
            return p.measurements;
        };
        const finite = v => v !== null && v !== undefined && !isNaN(v);

        // 1. Precalculate baseline measurements per noise level for savings:
        //    per-repeat map (for paired differences) plus the median fallback.
        const baselineMeasByNoise = {};        // noise -> median
        const baselineMeasByNoiseRepeat = {};  // noise -> Map(repeat -> value)
        if (baselineStrat && baselineConv) {
            uniqueNoises.forEach(noise => {
                const repPlots = genPlots.filter(p => p.noise === noise && p.strategy === baselineStrat);
                const byRepeat = new Map();
                const vals = [];
                repPlots.forEach(p => {
                    const v = measValueOf(p, baselineConv);
                    if (finite(v)) {
                        vals.push(v);
                        if (p.repeat != null) byRepeat.set(p.repeat, v);
                    }
                });
                if (vals.length > 0) {
                    baselineMeasByNoise[noise] = hlMedian(vals);
                    baselineMeasByNoiseRepeat[noise] = byRepeat;
                }
            });
        }

        // 2. Build Selected Pairs (sweep entities only make sense at 'full')
        const selectedPairs = [];
        window._selectedNoiseLocators.forEach(strat => {
            window._selectedNoiseConvergences.forEach(conv => {
                if (conv !== 'full' && isSweepBaseline(strat)) return;
                selectedPairs.push({ strategy: strat, convergence: conv });
            });
        });

        // 3. Generate Traces
        const colors = [
            '#2563eb', // Blue
            '#f59e0b', // Orange
            '#10b981', // Green
            '#8b5cf6', // Purple
            '#ec4899', // Pink
            '#ef4444', // Red
            '#06b6d4', // Cyan
            '#14b8a6', // Teal
        ];

        selectedPairs.forEach((pair, idx) => {
            const color = colors[idx % colors.length];
            const convLabel = pair.convergence === 'full' ? 'Full' : (pair.convergence === 'freq_converged' ? 'Freq. converged' : 'Converged');
            const traceName = `${pair.strategy} (${convLabel})`;

            const xVals = [];
            const errY = [], errLo = [], errHi = [], errN = [];
            const measY = [], measLo = [], measHi = [], measN = [];
            const savY = [], savN = [];

            uniqueNoises.forEach(noise => {
                const repPlots = genPlots.filter(p => p.noise === noise && p.strategy === pair.strategy);
                if (repPlots.length > 0) {
                    xVals.push(noise);

                    // Error: median + IQR across repeats (means are dominated
                    // by the occasional catastrophic miss).
                    const errVals = hlSorted(repPlots.map(p => {
                        if (pair.convergence === 'freq_converged') {
                            return p.err_fb_at_milestone ?? p.final_err_fb ?? p.abs_err_x;
                        }
                        return p.abs_err_x;
                    }));
                    errY.push(errVals.length ? hlQuantileSorted(errVals, 0.5) : null);
                    errLo.push(errVals.length ? hlQuantileSorted(errVals, 0.25) : null);
                    errHi.push(errVals.length ? hlQuantileSorted(errVals, 0.75) : null);
                    errN.push(errVals.length);

                    // Measurements: median + IQR
                    const measByRepeat = new Map();
                    const measVals = [];
                    repPlots.forEach(p => {
                        const v = measValueOf(p, pair.convergence);
                        if (finite(v)) {
                            measVals.push(v);
                            if (p.repeat != null) measByRepeat.set(p.repeat, v);
                        }
                    });
                    const measSorted = hlSorted(measVals);
                    const medMeas = measSorted.length ? hlQuantileSorted(measSorted, 0.5) : null;
                    measY.push(medMeas);
                    measLo.push(measSorted.length ? hlQuantileSorted(measSorted, 0.25) : null);
                    measHi.push(measSorted.length ? hlQuantileSorted(measSorted, 0.75) : null);
                    measN.push(measSorted.length);

                    // Savings: median of per-repeat paired differences when the
                    // repeats overlap (same ground truth), unpaired medians as
                    // fallback.
                    const baseByRepeat = baselineMeasByNoiseRepeat[noise];
                    let sav = null, savCount = 0;
                    if (baseByRepeat) {
                        const diffs = [];
                        measByRepeat.forEach((v, rep) => {
                            const b = baseByRepeat.get(rep);
                            if (b !== undefined) diffs.push(b - v);
                        });
                        if (diffs.length) {
                            sav = hlMedian(diffs);
                            savCount = diffs.length;
                        }
                    }
                    if (sav === null && baselineMeasByNoise[noise] !== undefined && medMeas !== null) {
                        sav = baselineMeasByNoise[noise] - medMeas;
                    }
                    savY.push(sav);
                    savN.push(savCount);
                }
            });

            if (xVals.length > 0) {
                const bandPair = (ys, los, his, nArr, unitFmt) => ([
                    { x: xVals, y: his, mode: 'lines', line: { width: 0 }, hoverinfo: 'skip', showlegend: false, legendgroup: traceName },
                    { x: xVals, y: los, mode: 'lines', line: { width: 0 }, fill: 'tonexty', fillcolor: color + '22', hoverinfo: 'skip', showlegend: false, legendgroup: traceName },
                    {
                        x: xVals, y: ys, mode: 'lines+markers', name: traceName, legendgroup: traceName,
                        line: { color: color, width: 2 }, marker: { size: 6 },
                        text: nArr.map(n => `n=${n}`),
                        hovertemplate: `%{y:${unitFmt}}<br>median (IQR band), %{text}<extra>${traceName}</extra>`,
                    },
                ]);
                errorTraces.push(...bandPair(errY, errLo, errHi, errN, '.4g'));
                measTraces.push(...bandPair(measY, measLo, measHi, measN, '.1f'));

                // Do not add savings trace for the baseline itself (always 0)
                if (`${pair.strategy}::${pair.convergence}` !== baselineVal) {
                    savingsTraces.push({
                        x: xVals,
                        y: savY,
                        mode: 'lines+markers',
                        name: traceName,
                        line: { color: color, width: 2 },
                        marker: { size: 6 },
                        text: savN.map(n => n > 0 ? `paired, n=${n}` : 'unpaired fallback'),
                        hovertemplate: '%{y:.1f} steps saved<br>%{text}<extra>' + traceName + '</extra>',
                    });
                }
            }
        });

        // 4. Common Layout
        const commonLayout = {
            template: 'plotly_white',
            margin: { t: 40, b: 60, l: 60, r: 20 },
            hovermode: 'closest',
            legend: {
                orientation: 'h',
                yanchor: 'bottom',
                y: 1.02,
                xanchor: 'right',
                x: 1
            },
            xaxis: {
                title: 'Noise Level',
                gridcolor: '#f1f5f9',
            },
            yaxis: {
                gridcolor: '#f1f5f9',
            },
            shapes: []
        };

        // Draw vertical reference lines for selected noises
        const selectedNoises = getSelectedScanNoises();
        if (selectedNoises && selectedNoises.length) {
            selectedNoises.forEach(noiseVal => {
                commonLayout.shapes.push({
                    type: 'line',
                    xref: 'x',
                    yref: 'paper',
                    x0: noiseVal,
                    x1: noiseVal,
                    y0: 0,
                    y1: 1,
                    line: {
                        color: '#f43f5e',
                        width: 2,
                        dash: 'dash'
                    }
                });
            });
        }

        const errLayout = Object.assign({}, commonLayout, {
            title: `Summary: ${generator} (Error)`,
            yaxis: Object.assign({}, commonLayout.yaxis, { title: 'Median Absolute Error (Hz), IQR band' })
        });

        const measLayout = Object.assign({}, commonLayout, {
            title: `Summary: ${generator} (Measurements)`,
            yaxis: Object.assign({}, commonLayout.yaxis, { title: 'Median Steps, IQR band' })
        });

        const baselineLabel = baselineStrat ? `${baselineStrat} (${baselineConv === 'full' ? 'Full' : (baselineConv === 'freq_converged' ? 'Freq. converged' : 'Converged')})` : 'Baseline';
        const savLayout = Object.assign({}, commonLayout, {
            title: `Measurement Savings vs ${baselineLabel}`,
            yaxis: Object.assign({}, commonLayout.yaxis, { title: 'Median Steps Saved (paired per repeat)' })
        });

        try {
            Plotly.react(document.getElementById('comp-div-summary-err'), errorTraces, errLayout, { responsive: true });
            Plotly.react(document.getElementById('comp-div-summary-meas'), measTraces, measLayout, { responsive: true });
            Plotly.react(document.getElementById('comp-div-summary-savings'), savingsTraces, savLayout, { responsive: true });
        } catch (e) {
            console.error('Failed to render dynamic noise sweep plots:', e);
        }
    }

    // Toggle setup
    // Noise argument the aggregate renderers expect: an array in noise-range
    // mode, otherwise the single effective noise.
    function compareNoisesArg() {
        return isNoiseRangeMode() ? getSelectedScanNoises() : getEffectiveScanNoise();
    }

    // Single source of truth for which Scan/Compare panel is visible and what it
    // renders. All entry points (toggle click, plot refresh, range-mode refresh)
    // route through here so the aggregate axes stay consistent.
    function showScanViewPanels(mode) {
        const repeatView = document.getElementById('scan-repeat-view');
        const speedView = document.getElementById('speed-view');
        const accuracyView = document.getElementById('accuracy-view');
        const failedRunsView = document.getElementById('failed-runs-view');
        const gridStatsView = document.getElementById('grid-stats-view');
        const stoppingRow = document.getElementById('stopping-criteria-row');
        const gen = compareGeneratorsArg();
        const noises = compareNoisesArg();

        if (repeatView) repeatView.style.display = 'none';
        if (speedView) speedView.style.display = 'none';
        if (accuracyView) accuracyView.style.display = 'none';
        if (failedRunsView) failedRunsView.style.display = 'none';
        if (gridStatsView) gridStatsView.style.display = 'none';

        if (mode === 'single') {
            if (repeatView) repeatView.style.display = 'block';
            updateStoppingCriteriaVisibility(currentPlot);
        } else if (mode === 'speed') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            setupTauControl(); syncTauControl();
            if (speedView) {
                speedView.style.display = 'block';
                renderSpeedTab(gen, noises);
            }
        } else if (mode === 'accuracy') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            if (accuracyView) {
                accuracyView.style.display = 'block';
                renderAccuracyTab(gen, noises);
            }
        } else if (mode === 'failed-runs') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            if (failedRunsView) {
                failedRunsView.style.display = 'block';
                renderFailedRunsTab(gen, noises);
            }
        } else if (mode === 'grid-stats') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            if (gridStatsView) {
                gridStatsView.style.display = 'block';
                renderGridStatsTab(gen, controlValue(scanStrategy));
            }
        }
    }

    const scanViewMode = document.getElementById('scan-view-mode');
    if (scanViewMode) {
        scanViewMode.addEventListener('click', (e) => {
            if (e.target.tagName === 'BUTTON' && !e.target.style.display.includes('none')) {
                scanViewMode.querySelectorAll('button').forEach(b => {
                    b.classList.remove('is-active');
                    b.setAttribute('aria-checked', 'false');
                    b.tabIndex = -1;
                });
                e.target.classList.add('is-active');
                e.target.setAttribute('aria-checked', 'true');
                e.target.tabIndex = 0;

                showScanViewPanels(e.target.dataset.value);
            }
        });
        scanViewMode.addEventListener('keydown', (e) => {
            if (e.target.tagName !== 'BUTTON') return;
            const buttons = Array.from(scanViewMode.querySelectorAll('button'));
            const index = buttons.indexOf(e.target);
            let nextIndex = null;
            if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                nextIndex = (index + 1) % buttons.length;
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                nextIndex = (index - 1 + buttons.length) % buttons.length;
            }
            if (nextIndex !== null) {
                e.preventDefault();
                buttons[nextIndex].focus();
                buttons[nextIndex].click();
            }
        });
    }

    const summaryTabBar = document.getElementById('summary-tab-bar');
    if (summaryTabBar) {
        summaryTabBar.addEventListener('click', (e) => {
            if (e.target.tagName === 'BUTTON') {
                summaryTabBar.querySelectorAll('button').forEach(b => {
                    b.classList.remove('is-active');
                    b.setAttribute('aria-selected', 'false');
                    b.tabIndex = -1;
                    const panel = document.getElementById(b.dataset.tab);
                    if (panel) panel.classList.remove('is-active');
                });
                e.target.classList.add('is-active');
                e.target.setAttribute('aria-selected', 'true');
                e.target.tabIndex = 0;
                const activePanel = document.getElementById(e.target.dataset.tab);
                if (activePanel) activePanel.classList.add('is-active');

                // Trigger resize so Plotly fits correctly if it was hidden
                window.dispatchEvent(new Event('resize'));
            }
        });
        summaryTabBar.addEventListener('keydown', (e) => {
            if (e.target.tagName !== 'BUTTON') return;
            const buttons = Array.from(summaryTabBar.querySelectorAll('button'));
            const index = buttons.indexOf(e.target);
            let nextIndex = null;
            if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                nextIndex = (index + 1) % buttons.length;
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                nextIndex = (index - 1 + buttons.length) % buttons.length;
            }
            if (nextIndex !== null) {
                e.preventDefault();
                buttons[nextIndex].focus();
                buttons[nextIndex].click();
            }
        });
    }

    if (scanIframe) {
        scanIframe.addEventListener('load', () => {
            // Keep legend preference when switching locator strategy/repeat (new iframe src).
            applyMeasurementDistributionPreferenceInScanIframe();
            bindScanIframeLegendPreferenceSync();
            // Parse and render narrowed param bounds from the scan figure meta.
            renderNarrowedBoundsFromIframe();
        });
    }

    const narrowedBoundsPanel = document.getElementById('narrowed-bounds-panel');


    function renderNarrowedBoundsPanel(narrowedBounds) {
        if (!narrowedBoundsPanel) return;
        if (!narrowedBounds || typeof narrowedBounds !== 'object' || Object.keys(narrowedBounds).length === 0) {
            narrowedBoundsPanel.hidden = true;
            narrowedBoundsPanel.innerHTML = '';
            return;
        }
        const entries = Object.entries(narrowedBounds)
            .filter(([, range]) => Array.isArray(range) && range.length === 2)
            .map(([name, [lo, hi]]) => ({ name, lo, hi }));
        if (entries.length === 0) {
            narrowedBoundsPanel.hidden = true;
            narrowedBoundsPanel.innerHTML = '';
            return;
        }

        let cardsHtml = '';
        for (const { name, lo, hi } of entries) {
            let selectedVal = undefined;
            if (currentPlot && currentPlot.true_params && currentPlot.true_params.params) {
                const params = currentPlot.true_params.params;
                if (params[name] !== undefined) {
                    selectedVal = params[name];
                } else {
                    const lowerName = name.toLowerCase();
                    const foundKey = Object.keys(params).find(k => k.toLowerCase() === lowerName);
                    if (foundKey) {
                        selectedVal = params[foundKey];
                    }
                }
            }
            if (selectedVal === undefined || typeof selectedVal !== 'number') {
                selectedVal = (lo + hi) / 2;
            }

            let percent = 50;
            if (hi > lo) {
                percent = Math.min(100, Math.max(0, (selectedVal - lo) / (hi - lo) * 100));
            }

            const fmtLo = formatHzValue(name, lo);
            const fmtHi = formatHzValue(name, hi);
            const fmtVal = formatHzValue(name, selectedVal);

            cardsHtml +=
                '<div class="param-slider-card" title="' + name + ': [' + lo + ', ' + hi + '] — Selected: ' + selectedVal + '">' +
                '<div class="param-slider-label">🔍 ' + escapeHtml(name) + '</div>' +
                '<div class="param-slider-wrapper">' +
                '<div class="param-slider-track-bg"></div>' +
                '<div class="param-slider-track-fill" style="width: ' + percent + '%"></div>' +
                '<div class="param-slider-handle" style="left: ' + percent + '%"></div>' +
                '<div class="param-slider-value" style="left: ' + percent + '%">' + fmtVal + '</div>' +
                '</div>' +
                '<div class="param-slider-bounds">' +
                '<span class="param-slider-bound-lo">' + fmtLo + '</span>' +
                '<span class="param-slider-bound-hi">' + fmtHi + '</span>' +
                '</div>' +
                '</div>';
        }

        narrowedBoundsPanel.innerHTML =
            '<div class="param-bounds-header">Sweep-narrowed priors:</div>' +
            '<div class="param-bounds-grid">' + cardsHtml + '</div>';
        narrowedBoundsPanel.hidden = false;
    }

    function renderNarrowedBoundsFromIframe() {
        if (!narrowedBoundsPanel) return;
        // JSON path: read directly from the Plotly graph div
        const scanPlotDiv = document.getElementById('scan-plot-div');
        if (scanPlotDiv && scanPlotDiv.style.display !== 'none' && scanPlotDiv.layout) {
            const meta = scanPlotDiv.layout.meta;
            renderNarrowedBoundsPanel(meta && meta.narrowed_param_bounds);
            return;
        }
        // Legacy HTML iframe path
        if (!scanIframe) return;
        const frameDoc = scanIframe.contentDocument;
        if (!frameDoc) { renderNarrowedBoundsPanel(null); return; }
        const html = frameDoc.documentElement ? frameDoc.documentElement.outerHTML : '';
        if (!html) { renderNarrowedBoundsPanel(null); return; }
        try {
            const m = html.match(/Plotly\.newPlot\(\s*"[^"]+",\s*/);
            if (!m) { renderNarrowedBoundsPanel(null); return; }
            const pos = m.index + m[0].length;
            const dataStr = html.slice(pos);
            let depth = 0, end = 0;
            for (let i = 0; i < dataStr.length; i++) {
                if (dataStr[i] === '[') depth++;
                else if (dataStr[i] === ']') {
                    depth--;
                    if (depth === 0) { end = i + 1; break; }
                }
            }
            let layoutStart = pos + end;
            while (layoutStart < html.length && /[\s,]/.test(html[layoutStart])) layoutStart++;
            if (html[layoutStart] !== '{') { renderNarrowedBoundsPanel(null); return; }
            let ldepth = 0, lend = 0;
            for (let i = layoutStart; i < html.length; i++) {
                if (html[i] === '{') ldepth++;
                else if (html[i] === '}') {
                    ldepth--;
                    if (ldepth === 0) { lend = i + 1; break; }
                }
            }
            if (lend <= layoutStart) { renderNarrowedBoundsPanel(null); return; }
            const layout = JSON.parse(html.slice(layoutStart, lend));
            const meta = layout && layout.meta;
            renderNarrowedBoundsPanel(meta && meta.narrowed_param_bounds);
        } catch (e) {
            renderNarrowedBoundsPanel(null);
        }
    }

    function setupTabs() {
        const tabBar = document.querySelector('.tab-bar');
        const tabPanels = document.querySelectorAll('.tab-panel');

        tabBar.style.display = 'flex';
        tabBar.innerHTML = ''; // Clear existing

        const hasScans = scanPlots.length > 0;

        if (hasScans) {
            const button = document.createElement('button');
            button.className = 'tab-button';
            button.textContent = 'Scan measurements';
            button.dataset.tab = 'scan-section';
            button.setAttribute('role', 'tab');
            button.setAttribute('id', 'tab-scan');
            button.setAttribute('aria-controls', 'scan-section');
            button.setAttribute('aria-selected', 'false');
            tabBar.appendChild(button);
            // Dashboard is now the "Pooled" axis inside the Scan Compare area.
        }

        // Noise Sweep top-level tab removed (moved under Scan View -> Noise Metrics)

        const tabButtons = Array.from(tabBar.querySelectorAll('.tab-button'));
        if (tabButtons.length > 0) {
            tabButtons[0].classList.add('is-active');
            tabButtons[0].setAttribute('aria-selected', 'true');
            tabButtons[0].tabIndex = 0;
            for (let i = 1; i < tabButtons.length; i++) {
                tabButtons[i].tabIndex = -1;
            }
            const initialTabId = tabButtons[0].dataset.tab;
            tabPanels.forEach(panel => {
                if (panel.id === initialTabId) {
                    panel.classList.remove('is-hidden');
                } else {
                    panel.classList.add('is-hidden');
                }
            });
            // With a single top-level section there is nothing to switch between,
            // so hide the lone tab button (the panel stays visible above).
            if (tabButtons.length <= 1) tabBar.style.display = 'none';
        } else {
            tabBar.style.display = 'none';
        }

        tabBar.addEventListener('click', (e) => {
            const target = e.target;
            if (!target.matches('.tab-button')) {
                return;
            }

            tabButtons.forEach(button => {
                button.classList.remove('is-active');
                button.setAttribute('aria-selected', 'false');
                button.tabIndex = -1;
            });
            target.classList.add('is-active');
            target.setAttribute('aria-selected', 'true');
            target.tabIndex = 0;

            tabPanels.forEach(panel => {
                if (panel.id === target.dataset.tab) {
                    panel.classList.remove('is-hidden');
                } else {
                    panel.classList.add('is-hidden');
                }
            });
            // Trigger a window resize event so responsive Plotly charts adjust to their visible containers
            setTimeout(() => {
                window.dispatchEvent(new Event('resize'));
            }, 0);
        });

        tabBar.addEventListener('keydown', (e) => {
            const target = e.target;
            if (!target.matches('.tab-button')) {
                return;
            }
            const index = tabButtons.indexOf(target);
            let nextIndex = null;
            if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                nextIndex = (index + 1) % tabButtons.length;
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                nextIndex = (index - 1 + tabButtons.length) % tabButtons.length;
            }
            if (nextIndex !== null) {
                e.preventDefault();
                tabButtons[nextIndex].focus();
                tabButtons[nextIndex].click();
            }
        });
    }

    // --- Strategy metrics (model_comparison bar charts) ---
    const allAggregatePlots = plots.filter(p => p.type === 'model_comparison' || p.type === 'milestone');

    // updateCompPlots: kept for backward compat; delegates to the new helpers
    function updateCompPlots() {
        const gen = controlValue(scanGenerator);
        initAndRenderNoiseSweepPlots(gen);
    }



    scanGenerator.addEventListener('controlchange', () => {
        lastComparePairIds = { a: null, b: null };
        lastSummaryKey = null;
        updateAllScanControls();
        findAndDisplayPlot();
    });
    scanNoise.addEventListener('controlchange', () => {
        updateNoiseViewMode();
        updateScanStrategyControl();
        updateScanRepeatControl();
        findAndDisplayPlot();
    });
    scanStrategy.addEventListener('controlchange', () => {
        updateScanRepeatControl();
        findAndDisplayPlot();
    });
    scanRepeat.addEventListener('change', () => {
        scanRepeat.dataset.value = scanRepeat.value || '';
        updateRepeatNavButtons();
        findAndDisplayPlot();
    });


    if (scanRepeatPrev) {
        scanRepeatPrev.addEventListener('click', () => {
            selectRepeatByOffset(-1);
        });
    }
    if (scanRepeatNext) {
        scanRepeatNext.addEventListener('click', () => {
            selectRepeatByOffset(1);
        });
    }

    const scanFlipViewToggle = document.getElementById('scan-flip-view-toggle');
    if (scanFlipViewToggle) {
        scanFlipViewToggle.addEventListener('change', () => {
            scanFlipViewEnabled = scanFlipViewToggle.checked;
            const scanPlotDiv = document.getElementById('scan-plot-div');
            if (scanPlotDiv && scanPlotDiv._lastJsonPath) {
                renderPlotFromJson(scanPlotDiv, scanPlotDiv._lastJsonPath);
            }
        });
    }

    if (scanDefault) {
        scanGenerator.dataset.value = scanDefault.generator ?? '';
        
        const defaultNoise = scanDefault.noise ?? '';
        if (defaultNoise) {
            scanNoise.dataset.selectedValues = JSON.stringify([defaultNoise]);
        }

        scanStrategy.dataset.value = scanDefault.strategy ?? '';
        scanRepeat.dataset.value =
            scanDefault.repeat === undefined || scanDefault.repeat === null
                ? ''
                : String(scanDefault.repeat);
    }

    try {
        setupTabs();
        updateAllScanControls();
        findAndDisplayPlot();
    } catch (error) {
        console.error('Error initializing UI controls:', error);
        // Show an error message to the user
        const errorDiv = document.createElement('div');
        errorDiv.setAttribute('role', 'alert');
        errorDiv.style.padding = '20px';
        errorDiv.style.margin = '20px';
        errorDiv.style.border = '1px solid #f5c6cb';
        errorDiv.style.backgroundColor = '#f8d7da';
        errorDiv.style.color = '#721c24';
        errorDiv.style.borderRadius = '4px';
        errorDiv.innerHTML = '<h3>Error: Failed to initialize UI</h3><p>There was a problem initializing the user interface. Please check the console for more details.</p>';
        document.body.appendChild(errorDiv);
    }
}

// Keyboard shortcut, recalc button, and app init are in reload.js
